window.GLOWSIS_BOOK = [{"id": 0, "sections": [{"cls": "unit-flag", "html": "<div class=\"unit-flag\">UNIT 0 · PREPARATION</div>\n  "}, {"cls": "sec-title", "html": "<div class=\"sec-title\"><div class=\"no\">0</div><div><h2>Hangul First Steps</h2><div class=\"en\">한글 — the ABC of Korean</div></div></div>\n\n  <!-- 한글의 비밀 — 상세 시리즈 -->\n  "}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">📜 The Secret of Hangul ① — The Story of Hunminjeongeum</span>\n    <div class=\"g-point\">A letter created by King Sejong for the people</div>\n    <div class=\"g-rule\">Long ago, Koreans used Chinese characters (한자). But hanja was so hard that <b>common people could neither read nor write.</b> King Sejong said, \"The people suffer because they cannot write down what they want to say,\" and created <b>a new alphabet anyone could learn easily.</b> Its name is <b>Hunminjeongeum (훈민정음)</b> — meaning \"the correct sounds for teaching the people.\"</div>\n    <div class=\"h-timeline\">\n      <div class=\"ht-item\"><span class=\"ht-year\">1443</span><span class=\"ht-text\">King Sejong <b>created</b> Hunminjeongeum (28 letters).</span></div>\n      <div class=\"ht-item\"><span class=\"ht-year\">1446</span><span class=\"ht-text\">Published as the <b>Hunminjeongeum Haerye</b> — released to the world with its principle manual.</span></div>\n      <div class=\"ht-item\"><span class=\"ht-year\">1910s</span><span class=\"ht-text\">Scholar Ju Si-gyeong named it <b>Hangul</b> — meaning \"the great and correct script.\"</span></div>\n      <div class=\"ht-item\"><span class=\"ht-year\">오늘</span><span class=\"ht-text\">With 24 letters (14 consonants + 10 vowels), it is recognized as <b>the world's most scientific writing system.</b></span></div>\n    </div>\n  </div>\n\n  "}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">🔤 The Secret of Hangul ② — Consonants are \"Shapes of the Mouth\"!</span>\n    <div class=\"g-point\">Consonants made by imitating the shape of the speech organs</div>\n    <div class=\"g-rule\">The 5 basic consonants were made by copying the <b>shape of the mouth, tongue, and throat as they move when you speak.</b> Just looking at the letter shows you how to pronounce it!</div>\n    <div class=\"hangul-grid\">\n      <div class=\"h-cell highlight\"><div class=\"h-jamo\">ㄱ</div><div class=\"h-rom\">g/k</div><div class=\"h-name\">기역</div><div class=\"h-desc\">Shape of the tongue root blocking the throat</div></div>\n      <div class=\"h-cell highlight\"><div class=\"h-jamo\">ㄴ</div><div class=\"h-rom\">n</div><div class=\"h-name\">니은</div><div class=\"h-desc\">Shape of the tongue tip touching the upper gum</div></div>\n      <div class=\"h-cell highlight\"><div class=\"h-jamo\">ㅁ</div><div class=\"h-rom\">m</div><div class=\"h-name\">미음</div><div class=\"h-desc\">Shape of pursed lips</div></div>\n      <div class=\"h-cell highlight\"><div class=\"h-jamo\">ㅅ</div><div class=\"h-rom\">s</div><div class=\"h-name\">시옷</div><div class=\"h-desc\">Shape of the teeth</div></div>\n      <div class=\"h-cell highlight\"><div class=\"h-jamo\">ㅇ</div><div class=\"h-rom\">ng</div><div class=\"h-name\">이응</div><div class=\"h-desc\">Shape of the throat</div></div>\n    </div>\n    <div class=\"g-rule\">Add a stroke and it becomes a <b>stronger sound</b>: ㄱ→ㅋ, ㄴ→ㄷ→ㅌ, ㅁ→ㅂ→ㅍ, ㅅ→ㅈ→ㅊ. <b>One extra stroke = one stronger sound!</b></div>\n  </div>\n\n  "}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">🌌 The Secret of Hangul ③ — Vowels are \"Heaven, Earth, Human\"!</span>\n    <div class=\"g-point\">Cheonji-in (天地人) — vowels that draw the universe</div>\n    <div class=\"g-rule\">Vowels are made from just <b>three symbols</b>: <b>ㆍ (heaven, a dot)</b> · <b>ㅡ (earth, something flat)</b> · <b>ㅣ (human, a standing figure)</b>. Every vowel is born from how these three are arranged!</div>\n    <div class=\"hangul-grid\">\n      <div class=\"h-cell\"><div class=\"h-jamo\">ㆍ</div><div class=\"h-rom\">(arae-a)</div><div class=\"h-name\">하늘</div><div class=\"h-desc\">Round dot = heaven</div></div>\n      <div class=\"h-cell\"><div class=\"h-jamo\">ㅡ</div><div class=\"h-rom\">eu</div><div class=\"h-name\">땅</div><div class=\"h-desc\">Flat earth</div></div>\n      <div class=\"h-cell\"><div class=\"h-jamo\">ㅣ</div><div class=\"h-rom\">i</div><div class=\"h-name\">사람</div><div class=\"h-desc\">Standing person</div></div>\n    </div>\n    <div class=\"g-rule\">The combination rule:</div>\n    <div class=\"g-ex\">\n      <div class=\"ex\"><span class=\"ko\">ㅣ + ㆍ = ㅏ / ㅓ</span><span class=\"gl\">Heaven (ㆍ) to the right of human (ㅣ) → ㅏ · to the left → ㅓ</span></div>\n      <div class=\"ex\"><span class=\"ko\">ㅡ + ㆍ = ㅗ / ㅜ</span><span class=\"gl\">Heaven above earth (ㅡ) → ㅗ · below → ㅜ</span></div>\n      <div class=\"ex\"><span class=\"ko\">ㅏ + ㅣ = ㅐ / ㅔ</span><span class=\"gl\">When vowels combine, a new vowel is born!</span></div>\n    </div>\n  </div>\n\n  "}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">🧱 The Secret of Hangul ④ — One letter = one syllable block</span>\n    <div class=\"g-point\">Consonant + vowel come together to form \"one letter\"</div>\n    <div class=\"g-rule\">Hangul is not written in a row like the alphabet. Instead, <b>consonants and vowels are stacked in one block</b> to form one syllable. You can even add a final consonant (받침) below!</div>\n    <div class=\"h-block-demo\">\n      <div class=\"h-block\"><div class=\"hb-main\">가</div><div class=\"hb-sub\">ㄱ + ㅏ</div></div>\n      <div class=\"h-block-op\">→</div>\n      <div class=\"h-block\"><div class=\"hb-main\">간</div><div class=\"hb-sub\">ㄱ + ㅏ + ㄴ</div></div>\n      <div class=\"h-block-op\">→</div>\n      <div class=\"h-block\"><div class=\"hb-main\">사랑</div><div class=\"hb-sub\">사 + 랑 · 2 blocks</div></div>\n    </div>\n    <div class=\"g-rule\">Stack blocks to make words, then sentences! Example: <b>사랑해요</b> = 사 + 랑 + 해 + 요 (4 blocks)</div>\n  </div>\n\n  "}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">🏆 The Secret of Hangul ⑤ — A Script Recognized by the World</span>\n    <div class=\"g-point\">\"The most remarkable writing system on Earth\" — world linguists</div>\n    <div class=\"g-rule\">Hunminjeongeum is registered as a <b>UNESCO Memory of the World</b>. American linguist Edwin Reischauer praised it as <b>\"the finest writing system in the world.\"</b> Because sound and letter map 1:1, it is easy to learn!</div>\n    <div class=\"g-ex\">\n      <div class=\"ex\"><span class=\"ko\">한글날 — 10월 9일</span><span class=\"gl\">A Korean national holiday celebrating Hangul!</span></div>\n      <div class=\"ex\"><span class=\"ko\">유네스코 세계기록유산 (1997)</span><span class=\"gl\">Hunminjeongeum Haerye registered</span></div>\n      <div class=\"ex\"><span class=\"ko\">훈민정음 → 한글</span><span class=\"gl\">Today's name was given by Ju Si-gyeong</span></div>\n    </div>\n  </div>\n\n  "}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">🎵 Reading Hangul through K-pop Group Names</span>\n    <div class=\"g-point\">The group names you love — this is how they are written in Korean!</div>\n    <div class=\"g-rule\">Foreign words are written in Hangul by their sound. Let's read K-pop group names together!</div>\n    <div class=\"g-ex\">\n      <div class=\"ex\"><span class=\"ko\">BTS → 비티에스</span><span class=\"gl\">bi-ti-e-seu · 방탄소년단 (Bulletproof Boy Scouts)</span></div>\n      <div class=\"ex\"><span class=\"ko\">BLACKPINK → 블랙핑크</span><span class=\"gl\">beul-laek-ping-keu</span></div>\n      <div class=\"ex\"><span class=\"ko\">TWICE → 트와이스</span><span class=\"gl\">teu-wa-i-seu</span></div>\n      <div class=\"ex\"><span class=\"ko\">NEWJEANS → 뉴진스</span><span class=\"gl\">nyu-jin-seu</span></div>\n      <div class=\"ex\"><span class=\"ko\">글로시스 → GLOWSIS</span><span class=\"gl\">Our group's name! Glow(빛나다) + Sis(언니) = 빛나는 언니들 ✨</span></div>\n    </div>\n  </div>\n\n  "}, {"cls": "practice", "html": "<div class=\"practice\">\n    <div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[1-1] Hangul Sound Match</span></div>\n    <div class=\"p-dir\">Read the Hangul word and choose the correct pronunciation. 🔊 Press the button to hear the sound.</div>\n    <div class=\"p-q\">Read and choose the correct answer. — <span class=\"blank\">뉴진스</span></div>\n    <div class=\"opts\" data-q=\"u0q1\">\n      <button class=\"opt\" onclick=\"checkQ('u0q1',1,this)\"><span class=\"o-idx\">1</span> nu-jin-seu<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u0q1',1,this)\"><span class=\"o-idx\">2</span> nyu-jin-seu<span class=\"o-gl\">✅ 뉴 = nyu</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u0q1',1,this)\"><span class=\"o-idx\">3</span> niu-jin-seu<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u0q1',1,this)\"><span class=\"o-idx\">4</span> nu-jin-ssu<span class=\"o-gl\">❌</span></button></div>\n    <div class=\"p-feedback\" id=\"fb-u0q1\"></div>\n  </div>\n\n  "}, {"cls": "practice", "html": "<div class=\"practice\">\n    <div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[1-2] Group Names in Hangul</span></div>\n    <div class=\"p-dir\">Choose the correct Hangul spelling.</div>\n    <div class=\"p-q\">Read and choose the correct answer. — <b>How do you write \"TWICE\" in Hangul?</b></div>\n    <div class=\"opts\" data-q=\"u0q2\">\n      <button class=\"opt\" onclick=\"checkQ('u0q2',1,this)\"><span class=\"o-idx\">1</span> 트바이스<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u0q2',1,this)\"><span class=\"o-idx\">2</span> 트와이스<span class=\"o-gl\">✅</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u0q2',1,this)\"><span class=\"o-idx\">3</span> 트웨이스<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u0q2',1,this)\"><span class=\"o-idx\">4</span> 트아이스<span class=\"o-gl\">❌</span></button></div>\n    <div class=\"p-feedback\" id=\"fb-u0q2\"></div>\n  </div>\n\n  "}, {"cls": "culture", "html": "<div class=\"culture\">\n    <span class=\"c-label\">🎤 K-POP TIP</span>\n    <h3>How to Call an Idol</h3>\n    <p>In Korea, you add <b>씨</b> after an idol's name. Fans also call them <b>오빠/언니/누나/형</b>!</p>\n    <div class=\"c-tip\">💜 아란 씨, 사랑해요! (Aran, I love you!) — You'll learn cheering phrases in Unit 1.</div>\n  </div>\n\n<!-- ============================================================\n     UNIT 1 — GREETINGS\n     ============================================================ -->"}]}, {"id": 1, "sections": [{"cls": "unit-flag", "html": "<div class=\"unit-flag\">UNIT 1 · GREETINGS</div>\n  "}, {"cls": "sec-title", "html": "<div class=\"sec-title\"><div class=\"no\">1</div><div><h2>Hello!</h2><div class=\"en\">안녕하세요! — Greetings & 이에요/예요</div></div></div>\n  "}, {"cls": "story", "html": "<div class=\"story\">\n    <img class=\"story-art\" src=\"assets/glowsis/aran.png\" alt=\"아란\">\n    <div class=\"story-body\">\n      <span class=\"story-tag\">💿 GLOWSIS STORY · 1/8</span>\n      <h3>아란, 첫 번째 안녕 — \"안녕하세요!\"</h3>\n      <p>글로시스의 첫 연습실! 리더 <b>아란</b>은 한국어로 인사하는 법을 배워요. \"안녕하세요\"라는 말에 팬들의 마음이 열려요. ⭐</p>\n      <span class=\"story-piece\">⭐ GLOW POINT 1/8 획득 — Greetings!</span>\n    </div>\n  </div>\n\n  "}, {"cls": "goals", "html": "<div class=\"goals\">\n    <div class=\"goal\"><span class=\"g-ico\">👋</span> Learn greeting expressions</div>\n    <div class=\"goal\"><span class=\"g-ico\">🔤</span> N은/는 N이에요/예요</div>\n    <div class=\"goal\"><span class=\"g-ico\">🎤</span> Idol greeting phrases</div>\n  </div>\n\n  "}, {"cls": "dialog", "html": "<div class=\"dialog\">\n    <div class=\"d-head\">\n      <span class=\"d-title\">💬 Dialogue 1 — First Meeting</span>\n      <span class=\"d-scene\">🏢 First day at the practice room</span>\n    </div>\n    <div class=\"d-line\"><img src=\"assets/glowsis/aran.png\" alt=\"아란\">\n      <div class=\"d-bubble\"><div class=\"who\">아란</div><div class=\"ko\">안녕하세요! 저는 아란이에요.</div><div class=\"gl\">Hello! I'm Aran.</div></div>\n    </div>\n    <div class=\"d-line me\"><img src=\"assets/glowsis/dahee.png\" alt=\"다희\">\n      <div class=\"d-bubble\"><div class=\"who\">다희</div><div class=\"ko\">안녕하세요! 저는 다희예요.</div><div class=\"gl\">Hello! I'm Dahee.</div></div>\n    </div>\n    <div class=\"d-line\"><img src=\"assets/glowsis/roy.png\" alt=\"로이\">\n      <div class=\"d-bubble\"><div class=\"who\">로이</div><div class=\"ko\">안녕하세요? 저는 로이예요.</div><div class=\"gl\">Hello? I'm Roy.</div></div>\n    </div>\n    <div class=\"d-line\"><img src=\"assets/glowsis/roy.png\" alt=\"로이\">\n      <div class=\"d-bubble\"><div class=\"who\">로이</div><div class=\"ko\">만나서 반가워요! 저는 로이예요.</div><div class=\"gl\">Nice to meet you! I'm Roy.</div></div>\n    </div>\n  </div>\n\n  "}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">GRAMMAR 1</span>\n    <div class=\"g-point\">N은/는 N이에요/예요</div>\n    <div class=\"g-rule\">\"A is B\" — use it to introduce yourself. If the noun ends with a final consonant (받침), use <b>이에요</b>; otherwise use <b>예요</b>.</div>\n    <div class=\"g-ex\">\n      <div class=\"ex\"><span class=\"ko\">저는 아란<b>이에요</b>.</span><span class=\"gl\">아란 ends with ㄴ (final consonant) → 이에요</span></div>\n      <div class=\"ex\"><span class=\"ko\">저는 로이<b>예요</b>.</span><span class=\"gl\">로이 ends with ㅣ (no final consonant) → 예요</span></div>\n      <div class=\"ex\"><span class=\"ko\">저는 가수<b>예요</b>.</span><span class=\"gl\">I am a singer.</span></div>\n    </div>\n  </div>\n\n  "}, {"cls": "teach", "html": "<div class=\"teach\">\n  <span class=\"t-label\">🧑🏫 Teacher's Deep-Dive · 이에요 vs 예요 — two ways to say \"to be\"</span>\n  <div class=\"t-q\"><span class=\"t-ko\">저는 가수예요.</span> <span class=\"t-en\">vs</span> <span class=\"t-ko\">저는 학생이에요.</span></div>\n\n  <div class=\"t-row t-head\">\n    <div class=\"t-why\">Both mean \"to be\" — so why 가수<b class=hl>예요</b> but 학생<b class=hl>이에요</b>? It all comes down to the <b>받침</b>!</div>\n    <div class=\"t-deep\">The 받침 is the <b>final consonant</b> — the sound that \"closes\" a syllable at the end of a word. The rule is simple: if the word ends in a 받침, attach <b class=hl>이에요</b>; if it ends in a <b>vowel</b>, attach <b class=hl>예요</b>. Korean isn't being fussy for no reason — these forms were chosen so words flow smoothly. After a consonant the extra \"이\" sound is kept so it's easy to pronounce, but after a vowel that \"이\" naturally drops away. Just check the very last letter and you can never go wrong!</div>\n  </div>\n\n  <div class=\"t-grid\">\n    <div class=\"t-cell\"><div class=\"t-word\">학생</div><div class=\"t-role\">student<span class=\"t-sub\">(ends in 받침 ㄴ)</span></div><div class=\"t-note\">Has a 받침 → <b class=hl>이에요</b><br>학생 + 이에요 = 학생이에요</div></div>\n    <div class=\"t-op\">+</div>\n    <div class=\"t-cell t-eqcell\"><div class=\"t-word\">이에요</div><div class=\"t-role\">= is<span class=\"t-sub\">(after a 받침)</span></div><div class=\"t-note\">After a consonant the \"이\" is kept, so it becomes <b>이에요</b></div></div>\n    <div class=\"t-op\">→</div>\n    <div class=\"t-cell t-qcell\"><div class=\"t-word\">가수</div><div class=\"t-role\">singer<span class=\"t-sub\">(ends in a vowel)</span></div><div class=\"t-note\">No 받침 → <b class=hl>예요</b><br>가수 + 예요 = 가수예요</div></div>\n    <div class=\"t-op\">+</div>\n    <div class=\"t-cell t-eqcell\"><div class=\"t-word\">예요</div><div class=\"t-role\">= is<span class=\"t-sub\">(after a vowel)</span></div><div class=\"t-note\">After a vowel the \"이\" weakens and drops, so it becomes <b>예요</b></div></div>\n  </div>\n\n  <div class=\"t-insight\"><b class=\"t-i-ko\">Easy trick to remember:</b> \"<b class=hl>받침</b> → <b class=hl>이에요</b>\" — the \"이\" feels like it props up / supports the consonant that came before it. No 받침? Then it shortens down to a quick <b class=hl>예요</b>!</div>\n\n  <div class=\"t-compare\">\n    <div class=\"t-c-a\"><b>Has a 받침 → 이에요</b><br><span class=\"t-ko\">학생<b>이에요</b> · 선생님<b>이에요</b> · 아이돌<b>이에요</b> · 팬<b>이에요</b></span></div>\n    <div class=\"t-c-b\"><b>No 받침 (ends in a vowel) → 예요</b><br><span class=\"t-ko\">가수<b>예요</b> · 로이<b>예요</b> · 채아<b>예요</b> · 무대<b>예요</b></span></div>\n  </div>\n\n  <div class=\"t-tip\">💡 <b>K-POP trick:</b> memorize it with member names — '아란' ends in the 받침 ㄴ, so it's <b>아란이에요</b>; '로이' ends in a vowel, so it's <b>로이예요</b>. Still unsure? Also check the Unit 3 \"이거 뭐예요\" note!</div>\n</div>"}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">GRAMMAR 2</span>\n    <div class=\"g-point\">Greetings</div>\n    <div class=\"g-rule\">These greetings always appear in the TOPIK I listening section.</div>\n    <div class=\"g-ex\">\n      <div class=\"ex\"><span class=\"ko\">안녕하세요!</span><span class=\"gl\">Hello! / Good morning!</span></div>\n      <div class=\"ex\"><span class=\"ko\">만나서 반가워요.</span><span class=\"gl\">Nice to meet you.</span></div>\n      <div class=\"ex\"><span class=\"ko\">안녕히 가세요.</span><span class=\"gl\">Goodbye (to someone leaving).</span></div>\n      <div class=\"ex\"><span class=\"ko\">안녕히 계세요.</span><span class=\"gl\">Goodbye (said by the one leaving).</span></div>\n      <div class=\"ex\"><span class=\"ko\">감사합니다!</span><span class=\"gl\">Thank you!</span></div>\n    </div>\n  </div>\n\n    "}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">GRAMMAR 3</span>\n    <div class=\"g-point\">N입니다 / N입니까? — Formal polite form</div>\n    <div class=\"g-rule\">More formal than 이에요/예요 — used in news, announcements, and stage greetings. <b>입니다</b> = statement, <b>입니까?</b> = question.</div>\n    <div class=\"g-ex\">\n      <div class=\"ex\"><span class=\"ko\">안녕하세요, 글로시스입니다!</span><span class=\"gl\">Hello, we are Glowsis! (stage greeting)</span></div>\n      <div class=\"ex\"><span class=\"ko\">학생입니까?</span><span class=\"gl\">Are you a student?</span></div>\n      <div class=\"ex\"><span class=\"ko\">네, 학생입니다.</span><span class=\"gl\">Yes, I am a student.</span></div>\n    </div>\n  </div>\n\n"}, {"cls": "vocab-grid", "html": "<div class=\"vocab-lab\"><div class=\"vl-toolbar\"><span class=\"vl-hint\">카테고리를 눌러 그림과 함께 공부하세요</span><button class=\"vl-expand\" onclick=\"glowVocabAll()\">모두 펼치기</button></div><div class=\"vl-cat open\" data-tone=\"pink\"><button class=\"vl-cat-head\" onclick=\"glowVocab(this)\"><span class=\"vl-cat-ico\">🎤</span><span class=\"vl-cat-name\">사람 & 아이돌<small>People · 저/이름/가수/친구/팬</small></span><span class=\"vl-cat-count\">5</span><span class=\"vl-cat-arr\">▾</span></button><div class=\"vl-cat-body\"><div class=\"vw-grid\"><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u1_me.webp\" alt=\"저\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('저')\">🔊</button><div class=\"vw-ko\">저</div><div class=\"vw-rom\">jeo</div><div class=\"vw-en\">I (polite)</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u1_nametag.webp\" alt=\"이름\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('이름')\">🔊</button><div class=\"vw-ko\">이름</div><div class=\"vw-rom\">ireum</div><div class=\"vw-en\">name</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u1_singer.webp\" alt=\"가수\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('가수')\">🔊</button><div class=\"vw-ko\">가수</div><div class=\"vw-rom\">gasu</div><div class=\"vw-en\">singer</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u1_friend.webp\" alt=\"친구\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('친구')\">🔊</button><div class=\"vw-ko\">친구</div><div class=\"vw-rom\">chingu</div><div class=\"vw-en\">friend</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u1_fan.webp\" alt=\"팬\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('팬')\">🔊</button><div class=\"vw-ko\">팬</div><div class=\"vw-rom\">paen</div><div class=\"vw-en\">fan</div></div></div></div><div class=\"vs-box\"><div class=\"vs-head\">💬 이 단어로 자주 쓰는 말</div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('저는 아란이에요.')\">🔊</button><div><span class=\"vs-ko\">저는 아란이에요.</span> <span class=\"vs-en\">I am Aran.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('제 이름은 아란이에요.')\">🔊</button><div><span class=\"vs-ko\">제 이름은 아란이에요.</span> <span class=\"vs-en\">My name is Aran.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('저는 가수예요.')\">🔊</button><div><span class=\"vs-ko\">저는 가수예요.</span> <span class=\"vs-en\">I am a singer.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('친구가 많아요.')\">🔊</button><div><span class=\"vs-ko\">친구가 많아요.</span> <span class=\"vs-en\">I have many friends.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('팬이 많아요!')\">🔊</button><div><span class=\"vs-ko\">팬이 많아요!</span> <span class=\"vs-en\">I have many fans!</span></div></div></div><div class=\"vl-link\">🎤 <b>같이 쓰는 말:</b> 이름은 <b>~이에요/예요</b>로 말해요. 가수·친구·팬 뒤엔 '이에요'가 붙어 '사람이 뭔지' 설명해요 (GRAMMAR 1).</div></div></div><div class=\"vl-cat\" data-tone=\"mint\"><button class=\"vl-cat-head\" onclick=\"glowVocab(this)\"><span class=\"vl-cat-ico\">🎵</span><span class=\"vl-cat-name\">노래 & 무대<small>Music · Stage</small></span><span class=\"vl-cat-count\">2</span><span class=\"vl-cat-arr\">▾</span></button><div class=\"vl-cat-body\"><div class=\"vw-grid\"><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u1_song.webp\" alt=\"노래\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('노래')\">🔊</button><div class=\"vw-ko\">노래</div><div class=\"vw-rom\">norae</div><div class=\"vw-en\">song</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u1_stage.webp\" alt=\"무대\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('무대')\">🔊</button><div class=\"vw-ko\">무대</div><div class=\"vw-rom\">mudae</div><div class=\"vw-en\">stage</div></div></div></div><div class=\"vs-box\"><div class=\"vs-head\">💬 이 단어로 자주 쓰는 말</div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('노래를 좋아해요.')\">🔊</button><div><span class=\"vs-ko\">노래를 좋아해요.</span> <span class=\"vs-en\">I like songs.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('무대에 올라요.')\">🔊</button><div><span class=\"vs-ko\">무대에 올라요.</span> <span class=\"vs-en\">I go on stage.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('글로시스가 무대에서 노래해요.')\">🔊</button><div><span class=\"vs-ko\">글로시스가 무대에서 노래해요.</span> <span class=\"vs-en\">Glowsis sings on stage.</span></div></div></div><div class=\"vl-link\">🎵 <b>같이 쓰는 말:</b> 노래는 <b>좋아하다·듣다·부르다</b>, 무대는 <b>오르다·서다</b>와 함께 써요.</div></div></div><div class=\"vl-cat\" data-tone=\"lav\"><button class=\"vl-cat-head\" onclick=\"glowVocab(this)\"><span class=\"vl-cat-ico\">👋</span><span class=\"vl-cat-name\">인사말<small>Greetings · 안녕/감사합니다</small></span><span class=\"vl-cat-count\">2</span><span class=\"vl-cat-arr\">▾</span></button><div class=\"vl-cat-body\"><div class=\"vw-grid\"><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u1_hi.webp\" alt=\"안녕\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('안녕')\">🔊</button><div class=\"vw-ko\">안녕</div><div class=\"vw-rom\">annyeong</div><div class=\"vw-en\">hi / bye (informal)</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u1_thanks.webp\" alt=\"감사합니다\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('감사합니다')\">🔊</button><div class=\"vw-ko\">감사합니다</div><div class=\"vw-rom\">gamsahamnida</div><div class=\"vw-en\">thank you</div></div></div></div><div class=\"vs-box\"><div class=\"vs-head\">💬 이 단어로 자주 쓰는 말</div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('안녕! 잘 지내?')\">🔊</button><div><span class=\"vs-ko\">안녕! 잘 지내?</span> <span class=\"vs-en\">Hi! How are you? (to a friend)</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('안녕하세요!')\">🔊</button><div><span class=\"vs-ko\">안녕하세요!</span> <span class=\"vs-en\">Hello! (polite)</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('감사합니다!')\">🔊</button><div><span class=\"vs-ko\">감사합니다!</span> <span class=\"vs-en\">Thank you! (formal)</span></div></div></div><div class=\"vl-link\">💜 <b>격식 차이:</b> 안녕(친구) ↔ 안녕하세요(어른·처음). 감사합니다는 무대/방송에서도 쓰는 정중한 인사예요.</div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[1-1] Listening — Choose the Greeting</span></div><div class=\"p-dir\">🔊 Listen and pick the natural first greeting.</div><button class=\"p-audio\" onclick=\"tts('안녕하세요! 만나서 반가워요.')\">🔊 Listen</button><div class=\"opts\" data-q=\"u1q3\">\n      <button class=\"opt\" onclick=\"checkQ('u1q3',0,this)\"><span class=\"o-idx\">1</span>안녕하세요!<span class=\"o-gl\">✅ polite hello</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q3',0,this)\"><span class=\"o-idx\">2</span>잘 가!<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q3',0,this)\"><span class=\"o-idx\">3</span>감사합니다.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q3',0,this)\"><span class=\"o-idx\">4</span>뭐 해요?<span class=\"o-gl\">❌</span></button>\n  </div><div class=\"p-feedback\" id=\"fb-u1q3\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">When you meet someone for the first time or you're talking to an elder / higher-up (웃어른), <b class=hl>안녕하세요</b> is the correct greeting. You can tell because it usually comes together with '만나서 반가워요'.</div><div style=\"margin-bottom:5px;\">ⓞ 잘 가! / 안녕 are for <b class=hl>close friends</b>, 감사합니다 means \"thank you\", and 뭐 해요? asks \"what are you doing?\" — none of these is a greeting.</div></div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[1-2] Reading — 받침: 이에요 vs 예요</span></div><div class=\"p-dir\">Choose the correct ending.</div><div class=\"p-q\">저는 아이돌(    ).</div><div class=\"opts\" data-q=\"u1q4\">\n      <button class=\"opt\" onclick=\"checkQ('u1q4',0,this)\"><span class=\"o-idx\">1</span>이에요<span class=\"o-gl\">✅ 아이돌 ends ㄹ → 이에요</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q4',0,this)\"><span class=\"o-idx\">2</span>예요<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q4',0,this)\"><span class=\"o-idx\">3</span>이어요<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q4',0,this)\"><span class=\"o-idx\">4</span>있어요<span class=\"o-gl\">❌</span></button>\n  </div><div class=\"p-feedback\" id=\"fb-u1q4\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">아이돌 ends in the 받침 ㄹ, so it takes <b class=hl>이에요</b>: '저는 아이돌이에요'.</div><div style=\"margin-bottom:5px;\">ⓞ 예요 is only used when there's <b class=hl>no 받침</b> (like 가수예요), and 있어요 is a different word meaning \"there is / to have\". Just look at the last letter and you're done!</div></div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[1-3] Reading — Stage Greeting (입니다)</span></div><div class=\"p-dir\">Read and choose the meaning.</div><div class=\"p-q\"><span class=\"pt-ko\">안녕하세요! 글로시스입니다!</span> (at a music show)</div><div class=\"opts\" data-q=\"u1q5\">\n      <button class=\"opt\" onclick=\"checkQ('u1q5',1,this)\"><span class=\"o-idx\">1</span>I am a star.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q5',1,this)\"><span class=\"o-idx\">2</span>We are Glowsis.<span class=\"o-gl\">✅ 입니다 = formal are</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q5',1,this)\"><span class=\"o-idx\">3</span>Good night.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q5',1,this)\"><span class=\"o-idx\">4</span>See you again.<span class=\"o-gl\">❌</span></button>\n  </div><div class=\"p-feedback\" id=\"fb-u1q5\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\"><b class=hl>입니다</b> is a <b class=hl>more formal, official</b> form of 이에요/예요 — the version used on stage: '우리는 글로시스입니다'.</div><div style=\"margin-bottom:5px;\">ⓞ Like putting on a name tag, it's the stage greeting that announces who you are by attaching the group name + 입니다.</div></div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[1-4] Reading — 받침 없는 단어 (예요)</span></div><div class=\"p-dir\">Choose the correct ending.</div><div class=\"p-q\">저는 글로시스의 리더예요. <b>아란</b> ____. — What fits after 아란?</div><div class=\"opts\" data-q=\"u1q6\">\n      <button class=\"opt\" onclick=\"checkQ('u1q6',0,this)\"><span class=\"o-idx\">1</span>아란이에요<span class=\"o-gl\">✅ 아란 ends ㄴ → 이에요</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q6',0,this)\"><span class=\"o-idx\">2</span>아란예요<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q6',0,this)\"><span class=\"o-idx\">3</span>아란이 있어요<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q6',0,this)\"><span class=\"o-idx\">4</span>아란 좋아요<span class=\"o-gl\">❌</span></button>\n  </div><div class=\"p-feedback\" id=\"fb-u1q6\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">아란 ends in the 받침 <b class=hl>ㄴ</b> → so it takes <b class=hl>이에요</b>. '아란이에요' is correct.</div><div style=\"margin-bottom:5px;\">ⓞ Names ending in a 받침 all take 이에요 — 아란·학생·선생님·팬 all become ~이에요!</div></div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[1-5] Reading — 안녕히 가세요 vs 계세요</span></div><div class=\"p-dir\">누가 누구에게 하는 말인지 고르세요.</div><div class=\"p-q\">손님이 가게를 나갈 때, 주인이 하는 인사는?</div><div class=\"opts\" data-q=\"u1q7\">\n      <button class=\"opt\" onclick=\"checkQ('u1q7',0,this)\"><span class=\"o-idx\">1</span>안녕히 가세요.<span class=\"o-gl\">✅ to the one leaving</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q7',0,this)\"><span class=\"o-idx\">2</span>안녕히 계세요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q7',0,this)\"><span class=\"o-idx\">3</span>잘 자요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q7',0,this)\"><span class=\"o-idx\">4</span>고마워.<span class=\"o-gl\">❌</span></button>\n  </div><div class=\"p-feedback\" id=\"fb-u1q7\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\"><b class=hl>가세요</b> comes from '가시다' — you say it to the person who is <b>leaving</b>; <b class=hl>계세요</b> comes from '계시다 (to stay)' — you say it to the person who is <b>staying</b>.</div><div style=\"margin-bottom:5px;\">💡 If you get confused: when I leave I say '계세요 (please stay)', and the person who stays says '가세요 (go safely)'!</div></div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[1-6] Listening — 이름이 뭐예요?</span></div><div class=\"p-dir\">🔊 듣고 맞는 답을 고르세요.</div><button class=\"p-audio\" onclick=\"tts('이름이 뭐예요? 저는 다희예요.')\">🔊 Listen (이름이 뭐예요?)</button><div class=\"opts\" data-q=\"u1q8\">\n      <button class=\"opt\" onclick=\"checkQ('u1q8',0,this)\"><span class=\"o-idx\">1</span>제 이름은 다희예요.<span class=\"o-gl\">✅ answering name</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q8',0,this)\"><span class=\"o-idx\">2</span>다희가 좋아요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q8',0,this)\"><span class=\"o-idx\">3</span>다희 있어요?<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q8',0,this)\"><span class=\"o-idx\">4</span>안녕히 가세요.<span class=\"o-gl\">❌</span></button>\n  </div><div class=\"p-feedback\" id=\"fb-u1q8\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">'이름이 뭐예요?' is asking for your name → you answer with <span class=pt-ko>제 이름은 다희예요</span>.</div><div style=\"margin-bottom:5px;\">💡 To ask a name say '이름이 뭐예요?'; to answer say '제 이름은 ~이에요/예요' — memorize this and self-introductions are a cinch!</div></div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[1-7] Reading — 감사합니다 뜻</span></div><div class=\"p-dir\">뜻을 고르세요.</div><div class=\"p-q\"><span class=\"pt-ko\">감사합니다!</span></div><div class=\"opts\" data-q=\"u1q9\">\n      <button class=\"opt\" onclick=\"checkQ('u1q9',0,this)\"><span class=\"o-idx\">1</span>Thank you!<span class=\"o-gl\">✅</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q9',0,this)\"><span class=\"o-idx\">2</span>Sorry.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q9',0,this)\"><span class=\"o-idx\">3</span>Hello.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q9',0,this)\"><span class=\"o-idx\">4</span>Goodbye.<span class=\"o-gl\">❌</span></button>\n  </div><div class=\"p-feedback\" id=\"fb-u1q9\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\"><b class=hl>감사합니다</b> = 고맙습니다 = Thank you. It's the polite greeting also used on stage and on broadcasts.</div><div style=\"margin-bottom:5px;\">💡 죄송합니다 = Sorry, 안녕하세요 = Hello. Tell them apart by the ending!</div></div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[1-8] Listening — 자기소개</span></div><div class=\"p-dir\">🔊 듣고 들은 대로 고르세요.</div><button class=\"p-audio\" onclick=\"tts('저는 로이예요. 글로시스예요.')\">🔊 Listen</button><div class=\"opts\" data-q=\"u1q10\">\n      <button class=\"opt\" onclick=\"checkQ('u1q10',0,this)\"><span class=\"o-idx\">1</span>저는 로이예요, 글로시스예요.<span class=\"o-gl\">✅</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q10',0,this)\"><span class=\"o-idx\">2</span>저는 글로시스가 좋아요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q10',0,this)\"><span class=\"o-idx\">3</span>로이는 안녕하세요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q10',0,this)\"><span class=\"o-idx\">4</span>감사합니다, 로이.<span class=\"o-gl\">❌</span></button>\n  </div><div class=\"p-feedback\" id=\"fb-u1q10\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">로이 ends in a vowel → <b class=hl>예요</b>. '저는 로이예요, 글로시스예요' is a self-introduction.</div><div style=\"margin-bottom:5px;\">💡 '~가 좋아요' means \"I like ~\", and 안녕하세요 is just a greeting — neither one is stating your name.</div></div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[1-9] Reading — 나는 ~이에요/예요</span></div><div class=\"p-dir\">가장 자연스러운 자기소개를 고르세요.</div><div class=\"p-q\">글로시스의 <b>팬</b>이 자기소개를 해요:</div><div class=\"opts\" data-q=\"u1q11\">\n      <button class=\"opt\" onclick=\"checkQ('u1q11',2,this)\"><span class=\"o-idx\">1</span>저는 로이예요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q11',2,this)\"><span class=\"o-idx\">2</span>저는 글로시스는 팬예요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q11',2,this)\"><span class=\"o-idx\">3</span>저는 글로시스 팬이에요!<span class=\"o-gl\">✅ 팬 ends ㄴ → 이에요</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q11',2,this)\"><span class=\"o-idx\">4</span>저는 팬이 좋아요.<span class=\"o-gl\">❌</span></button>\n  </div><div class=\"p-feedback\" id=\"fb-u1q11\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">팬 ends in the 받침 <b class=hl>ㄴ</b> → '팬이에요'. So '저는 글로시스 팬이에요' is correct.</div><div style=\"margin-bottom:5px;\">💡 (3) and (2) are almost the same sentence, but the graded answer is (3) — well, actually both end in 팬이에요, so (2) is really also correct writing! (2) only differs by adding a space ('팬 이에요'). That's why this question is marked against the no-space spelling like (3). Just avoid the awkward (1) and (4) and you're fine.</div></div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[1-10] Listening — 헤어질 때</span></div><div class=\"p-dir\">🔊 친구와 헤어질 때 가장 자연스러운 인사는?</div><button class=\"p-audio\" onclick=\"tts('잘 가! 내일 봐!')\">🔊 Listen (잘 가!)</button><div class=\"opts\" data-q=\"u1q12\">\n      <button class=\"opt\" onclick=\"checkQ('u1q12',0,this)\"><span class=\"o-idx\">1</span>잘 가! 내일 봐!<span class=\"o-gl\">✅ informal to a friend</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q12',0,this)\"><span class=\"o-idx\">2</span>안녕히 계세요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q12',0,this)\"><span class=\"o-idx\">3</span>감사합니다.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u1q12',0,this)\"><span class=\"o-idx\">4</span>뭐 해요?<span class=\"o-gl\">❌</span></button>\n  </div><div class=\"p-feedback\" id=\"fb-u1q12\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">With close friends, casual speech like <b class=hl>잘 가</b> is the natural way to say goodbye.</div><div style=\"margin-bottom:5px;\">💡 안녕히 계세요 is for elders or people you've just met. Between friends it's '잘 가, 내일 봐'!</div></div></div></div></div>"}, {"cls": "culture", "html": "<div class=\"culture\">\n    <span class=\"c-label\">🎤 K-POP TIP</span>\n    <h3>Idol Greeting Phrases, Like This!</h3>\n    <p>On music shows, idols greet like this: <b>\"안녕하세요, 글로시스입니다!\"</b> — when a member says their name, fans <b>scream</b>!</p>\n    <div class=\"c-tip\">🎵 Self-intro: \"안녕하세요! 저는 아란이에요. 글로시스의 리더예요.\" — Can you do it like Dahee?</div>\n  </div>\n\n<!-- ============================================================\n     UNIT 2 — SELF-INTRODUCTION\n     ============================================================ -->"}]}, {"id": 2, "sections": [{"cls": "unit-flag", "html": "<div class=\"unit-flag\">UNIT 2 · SELF-INTRODUCTION</div>\n  "}, {"cls": "sec-title", "html": "<div class=\"sec-title\"><div class=\"no\">2</div><div><h2>I'm a Singer</h2><div class=\"en\">저는 가수예요 — Self-introduction · N은/는</div></div></div>\n  "}, {"cls": "story", "html": "<div class=\"story\">\n    <img class=\"story-art\" src=\"assets/glowsis/chaea.png\" alt=\"채아\">\n    <div class=\"story-body\">\n      <span class=\"story-tag\">💿 GLOWSIS STORY · 2/8</span>\n      <h3>채아의 자기소개 — \"저는 채아예요!\"</h3>\n      <p>분위기 메이커 <b>채아</b>는 데뷔 쇼케이스에서 <b>자기소개</b>를 가르쳐요. \"저는 ○○예요!\" — 소개할 때마다 팬들의 함성이 커져요. 💛</p>\n      <span class=\"story-piece\">💛 GLOW POINT 2/8 획득 — Self-introduction!</span>\n    </div>\n  </div>\n"}, {"cls": "goals", "html": "<div class=\"goals\">\n    <div class=\"goal\"><span class=\"g-ico\">🗣️</span> Introduce yourself</div>\n    <div class=\"goal\"><span class=\"g-ico\">🔤</span> 은/는 topic particle</div>\n    <div class=\"goal\"><span class=\"g-ico\">🌍</span> Country & job vocabulary</div>\n  </div>\n\n  "}, {"cls": "dialog", "html": "<div class=\"dialog\">\n    <div class=\"d-head\">\n      <span class=\"d-title\">💬 Dialogue 2 — Debut Interview</span>\n      <span class=\"d-scene\">📺 Debut showcase</span>\n    </div>\n    <div class=\"d-line\"><img src=\"assets/glowsis/chaea.png\" alt=\"채아\">\n      <div class=\"d-bubble\"><div class=\"who\">채아</div><div class=\"ko\">안녕하세요! 저는 채아예요. 글로시스의 보컬이에요.</div><div class=\"gl\">Hello! I'm Chaea. I'm Glowsis's vocalist.</div></div>\n    </div>\n    <div class=\"d-line\"><img src=\"assets/glowsis/roy.png\" alt=\"로이\">\n      <div class=\"d-bubble\"><div class=\"who\">로이</div><div class=\"ko\">저는 로이예요. 글로시스의 막내예요!</div><div class=\"gl\">I'm Roy. I'm Glowsis's maknae (youngest)!</div></div>\n    </div>\n    <div class=\"d-line me\"><img src=\"assets/glowsis/aran.png\" alt=\"아란\">\n      <div class=\"d-bubble\"><div class=\"who\">아란</div><div class=\"ko\">저는 아란이에요. 한국 사람이에요. 글로시스의 리더예요!</div><div class=\"gl\">I'm Aran. I'm Korean. I'm Glowsis's leader!</div></div>\n    </div>\n    <div class=\"d-line\"><img src=\"assets/glowsis/dahee.png\" alt=\"다희\">\n      <div class=\"d-bubble\"><div class=\"who\">다희</div><div class=\"ko\">저는 다희예요. 한국 사람이에요. 래퍼예요.</div><div class=\"gl\">I'm Dahee. I'm Korean. I'm a rapper.</div></div>\n    </div>\n    <div class=\"d-line me\"><img src=\"assets/glowsis/chaea.png\" alt=\"채아\">\n      <div class=\"d-bubble\"><div class=\"who\">채아</div><div class=\"ko\">우리 팬들은 베트남 사람, 일본 사람, 캄보디아 사람이에요!</div><div class=\"gl\">Our fans are Vietnamese, Japanese, and Cambodian!</div></div>\n    </div>\n  </div>\n\n  "}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">GRAMMAR 1</span>\n    <div class=\"g-point\">은/는 — Topic particle</div>\n    <div class=\"g-rule\">Use it to introduce the topic of the sentence. After a final consonant use <b>은</b>, after a vowel use <b>는</b>. It feels like \"as for ~\"!</div>\n    <div class=\"g-ex\">\n      <div class=\"ex\"><span class=\"ko\">저<b>는</b> 채아예요.</span><span class=\"gl\">저 has no final consonant → 는</span></div>\n      <div class=\"ex\"><span class=\"ko\">아란<b>은</b> 한국 사람이에요.</span><span class=\"gl\">아란 has final consonant ㄴ → 은</span></div>\n      <div class=\"ex\"><span class=\"ko\">이 노래<b>는</b> 좋아요.</span><span class=\"gl\">As for this song, I like it.</span></div>\n    </div>\n  </div>\n\n  "}, {"cls": "teach", "html": "<div class=\"teach\">\n  <span class=\"t-label\">🧑‍🏫 Teacher's Deep-Dive · 은/는 — the topic particle</span>\n  <div class=\"t-q\"><span class=\"t-ko\">저는 가수예요.</span> <span class=\"t-en\">= \"As for me, I'm a singer.\"</span></div>\n\n  <div class=\"t-row t-head\">\n    <div class=\"t-why\">Why isn't just <b>가수예요</b> enough? Why do we need <b>은/는</b>?</div>\n    <div class=\"t-deep\">\n      If you only say '<b>가수예요</b>', it sounds like a plain answer — like you're replying \"yes / no\" to a question someone just asked you. Adding <b class=hl>은/는</b> sets the <b>topic</b>: it announces \"<b>I (저)</b> am about to talk about myself now!\" That's why a self-introduction almost always opens with '<b>저는 ~</b>'.\n    </div>\n  </div>\n\n  <div class=\"t-grid\">\n    <div class=\"t-cell\">\n      <div class=\"t-word\">저</div>\n      <div class=\"t-role\">I <span class=\"t-sub\">(polite \"me\")</span></div>\n      <div class=\"t-note\">Ends in the vowel ㅓ.<br>No 받침 → <b class=hl>는</b></div>\n    </div>\n    <div class=\"t-op\">+</div>\n    <div class=\"t-cell t-qcell\">\n      <div class=\"t-word\">는</div>\n      <div class=\"t-role\">topic marker<span class=\"t-sub\">(주제 조사)</span></div>\n      <div class=\"t-note\">Shows <b>who</b> we're about to talk about.<br>'저는' = \"as for me\"</div>\n    </div>\n    <div class=\"t-op\">+</div>\n    <div class=\"t-cell\">\n      <div class=\"t-word\">가수</div>\n      <div class=\"t-role\">singer<span class=\"t-sub\">(what I am)</span></div>\n      <div class=\"t-note\">The thing being explained.<br>Ends in a vowel → <b>예요</b></div>\n    </div>\n    <div class=\"t-op\">+</div>\n    <div class=\"t-cell t-eqcell\">\n      <div class=\"t-word\">예요</div>\n      <div class=\"t-role\">= is <span class=\"t-sub\">(이다)</span></div>\n      <div class=\"t-note\">Connects the explanation<br>about the topic (저)</div>\n    </div>\n  </div>\n\n  <div class=\"t-insight\">\n    <b class=\"t-i-ko\">은/는 = \"as for / speaking of …\"</b>. With a 받침 use <b class=hl>은</b> (한국 사람<small>은</small>·학생<small>은</small>); without a 받침 (a vowel) use <b class=hl>는</b> (저<small>는</small>·의사<small>는</small>). For self-introductions, the '<b>저는 …이에요/예요</b>' pattern is the golden answer!\n  </div>\n\n  <div class=\"t-compare\">\n    <div class=\"t-c-a\"><b>With 은/는 — self-introduction · introducing</b><br><span class=\"t-ko\">저<b>는</b> 보컬이에요. 저<b>는</b> 한국 사람이에요.</span><br><span class=\"t-en\">\"I'm starting to talk about myself\" — a natural opening line</span></div>\n    <div class=\"t-c-b\"><b>Without 은/는 — short answers</b><br><span class=\"t-ko\">네, 가수예요. / 보컬이에요.</span><br><span class=\"t-en\">Only OK when the topic is already set by a question</span></div>\n  </div>\n\n  <div class=\"t-tip\">\n    💡 <b>Memory trick:</b> 은/는 is a <b>camera spotlight</b> — it tells us who's being lit up right now. '<b>저는</b>' = the spotlight is on me! That's exactly why idols open their stage intros with lines like \"저는 샛별의 보컬 서연이에요!\"\n  </div>\n</div>"}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">GRAMMAR 2</span>\n    <div class=\"g-point\">N이에요/예요 — Talking about Jobs & Nationalities</div>\n    <div class=\"g-rule\">Self-introduction = name + nationality + job + role! Connect them all with <b>이에요/예요</b>.</div>\n    <div class=\"g-ex\">\n      <div class=\"ex\"><span class=\"ko\">저는 가수예요.</span><span class=\"gl\">I am a singer.</span></div>\n      <div class=\"ex\"><span class=\"ko\">저는 학생이에요.</span><span class=\"gl\">I am a student.</span></div>\n      <div class=\"ex\"><span class=\"ko\">저는 캄보디아 사람이에요.</span><span class=\"gl\">I am Cambodian.</span></div>\n    </div>\n  </div>\n\n    "}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">GRAMMAR 3</span>\n    <div class=\"g-point\">N도 — \"also / too\"</div>\n    <div class=\"g-rule\">Add <b>도</b> after a noun to say \"also, too\". It replaces 은/는 and 이/가. A favorite in TOPIK I!</div>\n    <div class=\"g-ex\">\n      <div class=\"ex\"><span class=\"ko\">저는 가수<b>도</b>예요.</span><span class=\"gl\">I am also a singer.</span></div>\n      <div class=\"ex\"><span class=\"ko\">다희<b>도</b> 한국 사람이에요.</span><span class=\"gl\">Dahee is also Korean.</span></div>\n      <div class=\"ex\"><span class=\"ko\">노래<b>도</b> 좋아해요.</span><span class=\"gl\">I like singing too.</span></div>\n    </div>\n  </div>\n\n"}, {"cls": "vocab-lab", "html": "<div class=\"vocab-lab\"><div class=\"vl-toolbar\"><span class=\"vl-hint\">카테고리를 눌러 그림과 함께 공부하세요</span><button class=\"vl-expand\" onclick=\"glowVocabAll()\">모두 펼치기</button></div><div class=\"vl-cat open\" data-tone=\"pink\"><button class=\"vl-cat-head\" onclick=\"glowVocab(this)\"><span class=\"vl-cat-ico\">🎤</span><span class=\"vl-cat-name\">아이돌 포지션<small>Idol Roles · 보컬/래퍼/리더/막내/댄서</small></span><span class=\"vl-cat-count\">5</span><span class=\"vl-cat-arr\">▾</span></button><div class=\"vl-cat-body\"><div class=\"vw-grid\"><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u2_vocal.webp\" alt=\"보컬\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('보컬')\">🔊</button><div class=\"vw-ko\">보컬</div><div class=\"vw-rom\">bokeol</div><div class=\"vw-en\">vocalist</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u2_rapper.webp\" alt=\"래퍼\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('래퍼')\">🔊</button><div class=\"vw-ko\">래퍼</div><div class=\"vw-rom\">raepeo</div><div class=\"vw-en\">rapper</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u2_leader.webp\" alt=\"리더\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('리더')\">🔊</button><div class=\"vw-ko\">리더</div><div class=\"vw-rom\">rideo</div><div class=\"vw-en\">leader</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u2_maknae.webp\" alt=\"막내\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('막내')\">🔊</button><div class=\"vw-ko\">막내</div><div class=\"vw-rom\">mangnae</div><div class=\"vw-en\">youngest</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u2_dancer.webp\" alt=\"댄서\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('댄서')\">🔊</button><div class=\"vw-ko\">댄서</div><div class=\"vw-rom\">daenseo</div><div class=\"vw-en\">dancer</div></div></div></div><div class=\"vs-box\"><div class=\"vs-head\">💬 이 단어로 자주 쓰는 말</div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('지우는 샛별의 리더예요.')\">🔊</button><div><span class=\"vs-ko\">지우는 샛별의 리더예요.</span> <span class=\"vs-en\">Jiu is Saetbyeol's leader.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('유나는 댄서예요.')\">🔊</button><div><span class=\"vs-ko\">유나는 댄서예요.</span> <span class=\"vs-en\">Yuna is a dancer.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('지훈은 래퍼예요.')\">🔊</button><div><span class=\"vs-ko\">지훈은 래퍼예요.</span> <span class=\"vs-en\">Jihun is a rapper.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('하준은 막내예요.')\">🔊</button><div><span class=\"vs-ko\">하준은 막내예요.</span> <span class=\"vs-en\">Hajun is the youngest.</span></div></div></div><div class=\"vl-link\">🎤 <b>같이 쓰는 말:</b> 포지션은 그룹 안에서 멤버의 <b>역할</b>이에요. 리더·보컬·래퍼·댄서·막내가 다 있으면 한 그룹이 돼요. 소개할 땐 '<b>~은/는 ~예요</b>'로 말해요 (GRAMMAR 1).</div></div></div><div class=\"vl-cat\" data-tone=\"mint\"><button class=\"vl-cat-head\" onclick=\"glowVocab(this)\"><span class=\"vl-cat-ico\">💼</span><span class=\"vl-cat-name\">직업<small>Jobs · 학생/회사원/선생님/의사/경찰</small></span><span class=\"vl-cat-count\">5</span><span class=\"vl-cat-arr\">▾</span></button><div class=\"vl-cat-body\"><div class=\"vw-grid\"><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u2_student.webp\" alt=\"학생\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('학생')\">🔊</button><div class=\"vw-ko\">학생</div><div class=\"vw-rom\">haksaeng</div><div class=\"vw-en\">student</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u2_worker.webp\" alt=\"회사원\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('회사원')\">🔊</button><div class=\"vw-ko\">회사원</div><div class=\"vw-rom\">hoesawon</div><div class=\"vw-en\">office worker</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u2_teacher.webp\" alt=\"선생님\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('선생님')\">🔊</button><div class=\"vw-ko\">선생님</div><div class=\"vw-rom\">seonsaengnim</div><div class=\"vw-en\">teacher</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u2_doctor.webp\" alt=\"의사\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('의사')\">🔊</button><div class=\"vw-ko\">의사</div><div class=\"vw-rom\">uisa</div><div class=\"vw-en\">doctor</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u2_police.webp\" alt=\"경찰\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('경찰')\">🔊</button><div class=\"vw-ko\">경찰</div><div class=\"vw-rom\">gyeongchal</div><div class=\"vw-en\">police</div></div></div></div><div class=\"vs-box\"><div class=\"vs-head\">💬 이 단어로 자주 쓰는 말</div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('저는 학생이에요.')\">🔊</button><div><span class=\"vs-ko\">저는 학생이에요.</span> <span class=\"vs-en\">I am a student.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('아버지는 회사원이에요.')\">🔊</button><div><span class=\"vs-ko\">아버지는 회사원이에요.</span> <span class=\"vs-en\">My father is an office worker.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('어머니는 선생님이에요.')\">🔊</button><div><span class=\"vs-ko\">어머니는 선생님이에요.</span> <span class=\"vs-en\">My mother is a teacher.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('우리 삼촌은 의사예요.')\">🔊</button><div><span class=\"vs-ko\">우리 삼촌은 의사예요.</span> <span class=\"vs-en\">My uncle is a doctor.</span></div></div></div><div class=\"vl-link\">💼 <b>같이 쓰는 말:</b> 직업을 말할 땐 '<b>~은/는</b> 직업<small>이에요/예요</small>'예요. 받침 있는 직업(학생·회사원·선생님·경찰)은 <b>이에요</b>, 받침 없는 의사는 <b>예요</b> (GRAMMAR 2).</div></div></div><div class=\"vl-cat\" data-tone=\"lav\"><button class=\"vl-cat-head\" onclick=\"glowVocab(this)\"><span class=\"vl-cat-ico\">🌍</span><span class=\"vl-cat-name\">국가 & 국적<small>Countries & People · 어디 사람이에요?</small></span><span class=\"vl-cat-count\">4</span><span class=\"vl-cat-arr\">▾</span></button><div class=\"vl-cat-body\"><div class=\"vw-grid\"><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u2_korean.webp\" alt=\"한국 사람\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('한국 사람')\">🔊</button><div class=\"vw-ko\">한국 사람</div><div class=\"vw-rom\">hanguk saram</div><div class=\"vw-en\">Korean person</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u2_vietnam.webp\" alt=\"베트남\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('베트남')\">🔊</button><div class=\"vw-ko\">베트남</div><div class=\"vw-rom\">betnam</div><div class=\"vw-en\">Vietnam</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u2_japan.webp\" alt=\"일본\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('일본')\">🔊</button><div class=\"vw-ko\">일본</div><div class=\"vw-rom\">ilbon</div><div class=\"vw-en\">Japan</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u2_cambodia.webp\" alt=\"캄보디아\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('캄보디아')\">🔊</button><div class=\"vw-ko\">캄보디아</div><div class=\"vw-rom\">kambodia</div><div class=\"vw-en\">Cambodia</div></div></div></div><div class=\"vs-box\"><div class=\"vs-head\">💬 이 단어로 자주 쓰는 말</div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('저는 한국 사람이에요.')\">🔊</button><div><span class=\"vs-ko\">저는 한국 사람이에요.</span> <span class=\"vs-en\">I am Korean.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('유나는 베트남 사람이에요.')\">🔊</button><div><span class=\"vs-ko\">유나는 베트남 사람이에요.</span> <span class=\"vs-en\">Yuna is Vietnamese.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('지훈이는 일본 사람이에요.')\">🔊</button><div><span class=\"vs-ko\">지훈이는 일본 사람이에요.</span> <span class=\"vs-en\">Jihun is Japanese.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('그 친구는 캄보디아 사람이에요.')\">🔊</button><div><span class=\"vs-ko\">그 친구는 캄보디아 사람이에요.</span> <span class=\"vs-en\">That friend is Cambodian.</span></div></div></div><div class=\"vl-link\">🌍 <b>같이 쓰는 말:</b> <b>나라 + 사람 = 국적</b>. 한국 사람·베트남 사람… 이렇게 말해요. '<b>어느 나라 사람이에요?</b>'라고 물으면 이 단어로 답하면 돼요! (GRAMMAR 2)</div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK 읽기</span><span class=\"p-title\">[2-1] Reading — Who is Yuna?</span></div><div class=\"p-dir\">다음을 읽고 물음에 답하세요.</div><div class=\"p-q\">안녕하세요! 저는 유나예요. 저는 <span class=\"pt-ko\">베트남</span> 사람이에요. 샛별의 <span class=\"pt-ko\">댄서</span>예요.<br><br><b>물음:</b> 유나 씨는 어느 나라 사람이에요?</div><div class=\"opts\" data-q=\"u2q1\"><button class=\"opt\" onclick=\"checkQ('u2q1',1,this)\"><span class=\"o-idx\">1</span>한국 사람<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q1',1,this)\"><span class=\"o-idx\">2</span>베트남 사람<span class=\"o-gl\">✅ Vietnam · the country Yuna named</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q1',1,this)\"><span class=\"o-idx\">3</span>일본 사람<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q1',1,this)\"><span class=\"o-idx\">4</span>캄보디아 사람<span class=\"o-gl\">❌</span></button>\n  </div><div class=\"p-feedback\" id=\"fb-u2q1\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">In the passage Yuna says <span class=\"pt-ko\">\"저는 <b class=hl>베트남</b> 사람이에요\"</span>. So the answer is <b class=hl>베트남 사람</b>.</div><div style=\"margin-bottom:5px;\">ⓞ 한국·일본·캄보디아 are countries that come up with the other members in the passage — you must pick the country <b>Yuna</b> said. Nationalities are expressed as <b class=hl>country + 사람</b>.</div></div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK 읽기</span><span class=\"p-title\">[2-2] Reading — 도 (also/too)</span></div><div class=\"p-dir\">알맞은 조사를 고르세요.</div><div class=\"p-q\">저는 학생이에요. 제 친구 <span class=\"pt-ko\">____</span> 학생이에요. <span class=\"p-en\">(My friend is a student <b>too</b>.)</span></div><div class=\"opts\" data-q=\"u2q2\"><button class=\"opt\" onclick=\"checkQ('u2q2',1,this)\"><span class=\"o-idx\">1</span>는<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q2',1,this)\"><span class=\"o-idx\">2</span>도<span class=\"o-gl\">✅ too · my friend is also a student</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q2',1,this)\"><span class=\"o-idx\">3</span>이에요<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q2',1,this)\"><span class=\"o-idx\">4</span>은<span class=\"o-gl\">❌</span></button>\n  </div><div class=\"p-feedback\" id=\"fb-u2q2\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">\"제 친구<b class=hl>도</b> 학생이에요\" = \"my friend is a student <b class=hl>too</b>.\" <span class=\"pt-ko\">도</span> is the particle used to <b class=hl>add the same fact</b>, like '나도, 너도, 그것도' (me too, you too, that too).</div><div style=\"margin-bottom:5px;\">ⓞ This sentence is <b>adding</b> the point that \"the friend is also a student,\" so it needs <b class=hl>도</b>, not 은/는 (topic). 은/는 introduces a new topic; 도 adds \"same / also.\"</div></div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK 읽기</span><span class=\"p-title\">[2-3] Reading — 이에요 or 예요?</span></div><div class=\"p-dir\">바르게 연결한 것을 고르세요.</div><div class=\"p-q\">그분은 <span class=\"pt-ko\">선생님</span>이에요. “선생님”은 받침이 있으니까 뒤에 오는 말은?</div><div class=\"opts\" data-q=\"u2q3\"><button class=\"opt\" onclick=\"checkQ('u2q3',0,this)\"><span class=\"o-idx\">1</span>선생님이에요<span class=\"o-gl\">✅ teacher + 이에요 (받침 ㅁ)</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q3',0,this)\"><span class=\"o-idx\">2</span>선생님예요<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q3',0,this)\"><span class=\"o-idx\">3</span>선생님 이예요<span class=\"o-gl\">❌ common learner slip</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q3',0,this)\"><span class=\"o-idx\">4</span>선생님이어요<span class=\"o-gl\">❌</span></button>\n  </div><div class=\"p-feedback\" id=\"fb-u2q3\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">선생님 ends with the syllable <span class=\"pt-ko\">님</span>, whose last letter is the <b class=hl>받침 ㅁ</b>. After a 받침 we use <b class=hl>이에요</b> → so \"선생님<b class=hl>이에요</b>\" is correct.</div><div style=\"margin-bottom:5px;\">ⓞ \"선생님<b class=hl>예요</b>\" is wrong. <b>예요</b> only follows words with <b>no</b> 받침 (가수→가수<b class=hl>예요</b>). And <b class=hl>이예요</b> is a very common beginner mistake — don't write it!</div></div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK 읽기</span><span class=\"p-title\">[2-4] Reading — Correct Self-Intro</span></div><div class=\"p-dir\">가장 자연스러운 자기소개 문장을 고르세요.</div><div class=\"p-q\">샛별의 보컬 <b>서연</b> 씨의 자기소개를 만들어요. 어느 문장이 가장 자연스러워요?</div><div class=\"opts\" data-q=\"u2q4\"><button class=\"opt\" onclick=\"checkQ('u2q4',1,this)\"><span class=\"o-idx\">1</span>나 서연 보컬이에요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q4',1,this)\"><span class=\"o-idx\">2</span>저는 서연이에요. 저는 보컬이에요.<span class=\"o-gl\">✅ Two clear 저는… sentences</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q4',1,this)\"><span class=\"o-idx\">3</span>저 서연이에요 보컬예요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q4',1,this)\"><span class=\"o-idx\">4</span>서연이에요 저는 보컬이에요.<span class=\"o-gl\">❌</span></button>\n  </div><div class=\"p-feedback\" id=\"fb-u2q4\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">A natural self-introduction follows the order <b class=hl>name → role (job)</b>, giving each part its own <span class=\"pt-ko\">저는</span> and splitting it into <b class=hl>two sentences</b>: \"저는 서연이에요. 저는 보컬이에요.\"</div><div style=\"margin-bottom:5px;\">ⓞ ① drops the particle and sounds awkward; ③ and ④ don't pin down a clear topic, so they feel messy. When introducing yourself, use 은/는 to <b>set the topic</b>, then explain it with 이에요/예요.</div></div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK 읽기</span><span class=\"p-title\">[2-5] Reading — What does she do?</span></div><div class=\"p-dir\">다음을 읽고 물음에 답하세요.</div><div class=\"p-q\">서연: 어머니는 무슨 일을 하세요?<br>유나: 어머니는 병원에서 일하세요. <span class=\"pt-ko\">의사</span>예요.<br><br><b>물음:</b> 유나 어머니의 직업은 무엇이에요?</div><div class=\"opts\" data-q=\"u2q5\"><button class=\"opt\" onclick=\"checkQ('u2q5',0,this)\"><span class=\"o-idx\">1</span>의사<span class=\"o-gl\">✅ doctor · 받침 없음 → 예요</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q5',0,this)\"><span class=\"o-idx\">2</span>회사원<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q5',0,this)\"><span class=\"o-idx\">3</span>선생님<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q5',0,this)\"><span class=\"o-idx\">4</span>경찰<span class=\"o-gl\">❌</span></button>\n  </div><div class=\"p-feedback\" id=\"fb-u2q5\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">Yuna says \"어머니는 <span class=\"pt-ko\">의사</span><b class=hl>예요</b>\". So the answer is <b class=hl>의사</b>.</div><div style=\"margin-bottom:5px;\">ⓞ The hint \"병원에서 일해요\" (she works at a hospital) also points to a doctor. 의사 has no 받침, so it takes <b class=hl>예요</b> — words with a 받침 like 회사원·선생님·경찰 take <b class=hl>이에요</b>.</div></div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK 읽기</span><span class=\"p-title\">[2-6] Reading — Nationalities</span></div><div class=\"p-dir\">다음을 읽고 물음에 답하세요.</div><div class=\"p-q\">하준: 우리 멤버들은 다 한국 사람이에요?<br>지우: 아니요. 지훈은 <span class=\"pt-ko\">일본</span> 사람이고, 저는 한국 사람이에요.<br><br><b>물음:</b> 지훈 씨는 어느 나라 사람이에요?</div><div class=\"opts\" data-q=\"u2q6\"><button class=\"opt\" onclick=\"checkQ('u2q6',1,this)\"><span class=\"o-idx\">1</span>한국 사람<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q6',1,this)\"><span class=\"o-idx\">2</span>일본 사람<span class=\"o-gl\">✅ Japan · what Jihun is</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q6',1,this)\"><span class=\"o-idx\">3</span>베트남 사람<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q6',1,this)\"><span class=\"o-idx\">4</span>캄보디아 사람<span class=\"o-gl\">❌</span></button>\n  </div><div class=\"p-feedback\" id=\"fb-u2q6\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">Jiwoo says \"지훈<b class=hl>은</b> <span class=\"pt-ko\">일본</span> 사람\". So 지훈 is <b class=hl>일본 사람</b>. Here <span class=\"pt-ko\">은</span> marks a <b>contrast</b>: \"unlike me (a Korean), 지훈 is…\".</div><div style=\"margin-bottom:5px;\">ⓞ Watch out — the passage swaps people and countries around mid-sentence. <b class=hl>Match each name (topic) with the right nationality</b> as you read.</div></div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK 듣기</span><span class=\"p-title\">[2-7] Listening — His Job</span></div><div class=\"p-dir\">🔊 듣고 물음에 답하세요.</div><button class=\"p-audio\" onclick=\"tts('저는 하준이에요. 저는 막내예요. 리더는 지우 오빠예요.')\">🔊 Listen</button><div class=\"opts\" data-q=\"u2q7\"><button class=\"opt\" onclick=\"checkQ('u2q7',1,this)\"><span class=\"o-idx\">1</span>리더<span class=\"o-gl\">❌ 지우의 역할이에요</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q7',1,this)\"><span class=\"o-idx\">2</span>막내<span class=\"o-gl\">✅ Hajun said '저는 막내예요'</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q7',1,this)\"><span class=\"o-idx\">3</span>보컬<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q7',1,this)\"><span class=\"o-idx\">4</span>댄서<span class=\"o-gl\">❌</span></button>\n  </div><div class=\"p-feedback\" id=\"fb-u2q7\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">In the listening, 하준 says <span class=\"pt-ko\">\"저는 <b class=hl>막내</b>예요\"</span> himself. So the answer is <b class=hl>막내</b>.</div><div style=\"margin-bottom:5px;\">ⓞ It's easy to get confused because the passage also says \"리더는 지우 오빠예요\". Just follow the <b class=hl>topic (은/는)</b> to see <b class=hl>who is who</b> — 하준 = 막내, 지우 = 리더.</div></div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK 듣기</span><span class=\"p-title\">[2-8] Listening — Nationality</span></div><div class=\"p-dir\">🔊 듣고 물음에 답하세요.</div><button class=\"p-audio\" onclick=\"tts('저는 캄보디아 사람이에요. 그런데 제 친구는 베트남 사람이에요.')\">🔊 Listen</button><div class=\"opts\" data-q=\"u2q8\"><button class=\"opt\" onclick=\"checkQ('u2q8',1,this)\"><span class=\"o-idx\">1</span>베트남 사람<span class=\"o-gl\">❌ the friend</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q8',1,this)\"><span class=\"o-idx\">2</span>캄보디아 사람<span class=\"o-gl\">✅ the speaker said '저는 캄보디아 사람'</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q8',1,this)\"><span class=\"o-idx\">3</span>한국 사람<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q8',1,this)\"><span class=\"o-idx\">4</span>일본 사람<span class=\"o-gl\">❌</span></button>\n  </div><div class=\"p-feedback\" id=\"fb-u2q8\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">The speaker says <span class=\"pt-ko\">\"저는 <b class=hl>캄보디아</b> 사람이에요\"</span>. So the answer is <b class=hl>캄보디아 사람</b>.</div><div style=\"margin-bottom:5px;\">ⓞ It also says \"제 친구<b class=hl>는</b> 베트남 사람\" (my friend is Vietnamese). Don't mix up the <b class=hl>topics</b> — \"저는\" (me) vs \"제 친구는\" (my friend).</div></div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK 듣기</span><span class=\"p-title\">[2-9] Listening — Her Job</span></div><div class=\"p-dir\">🔊 듣고 물음에 답하세요.</div><button class=\"p-audio\" onclick=\"tts('어머니는 선생님이에요. 아버지도 선생님이에요.')\">🔊 Listen</button><div class=\"opts\" data-q=\"u2q9\"><button class=\"opt\" onclick=\"checkQ('u2q9',2,this)\"><span class=\"o-idx\">1</span>회사원<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q9',2,this)\"><span class=\"o-idx\">2</span>의사<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q9',2,this)\"><span class=\"o-idx\">3</span>선생님<span class=\"o-gl\">✅ both parents — '아버지도' = father too</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q9',2,this)\"><span class=\"o-idx\">4</span>경찰<span class=\"o-gl\">❌</span></button>\n  </div><div class=\"p-feedback\" id=\"fb-u2q9\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">Mother is <span class=\"pt-ko\">선생님</span><b class=hl>이에요</b> (받침 ㅁ → 이에요). And since it says \"아버지<b class=hl>도</b> 선생님이에요\", father is also a teacher.</div><div style=\"margin-bottom:5px;\">ⓞ <span class=\"pt-ko\">도</span> adds \"also / too,\" meaning the same thing applies to someone else. Here it tells us father has the <b class=hl>same job as mother (선생님)</b>. Words with no 받침 like 회사원·의사·경찰 take 예요.</div></div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK 듣기</span><span class=\"p-title\">[2-10] Listening — Korean person too</span></div><div class=\"p-dir\">🔊 듣고 물음에 답하세요.</div><button class=\"p-audio\" onclick=\"tts('서연은 한국 사람이에요. 지우도 한국 사람이에요.')\">🔊 Listen</button><div class=\"opts\" data-q=\"u2q10\"><button class=\"opt\" onclick=\"checkQ('u2q10',0,this)\"><span class=\"o-idx\">1</span>두 사람 다 한국 사람이에요.<span class=\"o-gl\">✅ Both — 서연 and 지우 are Korean</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q10',0,this)\"><span class=\"o-idx\">2</span>서연만 한국 사람이에요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q10',0,this)\"><span class=\"o-idx\">3</span>지우만 한국 사람이에요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u2q10',0,this)\"><span class=\"o-idx\">4</span>둘 다 일본 사람이에요.<span class=\"o-gl\">❌</span></button>\n  </div><div class=\"p-feedback\" id=\"fb-u2q10\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">\"서연은 한국 사람이에요. 지우<b class=hl>도</b> 한국 사람이에요.\" — <span class=\"pt-ko\">도</span> means 지우 is <b class=hl>the same as 서연</b>. So they are both Korean (한국 사람).</div><div style=\"margin-bottom:5px;\">ⓞ The key is catching the '도' in \"지우<b class=hl>도</b>\". If it had been \"지우<b class=hl>는</b>\", you'd need to check for brand-new information; but 도 <b class=hl>adds sameness</b>.</div></div></div></div></div>"}, {"cls": "culture", "html": "<div class=\"culture\">\n    <span class=\"c-label\">🎤 K-POP TIP</span>\n    <h3>Self-Introduction Challenge!</h3>\n    <p>Idols make a <b>self-introduction phrase</b> when they debut. Shall we make one too?</p>\n    <div class=\"c-tip\">✍️ \"안녕하세요! 저는 ○○예요. ○○ 사람이에요. ○○이에요!\" — Fill in your name, country, and job!</div>\n  </div>\n\n<!-- ============================================================\n     UNIT 3 — THINGS\n     ============================================================ -->"}]}, {"id": 3, "sections": [{"cls": "unit-flag", "html": "<div class=\"unit-flag\">UNIT 3 · THINGS</div>\n  "}, {"cls": "sec-title", "html": "<div class=\"sec-title\"><div class=\"no\">3</div><div><h2>What is This?</h2><div class=\"en\">이거 뭐예요? — Things · 이/그/저</div></div></div>\n  "}, {"cls": "story", "html": "<div class=\"story\">\n    <img class=\"story-art\" src=\"assets/glowsis/dahee.png\" alt=\"다희\">\n    <div class=\"story-body\">\n      <span class=\"story-tag\">💿 GLOWSIS STORY · 3/8</span>\n      <h3>다희의 보물 상자 — \"이거 뭐예요?\"</h3>\n      <p>메인댄서 <b>다희</b>는 신기한 물건들을 발견해요 — 응원봉, 포토카드, 앨범! 물건의 이름을 알면 팬들에게 자랑할 수 있어요. \"이거 뭐예요?\"라고 물어보세요! ⭐</p>\n      <span class=\"story-piece\">🎁 GLOW POINT 3/8 획득 — Things!</span>\n    </div>\n  </div>\n"}, {"cls": "goals", "html": "<div class=\"goals\">\n    <div class=\"goal\"><span class=\"g-ico\">👉</span> 이/그/저 demonstratives</div>\n    <div class=\"goal\"><span class=\"g-ico\">🎒</span> Object vocabulary</div>\n    <div class=\"goal\"><span class=\"g-ico\">✅</span> 있어요/없어요</div>\n  </div>\n\n  "}, {"cls": "dialog", "html": "<div class=\"dialog\">\n    <div class=\"d-head\">\n      <span class=\"d-title\">💬 Dialogue 3 — Making Merch</span>\n      <span class=\"d-scene\">🎁 Merch meeting</span>\n    </div>\n    <div class=\"d-line\"><img src=\"assets/glowsis/roy.png\" alt=\"로이\">\n      <div class=\"d-bubble\"><div class=\"who\">로이</div><div class=\"ko\">이거 뭐예요?</div><div class=\"gl\">What is this?</div></div>\n    </div>\n    <div class=\"d-line\"><img src=\"assets/glowsis/aran.png\" alt=\"아란\">\n      <div class=\"d-bubble\"><div class=\"who\">아란</div><div class=\"ko\">이거는 응원봉이에요. 팬들이 콘서트에서 써요.</div><div class=\"gl\">This is a light stick. Fans use it at concerts.</div></div>\n    </div>\n    <div class=\"d-line\"><img src=\"assets/glowsis/dahee.png\" alt=\"다희\">\n      <div class=\"d-bubble\"><div class=\"who\">다희</div><div class=\"ko\">그거는 뭐예요?</div><div class=\"gl\">What is that?</div></div>\n    </div>\n    <div class=\"d-line\"><img src=\"assets/glowsis/chaea.png\" alt=\"채아\">\n      <div class=\"d-bubble\"><div class=\"who\">채아</div><div class=\"ko\">그거는 앨범이에요. 사진하고 포토카드가 있어요.</div><div class=\"gl\">That is an album. It has photos and photocards.</div></div>\n    </div>\n    <div class=\"d-line\"><img src=\"assets/glowsis/dahee.png\" alt=\"다희\">\n      <div class=\"d-bubble\"><div class=\"who\">다희</div><div class=\"ko\">포토카드 있어요? 저거 주세요!</div><div class=\"gl\">Is there a photocard? Give me that one!</div></div>\n    </div>\n  </div>\n\n  "}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">GRAMMAR 1</span>\n    <div class=\"g-point\">이/그/저 — This / That / That over there</div>\n    <div class=\"g-rule\">이 = something near me, 그 = something near you, 저 = something far from both.</div>\n    <div class=\"g-ex\">\n      <div class=\"ex\"><span class=\"ko\">이거는 응원봉이에요.</span><span class=\"gl\">This (near me) is a light stick.</span></div>\n      <div class=\"ex\"><span class=\"ko\">그거는 앨범이에요.</span><span class=\"gl\">That (near you) is an album.</span></div>\n      <div class=\"ex\"><span class=\"ko\">저거 주세요.</span><span class=\"gl\">Please give me that one (over there).</span></div>\n    </div>\n  </div>\n\n  "}, {"cls": "teach", "html": "<div class=\"teach\">\n  <span class=\"t-label\">🧑‍🏫 Teacher's Deep-Dive · Breaking Down \"이거 뭐예요?\"</span>\n  <div class=\"t-q\"><span class=\"t-ko\">이거 뭐예요?</span> <span class=\"t-en\">= \"What is this?\"</span></div>\n\n  <div class=\"t-row t-head\">\n    <div class=\"t-why\">Why do Koreans say it this way? How is it different from the textbook form?</div>\n    <div class=\"t-deep\">\n      Following the textbook, you'd expect <b>\"이거<b class=hl>는</b> 뭐예요?\"</b>. But in real spoken Korean, when you're asking while pointing at something in front of you, <b>\"이거 뭐예요?\"</b> — with the topic particle <b>은/는 dropped</b> — sounds much more natural.\n    </div>\n  </div>\n\n  <div class=\"t-grid\">\n    <div class=\"t-cell\">\n      <div class=\"t-word\">이거</div>\n      <div class=\"t-role\">this <span class=\"t-sub\">(nearby thing)</span></div>\n      <div class=\"t-note\">The spoken, shortened form of '이것'.<br><b>이+것 → 이거</b> (것 → 거)</div>\n    </div>\n    <div class=\"t-op\">+</div>\n    <div class=\"t-cell t-qcell\">\n      <div class=\"t-word\">뭐</div>\n      <div class=\"t-role\">what <span class=\"t-sub\">(question word)</span></div>\n      <div class=\"t-note\">The short form of '무엇'.<br>뭐예요? = \"뭐 + 예요?\"</div>\n    </div>\n    <div class=\"t-op\">+</div>\n    <div class=\"t-cell t-eqcell\">\n      <div class=\"t-word\">예요</div>\n      <div class=\"t-role\">= is <span class=\"t-sub\">(이다)</span></div>\n      <div class=\"t-note\">뭐<b>예요</b> = 무엇<b>이에요</b>.<br>After a vowel, so it becomes '예요'</div>\n    </div>\n  </div>\n\n  <div class=\"t-insight\">\n    <b class=\"t-i-ko\">\"이거 뭐예요?\"</b> = 이거<b>(는)</b> 뭐예요? → When the thing you're asking about is <b>right in front of you</b>, you don't attach 은/는. You're already pointing at it, so everyone knows <b>which thing</b> you mean — you're just asking <b>what it is</b>.\n  </div>\n\n  <div class=\"t-compare\">\n    <div class=\"t-c-a\"><b>Textbook (standard)</b><br><span class=\"t-ko\">이거<b>는</b> 뭐예요?</span><br><span class=\"t-en\">Grammar-book answer · when analyzing word by word</span></div>\n    <div class=\"t-c-b\"><b>Real speech (natural)</b><br><span class=\"t-ko\">이거 뭐예요?</span><br><span class=\"t-en\">Everyday way to point and ask ✨</span></div>\n  </div>\n\n  <div class=\"t-tip\">\n    💡 <b>Memory trick:</b> In English \"What is this?\", what = <b>뭐</b>, is = <b>예요</b>(이다), this = <b>이거</b>. But Korean puts <b>the topic first, then the explanation</b> — \"이거(가 뭔지) = 뭐예요\". So it comes out as \"이거 뭐예요?\"!\n  </div>\n</div>"}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">GRAMMAR 2</span>\n    <div class=\"g-point\">N이/가 있어요 · 없어요 — There is / There isn't</div>\n    <div class=\"g-rule\">Essential for TOPIK I! <b>있어요</b> = 있다 (to exist / to have), <b>없어요</b> = 없다 (to not exist).</div>\n    <div class=\"g-ex\">\n      <div class=\"ex\"><span class=\"ko\">포토카드가 있어요.</span><span class=\"gl\">There is a photocard.</span></div>\n      <div class=\"ex\"><span class=\"ko\">시간이 없어요.</span><span class=\"gl\">I don't have time.</span></div>\n      <div class=\"ex\"><span class=\"ko\">연습실에 거울이 있어요.</span><span class=\"gl\">There is a mirror in the practice room.</span></div>\n    </div>\n  </div>\n\n    "}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">GRAMMAR 3</span>\n    <div class=\"g-point\">N 주세요 — \"Please give me N\"</div>\n    <div class=\"g-rule\">Ask for something politely. Essential for shopping, ordering, and merch booths!</div>\n    <div class=\"g-ex\">\n      <div class=\"ex\"><span class=\"ko\">포토카드 주세요.</span><span class=\"gl\">Please give me the photocard.</span></div>\n      <div class=\"ex\"><span class=\"ko\">물 주세요.</span><span class=\"gl\">Please give me water.</span></div>\n      <div class=\"ex\"><span class=\"ko\">저거 주세요.</span><span class=\"gl\">Please give me that one (over there).</span></div>\n    </div>\n  </div>\n\n"}, {"cls": "vocab-grid", "html": "<div class=\"vocab-lab\"><div class=\"vl-toolbar\"><span class=\"vl-hint\">카테고리를 눌러 그림과 함께 공부하세요</span><button class=\"vl-expand\" onclick=\"glowVocabAll()\">모두 펼치기</button></div><div class=\"vl-cat open\" data-tone=\"pink\"><button class=\"vl-cat-head\" onclick=\"glowVocab(this)\"><span class=\"vl-cat-ico\">🎁</span><span class=\"vl-cat-name\">팬 굿즈<small>Fan Goods · 콘서트에서 쓰는 물건</small></span><span class=\"vl-cat-count\">4</span><span class=\"vl-cat-arr\">▾</span></button><div class=\"vl-cat-body\"><div class=\"vw-grid\"><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/lightstick.webp\"\" alt=\"응원봉\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('응원봉')\">🔊</button><div class=\"vw-ko\">응원봉</div><div class=\"vw-rom\">eungwonbong</div><div class=\"vw-en\">light stick</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/album.webp\"\" alt=\"앨범\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('앨범')\">🔊</button><div class=\"vw-ko\">앨범</div><div class=\"vw-rom\">aelbeom</div><div class=\"vw-en\">album</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/photocard.webp\"\" alt=\"포토카드\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('포토카드')\">🔊</button><div class=\"vw-ko\">포토카드</div><div class=\"vw-rom\">potokadeu</div><div class=\"vw-en\">photocard</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/tshirt.webp\"\" alt=\"티셔츠\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('티셔츠')\">🔊</button><div class=\"vw-ko\">티셔츠</div><div class=\"vw-rom\">tisyeocheu</div><div class=\"vw-en\">T-shirt</div></div></div></div><div class=\"vs-box\"><div class=\"vs-head\">💬 이 단어로 자주 쓰는 말</div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('응원봉을 들어요.')\">🔊</button><div><span class=\"vs-ko\">응원봉을 들어요.</span> <span class=\"vs-en\">Hold up the light stick.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('콘서트에서 응원봉을 들어요.')\">🔊</button><div><span class=\"vs-ko\">콘서트에서 응원봉을 들어요.</span> <span class=\"vs-en\">We wave light sticks at the concert.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('앨범을 사요.')\">🔊</button><div><span class=\"vs-ko\">앨범을 사요.</span> <span class=\"vs-en\">I buy an album.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('앨범에 좋은 노래가 있어요.')\">🔊</button><div><span class=\"vs-ko\">앨범에 좋은 노래가 있어요.</span> <span class=\"vs-en\">The album has great songs.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('포토카드를 모아요.')\">🔊</button><div><span class=\"vs-ko\">포토카드를 모아요.</span> <span class=\"vs-en\">I collect photocards.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('글로시스 티셔츠를 입어요.')\">🔊</button><div><span class=\"vs-ko\">글로시스 티셔츠를 입어요.</span> <span class=\"vs-en\">I wear the Glowsis T-shirt.</span></div></div></div><div class=\"vl-link\">🤝 <b>같이 쓰는 말:</b> 응원봉은 <b>들다</b>, 앨범은 <b>사다·듣다</b>, 포토카드는 <b>모으다</b>와 잘 어울려요. 팬 굿즈는 전부 <b>콘서트</b>에서 나와요!</div></div></div><div class=\"vl-cat\" data-tone=\"mint\"><button class=\"vl-cat-head\" onclick=\"glowVocab(this)\"><span class=\"vl-cat-ico\">🎧</span><span class=\"vl-cat-name\">폰 & 음악<small>Phone · Music · 사진 찍기</small></span><span class=\"vl-cat-count\">3</span><span class=\"vl-cat-arr\">▾</span></button><div class=\"vl-cat-body\"><div class=\"vw-grid\"><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/phone.webp\"\" alt=\"휴대폰\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('휴대폰')\">🔊</button><div class=\"vw-ko\">휴대폰</div><div class=\"vw-rom\">hyudaepon</div><div class=\"vw-en\">cell phone</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/earphones.webp\"\" alt=\"이어폰\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('이어폰')\">🔊</button><div class=\"vw-ko\">이어폰</div><div class=\"vw-rom\">ieopon</div><div class=\"vw-en\">earphones</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/photo.webp\"\" alt=\"사진\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('사진')\">🔊</button><div class=\"vw-ko\">사진</div><div class=\"vw-rom\">sajin</div><div class=\"vw-en\">photo</div></div></div></div><div class=\"vs-box\"><div class=\"vs-head\">💬 이 단어로 자주 쓰는 말</div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('휴대폰으로 사진을 찍어요.')\">🔊</button><div><span class=\"vs-ko\">휴대폰으로 사진을 찍어요.</span> <span class=\"vs-en\">I take photos with my phone.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('휴대폰이 없어요.')\">🔊</button><div><span class=\"vs-ko\">휴대폰이 없어요.</span> <span class=\"vs-en\">I don't have a phone.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('이어폰으로 음악을 들어요.')\">🔊</button><div><span class=\"vs-ko\">이어폰으로 음악을 들어요.</span> <span class=\"vs-en\">I listen to music with earphones.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('사진을 찍어요.')\">🔊</button><div><span class=\"vs-ko\">사진을 찍어요.</span> <span class=\"vs-en\">I take a picture.</span></div></div></div><div class=\"vl-link\">🖼️ <b>같은 짝:</b> 포토카드(굿즈)는 '아이돌 사진'이에요. <b>사진 ↔ 포토카드</b> — 둘 다 '찍고 / 모아요'. 이어폰으로는 <b>노래</b>를 들어요.</div></div></div><div class=\"vl-cat\" data-tone=\"sky\"><button class=\"vl-cat-head\" onclick=\"glowVocab(this)\"><span class=\"vl-cat-ico\">🎒</span><span class=\"vl-cat-name\">매일 챙기는 것<small>Daily carry · 있어요/없어요</small></span><span class=\"vl-cat-count\">4</span><span class=\"vl-cat-arr\">▾</span></button><div class=\"vl-cat-body\"><div class=\"vw-grid\"><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/bag.webp\"\" alt=\"가방\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('가방')\">🔊</button><div class=\"vw-ko\">가방</div><div class=\"vw-rom\">gabang</div><div class=\"vw-en\">bag</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/umbrella.webp\"\" alt=\"우산\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('우산')\">🔊</button><div class=\"vw-ko\">우산</div><div class=\"vw-rom\">usan</div><div class=\"vw-en\">umbrella</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/key.webp\"\" alt=\"열쇠\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('열쇠')\">🔊</button><div class=\"vw-ko\">열쇠</div><div class=\"vw-rom\">yeolsoe</div><div class=\"vw-en\">key</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/watch.webp\"\" alt=\"시계\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('시계')\">🔊</button><div class=\"vw-ko\">시계</div><div class=\"vw-rom\">sigye</div><div class=\"vw-en\">watch, clock</div></div></div></div><div class=\"vs-box\"><div class=\"vs-head\">💬 이 단어로 자주 쓰는 말</div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('가방에 책이 있어요.')\">🔊</button><div><span class=\"vs-ko\">가방에 책이 있어요.</span> <span class=\"vs-en\">There's a book in the bag.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('가방에 열쇠가 있어요?')\">🔊</button><div><span class=\"vs-ko\">가방에 열쇠가 있어요?</span> <span class=\"vs-en\">Is there a key in the bag?</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('비가 와요. 우산을 써요.')\">🔊</button><div><span class=\"vs-ko\">비가 와요. 우산을 써요.</span> <span class=\"vs-en\">It's raining. Use an umbrella.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('열쇠가 없어요!')\">🔊</button><div><span class=\"vs-ko\">열쇠가 없어요!</span> <span class=\"vs-en\">I don't have the key!</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('시계를 봐요. 몇 시예요?')\">🔊</button><div><span class=\"vs-ko\">시계를 봐요. 몇 시예요?</span> <span class=\"vs-en\">Look at the watch. What time is it?</span></div></div></div><div class=\"vl-link\">⚖️ <b>반대 짝:</b> 있어요 ↔ 없어요 (GRAMMAR 2). 가방 <b>에</b> 열쇠가 있어요 / 없어요 — 다 '가지고 있냐 없냐'로 말해요.</div></div></div><div class=\"vl-cat\" data-tone=\"lav\"><button class=\"vl-cat-head\" onclick=\"glowVocab(this)\"><span class=\"vl-cat-ico\">📖</span><span class=\"vl-cat-name\">공부 & 연습<small>Study & practice room</small></span><span class=\"vl-cat-count\">2</span><span class=\"vl-cat-arr\">▾</span></button><div class=\"vl-cat-body\"><div class=\"vw-grid\"><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/book.webp\"\" alt=\"책\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('책')\">🔊</button><div class=\"vw-ko\">책</div><div class=\"vw-rom\">chaek</div><div class=\"vw-en\">book</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/mirror.webp\"\" alt=\"거울\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('거울')\">🔊</button><div class=\"vw-ko\">거울</div><div class=\"vw-rom\">geoul</div><div class=\"vw-en\">mirror</div></div></div></div><div class=\"vs-box\"><div class=\"vs-head\">💬 이 단어로 자주 쓰는 말</div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('책을 읽어요.')\">🔊</button><div><span class=\"vs-ko\">책을 읽어요.</span> <span class=\"vs-en\">I read a book.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('연습실에서 거울을 봐요.')\">🔊</button><div><span class=\"vs-ko\">연습실에서 거울을 봐요.</span> <span class=\"vs-en\">I look in the mirror in the practice room.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('거울을 보며 춤을 춰요.')\">🔊</button><div><span class=\"vs-ko\">거울을 보며 춤을 춰요.</span> <span class=\"vs-en\">I dance while watching the mirror.</span></div></div></div><div class=\"vl-link\">🔤 <b>둘 다 보는 물건:</b> 책은 <b>읽다</b>, 거울은 <b>보다</b>. 글로시스는 연습실 거울로 춤을 연습해요!</div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n  <div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[3-1] Reading — Picture: 있어요 vs 없어요</span></div>\n  <div class=\"p-dir\">Look at the picture and choose the correct sentence.</div>\n  <div class=\"p-q\">[그림: 기타 1개] Read and choose the correct answer.</div>\n  <div class=\"opts\" data-q=\"u3q1\">\n      <button class=\"opt\" onclick=\"checkQ('u3q1',0,this)\"><span class=\"o-idx\">1</span>기타가 있어요.<span class=\"o-gl\">✅ There IS a guitar — the picture has one.</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q1',0,this)\"><span class=\"o-idx\">2</span>기타가 없어요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q1',0,this)\"><span class=\"o-idx\">3</span>기타가 좋아요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q1',0,this)\"><span class=\"o-idx\">4</span>기타가 커요.<span class=\"o-gl\">❌</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u3q1\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">The photo shows one guitar, so \"there is\" = <b class=\"hl\">있어요</b> is the answer.</div><div style=\"margin-bottom:5px;\">ⓞ <b class=\"hl\">없어요</b> = not there, <b class=\"hl\">좋아요</b> = is good, <b class=\"hl\">커요</b> = is big — none of them mean existence.</div><div style=\"margin-bottom:5px;\">💡 <span class=\"pt-ko\">이/가 있어요</span> = \"there is ~\". If you can see the thing, it's 있어요!</div></div></div></div>\n</div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n  <div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[3-2] Listening — 가방에 책이 있어요</span></div>\n  <div class=\"p-dir\">🔊 Listen and choose what you hear.</div>\n  <button class=\"p-audio\" onclick=\"tts('가방에 책이 있어요.')\">🔊 Listen</button>\n  <div class=\"opts\" data-q=\"u3q2\">\n      <button class=\"opt\" onclick=\"checkQ('u3q2',0,this)\"><span class=\"o-idx\">1</span>가방에 책이 있어요.<span class=\"o-gl\">✅ You heard 책이 있어요</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q2',0,this)\"><span class=\"o-idx\">2</span>가방에 책이 없어요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q2',0,this)\"><span class=\"o-idx\">3</span>가방이 책이에요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q2',0,this)\"><span class=\"o-idx\">4</span>책이 가방이에요.<span class=\"o-gl\">❌</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u3q2\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">The audio says <span class=\"pt-ko\">가방에 책이 있어요</span> — \"there is a book (in the bag)\".</div><div style=\"margin-bottom:5px;\">ⓞ <b class=\"hl\">없어요</b> means the opposite, and <b class=\"hl\">이에요</b> means \"= is\" — it doesn't fit here.</div><div style=\"margin-bottom:5px;\">💡 In listening, catch the ending <b class=\"hl\">있어요/없어요/이에요</b> first!</div></div></div></div>\n</div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n  <div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[3-3] Listening — At the Merch Booth (주세요)</span></div>\n  <div class=\"p-dir\">🔊 Listen and choose what the fan says at the booth.</div>\n  <button class=\"p-audio\" onclick=\"tts('포토카드 주세요.')\">🔊 Listen</button>\n  <div class=\"opts\" data-q=\"u3q3\">\n      <button class=\"opt\" onclick=\"checkQ('u3q3',0,this)\"><span class=\"o-idx\">1</span>포토카드 주세요.<span class=\"o-gl\">✅ Please give me the photocard.</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q3',0,this)\"><span class=\"o-idx\">2</span>포토카드 있어요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q3',0,this)\"><span class=\"o-idx\">3</span>포토카드 없어요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q3',0,this)\"><span class=\"o-idx\">4</span>포토카드 좋아요.<span class=\"o-gl\">❌</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u3q3\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">To ask for something in a shop, use <span class=\"pt-ko\">주세요</span> (주다 = to give).</div><div style=\"margin-bottom:5px;\">ⓞ 있어요/없어요 = existence, 좋아요 = a feeling — none of them is a request for <b class=\"hl\">something to be handed over</b>.</div><div style=\"margin-bottom:5px;\">💡 At a shop or merch booth, always use <b class=\"hl\">… 주세요</b>!</div></div></div></div>\n</div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n  <div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[3-4] Reading — 이거/그거/저거 고르기</span></div>\n  <div class=\"p-dir\">아란이 옆에서 사진을 들고 “이거는 뭐예요?”라고 물어요. 사진이 아란에게 가까이 있어요.</div>\n  <div class=\"p-q\">사진이 <b>말하는 사람에게 가까울 때</b> 뭐라고 하나요?</div>\n  <div class=\"opts\" data-q=\"u3q4\">\n      <button class=\"opt\" onclick=\"checkQ('u3q4',0,this)\"><span class=\"o-idx\">1</span>이거는 뭐예요?<span class=\"o-gl\">✅ near me → 이</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q4',0,this)\"><span class=\"o-idx\">2</span>그거는 뭐예요?<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q4',0,this)\"><span class=\"o-idx\">3</span>저거는 뭐예요?<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q4',0,this)\"><span class=\"o-idx\">4</span>뭐는 이거예요?<span class=\"o-gl\">❌</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u3q4\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">If the photo is <b class=\"hl\">near me</b>, it's <span class=\"pt-ko\">이거</span>!</div><div style=\"margin-bottom:5px;\">ⓞ <b class=\"hl\">그거</b> = near the other person, <b class=\"hl\">저거</b> = far from both of us.</div><div style=\"margin-bottom:5px;\">💡 Distance: right in front of me = <b class=\"hl\">이</b>, next to you = <b class=\"hl\">그</b>, way over there = <b class=\"hl\">저</b>!</div></div></div></div>\n</div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n  <div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[3-5] Reading — 물건 어휘 (거울 있어요)</span></div>\n  <div class=\"p-dir\">다음 문장을 읽고 뜻을 고르세요.</div>\n  <div class=\"p-q\"><span class=\"pt-ko\">연습실에 거울이 있어요.</span></div>\n  <div class=\"opts\" data-q=\"u3q5\">\n      <button class=\"opt\" onclick=\"checkQ('u3q5',2,this)\"><span class=\"o-idx\">1</span>There is no mirror.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q5',2,this)\"><span class=\"o-idx\">2</span>The mirror is an idol.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q5',2,this)\"><span class=\"o-idx\">3</span>There is a mirror in the practice room.<span class=\"o-gl\">✅ 거울이 있어요</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q5',2,this)\"><span class=\"o-idx\">4</span>I like the mirror.<span class=\"o-gl\">❌</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u3q5\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\"><span class=\"pt-ko\">연습실에</span> = in the practice room, <span class=\"pt-ko\">거울이 있어요</span> = there is a mirror.</div><div style=\"margin-bottom:5px;\">ⓞ <b class=\"hl\">있어요</b> = there is, <b class=\"hl\">이에요</b> = is, <b class=\"hl\">좋아요</b> = is good — all different meanings.</div><div style=\"margin-bottom:5px;\">💡 <b class=\"hl\">장소에 ~이/가 있어요</b> = \"there is ~ in a place\".</div></div></div></div>\n</div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n  <div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[3-6] Listening — 저거 주세요</span></div>\n  <div class=\"p-dir\">🔊 판매대 멀리 있는 앨범을 가리키며 말해요.</div>\n  <button class=\"p-audio\" onclick=\"tts('저거 주세요.')\">🔊 Listen (저거 주세요)</button>\n  <div class=\"opts\" data-q=\"u3q6\">\n      <button class=\"opt\" onclick=\"checkQ('u3q6',0,this)\"><span class=\"o-idx\">1</span>저거 주세요.<span class=\"o-gl\">✅ far → 저 + 주세요</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q6',0,this)\"><span class=\"o-idx\">2</span>이거 주세요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q6',0,this)\"><span class=\"o-idx\">3</span>그거 있어요?<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q6',0,this)\"><span class=\"o-idx\">4</span>저거 좋아요.<span class=\"o-gl\">❌</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u3q6\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">If you want something far away, say <span class=\"pt-ko\">저거 주세요</span>! (<b class=\"hl\">저</b> = far)</div><div style=\"margin-bottom:5px;\">ⓞ If it's far, you must use <b class=\"hl\">저</b>. 이 = next to me, 그 = next to you.</div><div style=\"margin-bottom:5px;\">💡 Perfect for pointing at an album far across the booth!</div></div></div></div>\n</div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n  <div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[3-7] Reading — 부정문 (없어요)</span></div>\n  <div class=\"p-dir\">다음을 읽고 뜻을 고르세요.</div>\n  <div class=\"p-q\"><span class=\"pt-ko\">시간이 없어요.</span></div>\n  <div class=\"opts\" data-q=\"u3q7\">\n      <button class=\"opt\" onclick=\"checkQ('u3q7',0,this)\"><span class=\"o-idx\">1</span>There is no time.<span class=\"o-gl\">✅ 없어요 = is not</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q7',0,this)\"><span class=\"o-idx\">2</span>There is time.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q7',0,this)\"><span class=\"o-idx\">3</span>Time is fun.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q7',0,this)\"><span class=\"o-idx\">4</span>I have a watch.<span class=\"o-gl\">❌</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u3q7\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\"><span class=\"pt-ko\">없어요</span> = \"없다\" (to not exist). → \"시간이 없다\" = There is no time.</div><div style=\"margin-bottom:5px;\">ⓞ <b class=\"hl\">있어요 ↔ 없어요</b> are an opposite pair — if one is true, the other isn't.</div><div style=\"margin-bottom:5px;\">💡 This is exactly the 있어요/없어요 from GRAMMAR 2.</div></div></div></div>\n</div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n  <div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[3-8] Reading — 저거 (picture)</span></div>\n  <div class=\"p-dir\">그림을 보고 맞는 문장을 고르세요.</div>\n  <div class=\"p-q\">[그림: 저 멀리 축구공] — 공이 우리에게서 멀어요.</div>\n  <div class=\"opts\" data-q=\"u3q8\">\n      <button class=\"opt\" onclick=\"checkQ('u3q8',2,this)\"><span class=\"o-idx\">1</span>이거는 공이에요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q8',2,this)\"><span class=\"o-idx\">2</span>그거는 공이에요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q8',2,this)\"><span class=\"o-idx\">3</span>저거는 공이에요.<span class=\"o-gl\">✅ far → 저</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q8',2,this)\"><span class=\"o-idx\">4</span>공은 없어요.<span class=\"o-gl\">❌</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u3q8\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">The ball is <b class=\"hl\">far from both of us</b>, so <span class=\"pt-ko\">저거</span> is right.</div><div style=\"margin-bottom:5px;\">ⓞ You can see it, so <b class=\"hl\">없어요</b> (\"it's not there\") is immediately wrong.</div><div style=\"margin-bottom:5px;\">💡 공's final letter is ㅇ (not ㄱ)! So <b class=\"hl\">공이에요</b> is correct.</div></div></div></div>\n</div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n  <div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[3-9] Listening — 있어요? 질문</span></div>\n  <div class=\"p-dir\">🔊 가게에서 물어봐요. 알맞은 답을 고르세요.</div>\n  <button class=\"p-audio\" onclick=\"tts('포토카드 있어요?')\">🔊 Listen (포토카드 있어요?)</button>\n  <div class=\"opts\" data-q=\"u3q9\">\n      <button class=\"opt\" onclick=\"checkQ('u3q9',0,this)\"><span class=\"o-idx\">1</span>네, 있어요.<span class=\"o-gl\">✅ yes, there is</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q9',0,this)\"><span class=\"o-idx\">2</span>네, 주세요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q9',0,this)\"><span class=\"o-idx\">3</span>아니요, 있어요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q9',0,this)\"><span class=\"o-idx\">4</span>포토카드가 좋아요.<span class=\"o-gl\">❌</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u3q9\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">\"있어요?\" asks \"is there?\" — the answers are <span class=\"pt-ko\">네, 있어요</span> / <b class=\"hl\">아니요, 없어요</b>.</div><div style=\"margin-bottom:5px;\">ⓞ <b class=\"hl\">네+없어요</b> and <b class=\"hl\">아니요+있어요</b> are contradictory, so they're wrong.</div><div style=\"margin-bottom:5px;\">💡 For a normal (non-negative) question: 네 = 있어요, 아니요 = 없어요!</div></div></div></div>\n</div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n  <div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[3-10] Reading — 주세요 vs 있어요</span></div>\n  <div class=\"p-dir\">아란이 응원봉을 사려고 해요. 가장 자연스러운 말을 고르세요.</div>\n  <div class=\"p-q\">Glowsis 굿즈 판매대 앞에서 아란이:</div>\n  <div class=\"opts\" data-q=\"u3q10\">\n      <button class=\"opt\" onclick=\"checkQ('u3q10',0,this)\"><span class=\"o-idx\">1</span>응원봉 주세요.<span class=\"o-gl\">✅ polite request to buy</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q10',0,this)\"><span class=\"o-idx\">2</span>응원봉이에요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q10',0,this)\"><span class=\"o-idx\">3</span>응원봉이 있어요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u3q10',0,this)\"><span class=\"o-idx\">4</span>응원봉이 좋아요.<span class=\"o-gl\">❌</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u3q10\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">When you <b class=\"hl\">want to buy something</b>, request it with \"… 주세요\". → <span class=\"pt-ko\">응원봉 주세요</span>.</div><div style=\"margin-bottom:5px;\">ⓞ 이에요 (identity), 있어요 (existence), 좋아요 (feeling) are not <b class=\"hl\">requests</b>.</div><div style=\"margin-bottom:5px;\">💡 Buying intent = <b class=\"hl\">주세요</b>, checking if it exists = <b class=\"hl\">있어요?</b>!</div></div></div></div>\n</div>"}, {"cls": "culture", "html": "<div class=\"culture\">\n    <span class=\"c-label\">🎤 K-POP TIP</span>\n    <h3>Merch Vocabulary Dictionary</h3>\n    <p>Every idol group has a different light stick color and shape! Fans collect <b>photocards</b> and buy <b>albums</b>.</p>\n    <div class=\"c-tip\">🛍️ When shopping: \"이거 얼마예요?\" (How much is this?) — you'll learn it in Unit 9!</div>\n  </div>\n\n<!-- ============================================================\n     UNIT 4 — NUMBERS & DATES\n     ============================================================ -->"}]}, {"id": 4, "sections": [{"cls": "unit-flag", "html": "<div class=\"unit-flag\">UNIT 4 · NUMBERS & DATES</div>\n  "}, {"cls": "sec-title", "html": "<div class=\"sec-title\"><div class=\"no\">4</div><div><h2>Debut is in May</h2><div class=\"en\">데뷔는 5월이에요 — Numbers · Dates · Days</div></div></div>\n  "}, {"cls": "story", "html": "<div class=\"story\">\n    <img class=\"story-art\" src=\"assets/glowsis/roy.png\" alt=\"로이\">\n    <div class=\"story-body\">\n      <span class=\"story-tag\">💿 GLOWSIS STORY · 4/8</span>\n      <h3>로이의 데뷔 캘린더 — \"5월 20일!\"</h3>\n      <p>막내 <b>로이</b>는 데뷔 날짜를 기다리고 있어요. 데뷔 캘린더를 읽으려면 <b>숫자와 날짜, 요일</b>이 필요해요! \"언제예요?\" — 날짜를 말할수록 데뷔가 가까워져요. 🐰</p>\n      <span class=\"story-piece\">📆 GLOW POINT 4/8 획득 — Numbers & Dates!</span>\n    </div>\n  </div>\n"}, {"cls": "goals", "html": "<div class=\"goals\">\n    <div class=\"goal\"><span class=\"g-ico\">🔢</span> Native Korean numbers (하나~열)</div>\n    <div class=\"goal\"><span class=\"g-ico\">📅</span> Sino-Korean numbers & dates</div>\n    <div class=\"goal\"><span class=\"g-ico\">🗓️</span> Days of the week</div>\n  </div>\n\n  "}, {"cls": "dialog", "html": "<div class=\"dialog\">\n    <div class=\"d-head\">\n      <span class=\"d-title\">💬 Dialogue 4 — Setting the Debut Date</span>\n      <span class=\"d-scene\">📆 Manager meeting</span>\n    </div>\n    <div class=\"d-line\"><img src=\"assets/glowsis/aran.png\" alt=\"아란\">\n      <div class=\"d-bubble\"><div class=\"who\">아란</div><div class=\"ko\">데뷔는 5월 17일이에요. 무슨 요일이에요?</div><div class=\"gl\">Debut is May 17th. What day of the week is it?</div></div>\n    </div>\n    <div class=\"d-line me\"><img src=\"assets/glowsis/dahee.png\" alt=\"다희\">\n      <div class=\"d-bubble\"><div class=\"who\">다희</div><div class=\"ko\">일요일이에요!</div><div class=\"gl\">It's Sunday!</div></div>\n    </div>\n    <div class=\"d-line\"><img src=\"assets/glowsis/roy.png\" alt=\"로이\">\n      <div class=\"d-bubble\"><div class=\"who\">로이</div><div class=\"ko\">음악방송은 금요일이에요. 데뷔 무대는 5월 20일이에요!</div><div class=\"gl\">The music show is on Friday. The debut stage is May 20th!</div></div>\n    </div>\n    <div class=\"d-line me\"><img src=\"assets/glowsis/dahee.png\" alt=\"다희\">\n      <div class=\"d-bubble\"><div class=\"who\">다희</div><div class=\"ko\">좋아요! 5월 20일, 금요일이에요!</div><div class=\"gl\">Great! May 20th, Friday!</div></div>\n    </div>\n  </div>\n\n  "}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">GRAMMAR 1</span>\n    <div class=\"g-point\">Numbers — Native vs Sino-Korean</div>\n    <div class=\"g-rule\">하나, 둘, 셋 = <b>native Korean</b> (for counting: noun + 개). 일, 이, 삼 = <b>Sino-Korean</b> (dates, time, prices).</div>\n    <div class=\"g-ex\">\n      <div class=\"ex\"><span class=\"ko\">하나, 둘, 셋, 넷, 다섯, 여섯, 일곱, 여덟, 아홉, 열</span><span class=\"gl\">1-10 native Korean</span></div>\n      <div class=\"ex\"><span class=\"ko\">일, 이, 삼, 사, 오, 육, 칠, 팔, 구, 십</span><span class=\"gl\">1-10 Sino-Korean</span></div>\n      <div class=\"ex\"><span class=\"ko\">사과 세 개 있어요.</span><span class=\"gl\">There are three apples. (개 = counter)</span></div>\n    </div>\n  </div>\n\n  "}, {"cls": "teach", "html": "<div class=\"teach\">\n  <span class=\"t-label\">&#x1F9D1;&#x200D;&#x1F3EB; Teacher's Deep-Dive · Korean Numbers: 하나 vs 일</span>\n  <div class=\"t-q\"><span class=\"t-ko\">두 시</span> <span class=\"t-en\">vs</span> <span class=\"t-ko\">이십 분 · 이월</span></div>\n  <div class=\"t-row t-head\"><div class=\"t-why\">Same \"2\", so why <b>두</b> here but <b>이</b> there? &#8212; Korean has <b>TWO kinds of numbers</b>!</div>\n  <div class=\"t-deep\">Korean has separate <b>native numbers</b> (하나 둘 셋&#8230;) and <b>Sino-Korean numbers</b> (일 이 삼&#8230;). Which one you use depends on <b>what you are counting</b>. <b>Hours of the clock (&#8216;시&#8217;) use native</b>, while <b>minutes, dates, and months use Sino-Korean</b>. So to say the time, you actually need both!</div></div>\n  <div class=\"t-grid\">\n    <div class=\"t-cell\"><div class=\"t-word\">하나·둘·셋·넷</div><div class=\"t-role\">native numbers<span class=\"t-sub\">counting + hours (시)</span></div><div class=\"t-note\">used for counting (한 개, 두 개) and <b>clock hours</b></div></div>\n    <div class=\"t-op\">+</div>\n    <div class=\"t-cell t-eqcell\"><div class=\"t-word\">두 시 · 한 시</div><div class=\"t-role\">= 2 o'clock<span class=\"t-sub\">shape change before '시'</span></div><div class=\"t-note\">하나&#8594;<b>한</b>, 둘&#8594;<b>두</b>, 셋&#8594;<b>세</b>, 넷&#8594;<b>네</b><br>2시 = 두 시</div></div>\n    <div class=\"t-op\">&#8594;</div>\n    <div class=\"t-cell\"><div class=\"t-word\">일·이·삼·사</div><div class=\"t-role\">Sino-Korean<span class=\"t-sub\">minutes · dates · months</span></div><div class=\"t-note\">used for reading numbers &amp; phone numbers</div></div>\n    <div class=\"t-op\">+</div>\n    <div class=\"t-cell t-qcell\"><div class=\"t-word\">이십 분 · 이월</div><div class=\"t-role\">= 20 min · Feb<span class=\"t-sub\">no change before '분'</span></div><div class=\"t-note\">minutes, months &amp; dates are Sino-Korean<br>20분 = 이십 분</div></div>\n  </div>\n  <div class=\"t-insight\"><b class=\"t-i-ko\">One-line key:</b> <b>&#8216;시&#8217; (hours) &#8594; native</b> (한 시, 두 시, 여덟 시&#8230;), <b>&#8216;분&#8217; &amp; dates &#8594; Sino-Korean</b> (오 분, 이십 분 · 이월 십사일). So 7:20 is <b>일곱 시 이십 분</b>!</div>\n  <div class=\"t-compare\">\n    <div class=\"t-c-a\"><b>Hours (시) &#8594; native</b><br><span class=\"t-ko\">한 시 · 두 시 · 세 시 · 네 시 · 여덟 시 · 열 시</span><br><span class=\"t-en\">1·2·3·4 turn into 한·두·세·네!</span></div>\n    <div class=\"t-c-b\"><b>Minutes · months · dates &#8594; Sino-Korean</b><br><span class=\"t-ko\">일 분 · 이 분 · 십 분 · 이십 분 · 2월=이월 · 14일=십사일</span><br><span class=\"t-en\">read the digits just as they are</span></div>\n  </div>\n  <div class=\"t-tip\">&#x1F4A1; <b>Memory tip:</b> memorize with the members' birthdays &#8212; if the show starts at <b>8시</b> use the native <b>여덟 시</b>, but if a birthday is <b>2월 14일</b> use the Sino-Korean <b>이월 십사일</b>! Rule of thumb: times use the \"Korean numbers\" (하나 둘&#8230;), while minutes and dates use the \"Sino numbers\" (일 이 삼&#8230;).</div>\n</div>"}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">GRAMMAR 2</span>\n    <div class=\"g-point\">Dates and Days of the Week</div>\n    <div class=\"g-rule\">Dates use Sino-Korean: <b>N월 N일</b>. Days: 월·화·수·목·금·토·일 + 요일.</div>\n    <div class=\"g-ex\">\n      <div class=\"ex\"><span class=\"ko\">5월 17일</span><span class=\"gl\">May 17th (오월 십칠일)</span></div>\n      <div class=\"ex\"><span class=\"ko\">월요일, 화요일, 수요일, 목요일, 금요일, 토요일, 일요일</span><span class=\"gl\">Mon–Sun</span></div>\n      <div class=\"ex\"><span class=\"ko\">오늘은 금요일이에요.</span><span class=\"gl\">Today is Friday.</span></div>\n      <div class=\"ex\"><span class=\"ko\">When is your birthday? — May 17th. (TOPIK 필수!)</span><span class=\"gl\">When is your birthday? — May 17th. (TOPIK 필수!)</span></div>\n    </div>\n  </div>\n\n    "}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">GRAMMAR 3</span>\n    <div class=\"g-point\">시간 — N시 N분 (telling time)</div>\n    <div class=\"g-rule\">Time uses Sino-Korean numbers: <b>N시 N분</b>. \"What time is it?\" = <b>몇 시예요?</b></div>\n    <div class=\"g-ex\">\n      <div class=\"ex\"><span class=\"ko\">지금 몇 시예요? — 5시예요.</span><span class=\"gl\">What time is it now? — It's 5 o'clock.</span></div>\n      <div class=\"ex\"><span class=\"ko\">9시 30분이에요.</span><span class=\"gl\">It's 9:30.</span></div>\n      <div class=\"ex\"><span class=\"ko\">데뷔 무대는 6시에 시작해요.</span><span class=\"gl\">The debut stage starts at 6 o'clock.</span></div>\n    </div>\n  </div>\n\n"}, {"cls": "vocab-lab", "html": "<div class=\"vocab-lab\"><div class=\"vl-toolbar\"><span class=\"vl-hint\">카테고리를 눌러 그림과 함께 공부하세요</span><button class=\"vl-expand\" onclick=\"glowVocabAll()\">모두 펼치기</button></div><div class=\"vl-cat open\" data-tone=\"pink\"><button class=\"vl-cat-head\" onclick=\"glowVocab(this)\"><span class=\"vl-cat-ico\">&#x1F5D3;</span><span class=\"vl-cat-name\">요일<small>Days of the Week · 일주일</small></span><span class=\"vl-cat-count\">7</span><span class=\"vl-cat-arr\">&#x25BE;</span></button><div class=\"vl-cat-body\"><div class=\"vw-grid\"><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u4_mon.webp\" alt=\"월요일\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('월요일')\">&#x1F50A;</button><div class=\"vw-ko\">월요일</div><div class=\"vw-rom\">woryoil</div><div class=\"vw-en\">Monday</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u4_tue.webp\" alt=\"화요일\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('화요일')\">&#x1F50A;</button><div class=\"vw-ko\">화요일</div><div class=\"vw-rom\">hwayoil</div><div class=\"vw-en\">Tuesday</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u4_wed.webp\" alt=\"수요일\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('수요일')\">&#x1F50A;</button><div class=\"vw-ko\">수요일</div><div class=\"vw-rom\">suyoil</div><div class=\"vw-en\">Wednesday</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u4_thu.webp\" alt=\"목요일\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('목요일')\">&#x1F50A;</button><div class=\"vw-ko\">목요일</div><div class=\"vw-rom\">mogyoil</div><div class=\"vw-en\">Thursday</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u4_fri.webp\" alt=\"금요일\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('금요일')\">&#x1F50A;</button><div class=\"vw-ko\">금요일</div><div class=\"vw-rom\">geumyoil</div><div class=\"vw-en\">Friday</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u4_sat.webp\" alt=\"토요일\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('토요일')\">&#x1F50A;</button><div class=\"vw-ko\">토요일</div><div class=\"vw-rom\">toyoil</div><div class=\"vw-en\">Saturday</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u4_sun.webp\" alt=\"일요일\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('일요일')\">&#x1F50A;</button><div class=\"vw-ko\">일요일</div><div class=\"vw-rom\">iryoil</div><div class=\"vw-en\">Sunday</div></div></div></div><div class=\"vs-box\"><div class=\"vs-head\">&#x1F4AC; 이 단어들로 자주 쓰는 말</div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('오늘은 월요일이에요.')\">&#x1F50A;</button><div><span class=\"vs-ko\">오늘은 월요일이에요.</span> <span class=\"vs-en\">Today is Monday.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('화요일에 연습이 있어요.')\">&#x1F50A;</button><div><span class=\"vs-ko\">화요일에 연습이 있어요.</span> <span class=\"vs-en\">There's practice on Tuesday.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('금요일에 콘서트가 있어요.')\">&#x1F50A;</button><div><span class=\"vs-ko\">금요일에 콘서트가 있어요.</span> <span class=\"vs-en\">There's a concert on Friday.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('주말은 토요일과 일요일이에요.')\">&#x1F50A;</button><div><span class=\"vs-ko\">주말은 토요일과 일요일이에요.</span> <span class=\"vs-en\">The weekend is Saturday and Sunday.</span></div></div></div><div class=\"vl-link\">&#x1F4CE; 일곱 요일은 모두 <b>요일</b>로 끝나요. 순서는 <b>월화수목금토일</b> — 영어 'Monday'가 '달(Moon)의 날'이듯, 월요일은 <b>월(月)</b>부터 시작해요!</div></div></div><div class=\"vl-cat\" data-tone=\"sky\"><button class=\"vl-cat-head\" onclick=\"glowVocab(this)\"><span class=\"vl-cat-ico\">&#x23F0;</span><span class=\"vl-cat-name\">하루의 때<small>Time of Day · 오늘·아침·밤</small></span><span class=\"vl-cat-count\">3</span><span class=\"vl-cat-arr\">&#x25BE;</span></button><div class=\"vl-cat-body\"><div class=\"vw-grid\"><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u4_today.webp\" alt=\"오늘\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('오늘')\">&#x1F50A;</button><div class=\"vw-ko\">오늘</div><div class=\"vw-rom\">oneul</div><div class=\"vw-en\">today</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u4_morning.webp\" alt=\"아침\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('아침')\">&#x1F50A;</button><div class=\"vw-ko\">아침</div><div class=\"vw-rom\">achim</div><div class=\"vw-en\">morning</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u4_night.webp\" alt=\"밤\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('밤')\">&#x1F50A;</button><div class=\"vw-ko\">밤</div><div class=\"vw-rom\">bam</div><div class=\"vw-en\">night</div></div></div></div><div class=\"vs-box\"><div class=\"vs-head\">&#x1F4AC; 이 단어들로 자주 쓰는 말</div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('오늘은 무슨 요일이에요?')\">&#x1F50A;</button><div><span class=\"vs-ko\">오늘은 무슨 요일이에요?</span> <span class=\"vs-en\">What day is it today?</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('아침에 일찍 일어나요.')\">&#x1F50A;</button><div><span class=\"vs-ko\">아침에 일찍 일어나요.</span> <span class=\"vs-en\">I wake up early in the morning.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('밤에 노래를 들어요.')\">&#x1F50A;</button><div><span class=\"vs-ko\">밤에 노래를 들어요.</span> <span class=\"vs-en\">I listen to music at night.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('오늘 아침 여섯 시에 일어났어요.')\">&#x1F50A;</button><div><span class=\"vs-ko\">오늘 아침 여섯 시에 일어났어요.</span> <span class=\"vs-en\">I woke up at six this morning.</span></div></div></div><div class=\"vl-link\">&#x1F4CE; <b>오늘</b>은 지금 이 날, <b>아침</b>은 하루의 시작, <b>밤</b>은 해가 진 뒤예요. 시각(몇 시)과 붙여 <b>오늘 몇 시에?</b>, <b>아침 여섯 시</b>처럼 자주 써요.</div></div></div><div class=\"vl-cat\" data-tone=\"lav\"><button class=\"vl-cat-head\" onclick=\"glowVocab(this)\"><span class=\"vl-cat-ico\">&#x1F382;</span><span class=\"vl-cat-name\">생일 & 시간 묻기<small>Birthday · When · What time</small></span><span class=\"vl-cat-count\">3</span><span class=\"vl-cat-arr\">&#x25BE;</span></button><div class=\"vl-cat-body\"><div class=\"vw-grid\"><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u4_birthday.webp\" alt=\"생일\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('생일')\">&#x1F50A;</button><div class=\"vw-ko\">생일</div><div class=\"vw-rom\">saengil</div><div class=\"vw-en\">birthday</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u4_when.webp\" alt=\"언제\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('언제')\">&#x1F50A;</button><div class=\"vw-ko\">언제</div><div class=\"vw-rom\">eonje</div><div class=\"vw-en\">when</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u4_time.webp\" alt=\"몇 시\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('몇 시')\">&#x1F50A;</button><div class=\"vw-ko\">몇 시</div><div class=\"vw-rom\">myeot si</div><div class=\"vw-en\">what time</div></div></div></div><div class=\"vs-box\"><div class=\"vs-head\">&#x1F4AC; 이 단어들로 자주 쓰는 말</div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('생일이 언제예요?')\">&#x1F50A;</button><div><span class=\"vs-ko\">생일이 언제예요?</span> <span class=\"vs-en\">When is your birthday?</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('제 생일은 6월 5일이에요.')\">&#x1F50A;</button><div><span class=\"vs-ko\">제 생일은 6월 5일이에요.</span> <span class=\"vs-en\">My birthday is June 5th.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('지금 몇 시예요?')\">&#x1F50A;</button><div><span class=\"vs-ko\">지금 몇 시예요?</span> <span class=\"vs-en\">What time is it now?</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('콘서트가 몇 시에 시작해요?')\">&#x1F50A;</button><div><span class=\"vs-ko\">콘서트가 몇 시에 시작해요?</span> <span class=\"vs-en\">What time does the concert start?</span></div></div></div><div class=\"vl-link\">&#x1F4CE; <b>언제</b>로 '날'(요일·날짜)을 묻고, <b>몇 시</b>로 '시각'을 물어요. 생일 노래는 <b>생일 축하합니다!</b> 멤버 생일을 한국어로 말할 수 있게 되면 대박이에요!</div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[4-1] Reading &#8212; Which Day?</span></div><div class=\"p-dir\">Read the schedule and choose the correct day.</div><div class=\"p-q\">&#x1F5C4;&#xFE0F; 스케줄 &#8212; 월요일: 연습 / 수요일: 방송 / <b>금요일: 콘서트</b>. &#8212; 콘서트는 무슨 요일이에요?</div><div class=\"opts\" data-q=\"u4q1\"><button class=\"opt\" onclick=\"checkQ('u4q1',2,this)\"><span class=\"o-idx\">1</span>월요일<span class=\"o-gl\">&#x274C;</span></button><button class=\"opt\" onclick=\"checkQ('u4q1',2,this)\"><span class=\"o-idx\">2</span>수요일<span class=\"o-gl\">&#x274C;</span></button><button class=\"opt\" onclick=\"checkQ('u4q1',2,this)\"><span class=\"o-idx\">3</span>금요일<span class=\"o-gl\">&#x2705; 금요일 = Friday</span></button><button class=\"opt\" onclick=\"checkQ('u4q1',2,this)\"><span class=\"o-idx\">4</span>일요일<span class=\"o-gl\">&#x274C;</span></button></div><div class=\"p-feedback\" id=\"fb-u4q1\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">&#x1F9D1;&#x200D;&#x1F3EB; 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\">From the schedule, the concert is on <b>금요일</b>. <b>금요일</b> = Friday, <b>월요일</b> = Monday, <b>수요일</b> = Wednesday, <b>일요일</b> = Sunday. Learn the days in order: 월&#8594;화&#8594;수&#8594;목&#8594;금&#8594;토&#8594;일.</div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[4-2] Reading &#8212; Day Order</span></div><div class=\"p-dir\">Read and choose the day right after the one shown.</div><div class=\"p-q\">&#x1F501; 요일 순서: 월 &#8594; 화 &#8594; 수 &#8594; 목 &#8594; &#8230; &#8212; <b>목요일 다음에 오는 요일</b>은?</div><div class=\"opts\" data-q=\"u4q2\"><button class=\"opt\" onclick=\"checkQ('u4q2',0,this)\"><span class=\"o-idx\">1</span>금요일<span class=\"o-gl\">&#x2705; 목요일 다음 = 금요일</span></button><button class=\"opt\" onclick=\"checkQ('u4q2',0,this)\"><span class=\"o-idx\">2</span>토요일<span class=\"o-gl\">&#x274C;</span></button><button class=\"opt\" onclick=\"checkQ('u4q2',0,this)\"><span class=\"o-idx\">3</span>화요일<span class=\"o-gl\">&#x274C;</span></button><button class=\"opt\" onclick=\"checkQ('u4q2',0,this)\"><span class=\"o-idx\">4</span>일요일<span class=\"o-gl\">&#x274C;</span></button></div><div class=\"p-feedback\" id=\"fb-u4q2\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">&#x1F9D1;&#x200D;&#x1F3EB; 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\">The week runs 월&#8594;화&#8594;수&#8594;목&#8594;금&#8594;토&#8594;일. Right after <b>목요일</b> (Thursday) comes <b>금요일</b> (Friday). 토요일 and 일요일 are two slots after 목요일, so they are not the answer.</div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[4-3] Listening &#8212; What Time?</span></div><div class=\"p-dir\">Listen and choose when the concert starts.</div><button class=\"p-audio\" onclick=\"tts('콘서트가 일곱 시에 시작해요.')\">&#x1F50A; Listen</button><div class=\"p-q\">콘서트는 몇 시에 시작해요?</div><div class=\"opts\" data-q=\"u4q3\"><button class=\"opt\" onclick=\"checkQ('u4q3',2,this)\"><span class=\"o-idx\">1</span>다섯 시<span class=\"o-gl\">&#x274C;</span></button><button class=\"opt\" onclick=\"checkQ('u4q3',2,this)\"><span class=\"o-idx\">2</span>여섯 시<span class=\"o-gl\">&#x274C;</span></button><button class=\"opt\" onclick=\"checkQ('u4q3',2,this)\"><span class=\"o-idx\">3</span>일곱 시<span class=\"o-gl\">&#x2705; 들은 문장 = 일곱 시 (7시)</span></button><button class=\"opt\" onclick=\"checkQ('u4q3',2,this)\"><span class=\"o-idx\">4</span>여덟 시<span class=\"o-gl\">&#x274C;</span></button></div><div class=\"p-feedback\" id=\"fb-u4q3\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">&#x1F9D1;&#x200D;&#x1F3EB; 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\">What you heard, <b>일곱 시</b>, means 7 o'clock. To say what time it is (시), Korean uses <b>native</b> numbers. Watch how 1&#8594;<b>한</b>, 2&#8594;<b>두</b>, 3&#8594;<b>세</b>, 4&#8594;<b>네</b> change shape.</div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[4-4] Reading &#8212; Minutes</span></div><div class=\"p-dir\">Read the clock and say the time out loud.</div><div class=\"p-q\">&#x1F558; 지금 시계가 <b>7시 20분</b>이에요. &#8212; 지금 몇 시 몇 분이에요?</div><div class=\"opts\" data-q=\"u4q4\"><button class=\"opt\" onclick=\"checkQ('u4q4',0,this)\"><span class=\"o-idx\">1</span>일곱 시 이십 분<span class=\"o-gl\">&#x2705; 7시 20분 = 일곱 시 이십 분</span></button><button class=\"opt\" onclick=\"checkQ('u4q4',0,this)\"><span class=\"o-idx\">2</span>일곱 시 이 분<span class=\"o-gl\">&#x274C;</span></button><button class=\"opt\" onclick=\"checkQ('u4q4',0,this)\"><span class=\"o-idx\">3</span>여덟 시 이십 분<span class=\"o-gl\">&#x274C;</span></button><button class=\"opt\" onclick=\"checkQ('u4q4',0,this)\"><span class=\"o-idx\">4</span>일곱 시 오십 분<span class=\"o-gl\">&#x274C;</span></button></div><div class=\"p-feedback\" id=\"fb-u4q4\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">&#x1F9D1;&#x200D;&#x1F3EB; 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\">The hour word <b>시</b> takes a native number &#8594; 7 = <b>일곱</b> (일곱 시). <b>분</b> (minutes) takes a Sino-Korean number &#8594; 20 = <b>이십</b> (이십 분). So the time is <b>일곱 시 이십 분</b>. Remember: \"시 = native, 분 = Sino-Korean\"!</div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[4-5] Reading &#8212; Hour Form</span></div><div class=\"p-dir\">Hours use native Korean numbers — choose the natural form.</div><div class=\"p-q\">&#x1F552; 시계가 <b>2시</b>예요. 자연스러운 표현은?</div><div class=\"opts\" data-q=\"u4q5\"><button class=\"opt\" onclick=\"checkQ('u4q5',1,this)\"><span class=\"o-idx\">1</span>둘 시예요.<span class=\"o-gl\">&#x274C;</span></button><button class=\"opt\" onclick=\"checkQ('u4q5',1,this)\"><span class=\"o-idx\">2</span>두 시예요.<span class=\"o-gl\">&#x2705; 2시 = 두 시 (둘&#8594;두)</span></button><button class=\"opt\" onclick=\"checkQ('u4q5',1,this)\"><span class=\"o-idx\">3</span>이 시예요.<span class=\"o-gl\">&#x274C;</span></button><button class=\"opt\" onclick=\"checkQ('u4q5',1,this)\"><span class=\"o-idx\">4</span>일 시예요.<span class=\"o-gl\">&#x274C;</span></button></div><div class=\"p-feedback\" id=\"fb-u4q5\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">&#x1F9D1;&#x200D;&#x1F3EB; 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\">To count hours you use native numbers, and 1&#8594;<b>한</b>, 2&#8594;<b>두</b>, 3&#8594;<b>세</b>, 4&#8594;<b>네</b> change their shape. So 2시 = <b>두 시</b>. <b>둘 시</b> and the Sino-Korean <b>이 시</b> are both wrong here.</div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[4-6] Reading &#8212; Minute Form</span></div><div class=\"p-dir\">Minutes and dates use Sino-Korean numbers — choose the correct form.</div><div class=\"p-q\">&#x23F1;&#xFE0F; <b>3분</b>을 한국어로 하면?</div><div class=\"opts\" data-q=\"u4q6\"><button class=\"opt\" onclick=\"checkQ('u4q6',2,this)\"><span class=\"o-idx\">1</span>셋 분<span class=\"o-gl\">&#x274C;</span></button><button class=\"opt\" onclick=\"checkQ('u4q6',2,this)\"><span class=\"o-idx\">2</span>세 분<span class=\"o-gl\">&#x274C;</span></button><button class=\"opt\" onclick=\"checkQ('u4q6',2,this)\"><span class=\"o-idx\">3</span>삼 분<span class=\"o-gl\">&#x2705; 3분 = 삼 분 (한자어)</span></button><button class=\"opt\" onclick=\"checkQ('u4q6',2,this)\"><span class=\"o-idx\">4</span>사 분<span class=\"o-gl\">&#x274C;</span></button></div><div class=\"p-feedback\" id=\"fb-u4q6\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">&#x1F9D1;&#x200D;&#x1F3EB; 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><b>분</b> (minutes) plus dates and months use <b>Sino-Korean</b> numbers (일 이 삼 사) &#8594; 3분 = <b>삼 분</b>. The native <b>세</b> is only used in &#8216;세 시&#8217; (3 o'clock, an hour) and never with 분.</div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[4-7] Listening &#8212; Birthday Date</span></div><div class=\"p-dir\">Listen and choose the birthday date.</div><button class=\"p-audio\" onclick=\"tts('제 생일이 오늘인데, 오늘은 이월 십사일이에요.')\">&#x1F50A; Listen</button><div class=\"p-q\">생일이 언제예요?</div><div class=\"opts\" data-q=\"u4q7\"><button class=\"opt\" onclick=\"checkQ('u4q7',1,this)\"><span class=\"o-idx\">1</span>이월 사일<span class=\"o-gl\">&#x274C;</span></button><button class=\"opt\" onclick=\"checkQ('u4q7',1,this)\"><span class=\"o-idx\">2</span>이월 십사일<span class=\"o-gl\">&#x2705; 들은 날짜 = 2월 14일</span></button><button class=\"opt\" onclick=\"checkQ('u4q7',1,this)\"><span class=\"o-idx\">3</span>십이월 사일<span class=\"o-gl\">&#x274C;</span></button><button class=\"opt\" onclick=\"checkQ('u4q7',1,this)\"><span class=\"o-idx\">4</span>사월 십이일<span class=\"o-gl\">&#x274C;</span></button></div><div class=\"p-feedback\" id=\"fb-u4q7\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">&#x1F9D1;&#x200D;&#x1F3EB; 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\">The date you heard, <b>이월 십사일</b>, means February 14th. Months and days (dates) are read with <b>Sino-Korean</b> numbers: 이월 (February) + 십사일 (14th). A great example that minutes, months and dates are all Sino-Korean!</div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[4-8] Reading &#8212; Time of Day</span></div><div class=\"p-dir\">Read the lyric and choose when you'd hear this song.</div><div class=\"p-q\">&#x1F319; 가사 &#8212; &#8216;<b>밤이 깊었어요.</b>&#8217; 이 노래는 언제 주로 들어요?</div><div class=\"opts\" data-q=\"u4q8\"><button class=\"opt\" onclick=\"checkQ('u4q8',2,this)\"><span class=\"o-idx\">1</span>아침에<span class=\"o-gl\">&#x274C;</span></button><button class=\"opt\" onclick=\"checkQ('u4q8',2,this)\"><span class=\"o-idx\">2</span>점심에<span class=\"o-gl\">&#x274C;</span></button><button class=\"opt\" onclick=\"checkQ('u4q8',2,this)\"><span class=\"o-idx\">3</span>밤에<span class=\"o-gl\">&#x2705; 밤이 깊다 = 깊은 밤</span></button><button class=\"opt\" onclick=\"checkQ('u4q8',2,this)\"><span class=\"o-idx\">4</span>오후에<span class=\"o-gl\">&#x274C;</span></button></div><div class=\"p-feedback\" id=\"fb-u4q8\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">&#x1F9D1;&#x200D;&#x1F3EB; 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><b>밤이 깊다</b> = the night is deep. So this song is for listening at <b>밤</b> (night). <b>아침</b> = morning, <b>오후</b> = afternoon, <b>오늘</b> = today &#8212; all time-of-day words.</div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[4-9] Reading &#8212; Birthday Reply</span></div><div class=\"p-dir\">Choose the most natural reply to the question.</div><div class=\"p-q\">&#x1F382; 질문: <b>&#8216;생일이 언제예요?&#8217;</b> &#8212; 자연스러운 응답은?</div><div class=\"opts\" data-q=\"u4q9\"><button class=\"opt\" onclick=\"checkQ('u4q9',1,this)\"><span class=\"o-idx\">1</span>네, 생일 좋아해요.<span class=\"o-gl\">&#x274C;</span></button><button class=\"opt\" onclick=\"checkQ('u4q9',1,this)\"><span class=\"o-idx\">2</span>제 생일은 다음 주 화요일이에요.<span class=\"o-gl\">&#x2705; 언제로 물으면 날짜·요일로 답해요</span></button><button class=\"opt\" onclick=\"checkQ('u4q9',1,this)\"><span class=\"o-idx\">3</span>생일이 있어요.<span class=\"o-gl\">&#x274C;</span></button><button class=\"opt\" onclick=\"checkQ('u4q9',1,this)\"><span class=\"o-idx\">4</span>오늘 생일이 아니에요.<span class=\"o-gl\">&#x274C;</span></button></div><div class=\"p-feedback\" id=\"fb-u4q9\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">&#x1F9D1;&#x200D;&#x1F3EB; 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\">When someone asks <b>언제</b> (when), you answer with a <b>date/day</b>: &#8216;제 생일은 다음 주 화요일이에요.&#8217; Saying &#8216;좋아해요&#8217; answers about taste, and &#8216;있어요/아니에요&#8217; answers whether something exists &#8212; neither fits a \"when\" question.</div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[4-10] Listening &#8212; Day &amp; Time Recap</span></div><div class=\"p-dir\">Listen and choose when the practice is.</div><button class=\"p-audio\" onclick=\"tts('토요일 아침 열 시에 연습이 있어요.')\">&#x1F50A; Listen</button><div class=\"p-q\">연습은 언제예요?</div><div class=\"opts\" data-q=\"u4q10\"><button class=\"opt\" onclick=\"checkQ('u4q10',0,this)\"><span class=\"o-idx\">1</span>토요일 아침 열 시<span class=\"o-gl\">&#x2705; 들은 내용 = 토요일 아침 열 시</span></button><button class=\"opt\" onclick=\"checkQ('u4q10',0,this)\"><span class=\"o-idx\">2</span>일요일 저녁 열 시<span class=\"o-gl\">&#x274C;</span></button><button class=\"opt\" onclick=\"checkQ('u4q10',0,this)\"><span class=\"o-idx\">3</span>토요일 밤 열 시<span class=\"o-gl\">&#x274C;</span></button><button class=\"opt\" onclick=\"checkQ('u4q10',0,this)\"><span class=\"o-idx\">4</span>금요일 아침 아홉 시<span class=\"o-gl\">&#x274C;</span></button></div><div class=\"p-feedback\" id=\"fb-u4q10\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">&#x1F9D1;&#x200D;&#x1F3EB; 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\">What you heard, <b>토요일 아침 열 시</b> = Saturday morning, 10 o'clock. Here you practice all at once: a day (<b>토요일</b>) + a time of day (<b>아침</b>) + a clock hour (<b>열 시</b> = 10시, a native number). It&#8217;s 밤 &#8594; 아침, not 저녁.</div></div></div>"}, {"cls": "culture", "html": "<div class=\"culture\">\n    <span class=\"c-label\">🎤 K-POP TIP</span>\n    <h3>Debut Day = Festival Day!</h3>\n    <p>An idol's <b>debut day (anniversary)</b> is the most special day for fans! They celebrate it like a <b>birthday</b>.</p>\n    <div class=\"c-tip\">🎂 On your favorite idol's birthday, fans say: \"생일 축하해요!\" (Happy birthday!)</div>\n  </div>\n\n<!-- ============================================================\n     UNIT 5 — LIKES & DAILY ACTIONS\n     ============================================================ -->"}]}, {"id": 5, "sections": [{"cls": "unit-flag", "html": "<div class=\"unit-flag\">UNIT 5 · LIKES & DAILY ACTIONS</div>\n  "}, {"cls": "sec-title", "html": "<div class=\"sec-title\"><div class=\"no\">5</div><div><h2>I Like Singing</h2><div class=\"en\">노래를 좋아해요 — Likes · 을/를 · -아요/어요</div></div></div>\n  "}, {"cls": "story", "html": "<div class=\"story\">\n    <img class=\"story-art\" src=\"assets/glowsis/dahee.png\" alt=\"다희\">\n    <div class=\"story-body\">\n      <span class=\"story-tag\">💿 GLOWSIS STORY · 5/8</span>\n      <h3>다희의 좋아하는 것 — \"노래를 좋아해요!\"</h3>\n      <p>대기실 인터뷰! <b>다희</b>는 한국어로 좋아하는 것을 말하는 법을 가르쳐요. \"저는 ○○을 좋아해요!\" — 좋아하는 것을 말할 때마다 음표가 반짝여요. 🎶</p>\n      <span class=\"story-piece\">🎶 GLOW POINT 5/8 획득 — Likes!</span>\n    </div>\n  </div>\n"}, {"cls": "goals", "html": "<div class=\"goals\">\n    <div class=\"goal\"><span class=\"g-ico\">❤️</span> 좋아해요 (like) / 싫어해요 (dislike)</div>\n    <div class=\"goal\"><span class=\"g-ico\">🔤</span> 을/를 object particle</div>\n    <div class=\"goal\"><span class=\"g-ico\">🎵</span> -아요/어요 present tense</div>\n  </div>\n\n  "}, {"cls": "dialog", "html": "<div class=\"dialog\">\n    <div class=\"d-head\">\n      <span class=\"d-title\">💬 Dialogue 5 — Things We Like</span>\n      <span class=\"d-scene\">🎶 Waiting room interview</span>\n    </div>\n    <div class=\"d-line\"><img src=\"assets/glowsis/dahee.png\" alt=\"다희\">\n      <div class=\"d-bubble\"><div class=\"who\">다희</div><div class=\"ko\">저는 춤을 좋아해요. 그리고 노래도 좋아해요.</div><div class=\"gl\">I like dancing. And I like singing too.</div></div>\n    </div>\n    <div class=\"d-line\"><img src=\"assets/glowsis/roy.png\" alt=\"로이\">\n      <div class=\"d-bubble\"><div class=\"who\">로이</div><div class=\"ko\">저는 랩을 좋아해요. 하지만 매운 음식은 싫어해요.</div><div class=\"gl\">I like rap. But I don't like spicy food.</div></div>\n    </div>\n    <div class=\"d-line me\"><img src=\"assets/glowsis/aran.png\" alt=\"아란\">\n      <div class=\"d-bubble\"><div class=\"who\">아란</div><div class=\"ko\">저는 팬들을 좋아해요! 팬들이 제일 좋아요!</div><div class=\"gl\">I like our fans! Fans are the best!</div></div>\n    </div>\n    <div class=\"d-line\"><img src=\"assets/glowsis/roy.png\" alt=\"로이\">\n      <div class=\"d-bubble\"><div class=\"who\">로이</div><div class=\"ko\">저는 게임을 좋아해요. 매일 밤 게임을 해요!</div><div class=\"gl\">I like games. I play games every night!</div></div>\n    </div>\n  </div>\n\n  "}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">GRAMMAR 1</span>\n    <div class=\"g-point\">을/를 — Object particle</div>\n    <div class=\"g-rule\">It marks the object of an action. After a final consonant use <b>을</b>, after a vowel use <b>를</b>.</div>\n    <div class=\"g-ex\">\n      <div class=\"ex\"><span class=\"ko\">노래<b>를</b> 좋아해요.</span><span class=\"gl\">노래 has no final consonant → 를</span></div>\n      <div class=\"ex\"><span class=\"ko\">랩<b>을</b> 좋아해요.</span><span class=\"gl\">랩 has final consonant ㅂ → 을</span></div>\n      <div class=\"ex\"><span class=\"ko\">물을 마셔요.</span><span class=\"gl\">I drink water.</span></div>\n    </div>\n  </div>\n\n  "}, {"cls": "teach", "html": "<div class=\"teach\">\n  <span class=\"t-label\">&#x1F9D1;&#x200D;&#x1F3EB; Teacher's Deep-Dive · 을/를 목적격 조사 (Object Particle)</span>\n  <div class=\"t-q\"><span class=\"t-ko\">다희는 춤을 좋아해요 · 저는 노래를 좋아해요</span> <span class=\"t-en\">marking the thing we like</span></div>\n\n  <div class=\"t-row t-head\">\n    <div class=\"t-why\">Why <b class=hl>춤을</b>, <b class=hl>노래를</b>? &#8212; because 을/를 marks the <b>object</b> (the thing being liked)!</div>\n    <div class=\"t-deep\">\n      Whenever a verb describes <b>an action done TO something</b> &#8212; like 좋아해요 · 싫어해요 · 해요 · 먹어요 &#8212; that <b>object (the target)</b> is marked with 을/를.\n      In English \"I like dance,\" the object of \"like\" is dance. Korean puts this object <b>right before the verb</b>.\n      Whether you use 을 or 를 depends on the <b>받침 (final consonant)</b> of the word before it &#8212; a final consonant means <b>을</b>, no final consonant (vowel) means <b>를</b>.\n    </div>\n  </div>\n\n  <div class=\"t-grid\">\n    <div class=\"t-cell\"><div class=\"t-word\">저는</div><div class=\"t-role\">I <span class=\"t-sub\">(subject)</span></div><div class=\"t-note\">a subject takes the topic particle<br>은/는</div></div>\n    <div class=\"t-op\">+</div>\n    <div class=\"t-cell t-qcell\"><div class=\"t-word\">춤을</div><div class=\"t-role\">dance <span class=\"t-sub\">(object)</span></div><div class=\"t-note\">춤 (final consonant ㅁ) &#8594; <b class=hl>을</b><br>the thing being liked</div></div>\n    <div class=\"t-op\">+</div>\n    <div class=\"t-cell t-eqcell\"><div class=\"t-word\">좋아해요</div><div class=\"t-role\">like <span class=\"t-sub\">(verb)</span></div><div class=\"t-note\">comes right after<br>the object</div></div>\n  </div>\n\n  <div class=\"t-insight\"><b class=\"t-i-ko\">The key:</b> 을/를 is the <b>object marker</b> that tells you <b>WHAT the action is done to</b>. Ends with a final consonant &#8594; <b>을</b>, ends with a vowel &#8594; <b>를</b> &#8212; the same rule as 이에요/예요!</div>\n\n  <div class=\"t-compare\">\n    <div class=\"t-c-a\"><b>final consonant &#8594; 을</b><br><span class=\"t-ko\">춤<b>을</b> · 음악<b>을</b> · 게임<b>을</b> · 물<b>을</b> · 운동<b>을</b></span></div>\n    <div class=\"t-c-b\"><b>no final consonant &#8594; 를</b><br><span class=\"t-ko\">노래<b>를</b> · 커피<b>를</b> · 공부<b>를</b> · 우유<b>를</b> · 사과<b>를</b></span></div>\n  </div>\n\n  <div class=\"t-tip\">&#x1F4A1; <b>Memory tip:</b> learn it from the dialogue &#8212; 춤 (which \"cuts off\" on the final ㅁ) is <b>춤을</b>, while 노래 (which opens with a vowel) is <b>노래를</b>. In front of the fans, saying \"저는 <b>여러분을</b> 좋아해요!\" &#8212; always marking the object with 을/를 &#8212; sounds totally natural!</div>\n</div>"}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">GRAMMAR 2</span>\n    <div class=\"g-point\">-아요/어요 — Present Tense</div>\n    <div class=\"g-rule\">The polite present form of verbs & adjectives. After vowels ㅏ/ㅗ use <b>-아요</b>, otherwise <b>-어요</b>, and 하다 verbs become <b>-해요</b>!</div>\n    <div class=\"g-ex\">\n      <div class=\"ex\"><span class=\"ko\">좋아하<b>다</b> → 좋아<b>해요</b></span><span class=\"gl\">하다 → 해요 (like)</span></div>\n      <div class=\"ex\"><span class=\"ko\">가<b>다</b> → 가<b>요</b></span><span class=\"gl\">ㅏ + 아요 = 아요 (go)</span></div>\n      <div class=\"ex\"><span class=\"ko\">먹<b>다</b> → 먹<b>어요</b></span><span class=\"gl\">eat</span></div>\n      <div class=\"ex\"><span class=\"ko\">마시<b>다</b> → 마셔요</span><span class=\"gl\">drink</span></div>\n    </div>\n  </div>\n\n    "}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">GRAMMAR 3</span>\n    <div class=\"g-point\">-고 싶어요 — \"I want to ~\"</div>\n    <div class=\"g-rule\">Drop 다 from a verb and add <b>-고 싶어요</b> to say what you want to do. A TOPIK I favorite!</div>\n    <div class=\"g-ex\">\n      <div class=\"ex\"><span class=\"ko\">노래하<b>고 싶어요</b>.</span><span class=\"gl\">I want to sing.</span></div>\n      <div class=\"ex\"><span class=\"ko\">춤추<b>고 싶어요</b>.</span><span class=\"gl\">I want to dance.</span></div>\n      <div class=\"ex\"><span class=\"ko\">팬들을 만나<b>고 싶어요</b>.</span><span class=\"gl\">I want to meet the fans.</span></div>\n    </div>\n  </div>\n\n"}, {"cls": "vocab-lab", "html": "<div class=\"vocab-lab\"><div class=\"vl-toolbar\"><span class=\"vl-hint\">카드를 눌러 🔊 소리를 들어 보세요.</span><button class=\"vl-expand\" onclick=\"glowVocabAll(this)\">모두 펼치기</button></div><div class=\"vl-cat open\" data-tone=\"pink\"><button class=\"vl-cat-head\" onclick=\"glowVocab(this)\"><span class=\"vl-cat-ico\">❤️</span><div class=\"vl-cat-name\">기분 말하기<small>Talking about feelings</small></div><span class=\"vl-cat-count\">2</span><span class=\"vl-cat-arr\">▾</span></button><div class=\"vl-cat-body\"><div class=\"vw-grid\"><div class=\"vw-card\"><img class=\"vw-thumb\" src=\"assets/vocab/u5_like.webp\" alt=\"좋아하다\"><div class=\"vw-main\"><div class=\"vw-ko\">좋아하다</div><div class=\"vw-rom\">joahada</div><div class=\"vw-en\">to like</div></div><button class=\"vw-tts\" onclick=\"tts('좋아해요')\" aria-label=\"듣기\">🔊</button></div><div class=\"vw-card\"><img class=\"vw-thumb\" src=\"assets/vocab/u5_dislike.webp\" alt=\"싫어하다\"><div class=\"vw-main\"><div class=\"vw-ko\">싫어하다</div><div class=\"vw-rom\">sireohada</div><div class=\"vw-en\">to dislike</div></div><button class=\"vw-tts\" onclick=\"tts('싫어해요')\" aria-label=\"듣기\">🔊</button></div></div><div class=\"vs-box\"><div class=\"vs-title\">💬 자주 쓰는 말</div><div class=\"vs-line\"><span class=\"vs-ko\">저는 케이팝을 좋아해요.</span><button class=\"vu-btn\" onclick=\"tts('저는 케이팝을 좋아해요.')\" aria-label=\"읽어 주기\">🔊</button></div><div class=\"vs-line\"><span class=\"vs-ko\">로이는 매운 음식을 싫어해요.</span><button class=\"vu-btn\" onclick=\"tts('로이는 매운 음식을 싫어해요.')\" aria-label=\"읽어 주기\">🔊</button></div></div><div class=\"vl-link\">🔗 <b>좋아하다 · 싫어하다</b>는 반대 뜻이에요. 둘 다 「무엇을」 좋아/싫어하는지 대상(목적어)을 을/를로 표시해요 — 예) <b>춤을 좋아해요</b>.</div>\n</div></div><div class=\"vl-cat\" data-tone=\"mint\"><button class=\"vl-cat-head\" onclick=\"glowVocab(this)\"><span class=\"vl-cat-ico\">🎶</span><div class=\"vl-cat-name\">노래와 춤<small>Singing &amp; dancing</small></div><span class=\"vl-cat-count\">3</span><span class=\"vl-cat-arr\">▾</span></button><div class=\"vl-cat-body\"><div class=\"vw-grid\"><div class=\"vw-card\"><img class=\"vw-thumb\" src=\"assets/vocab/u5_sing.webp\" alt=\"노래하다\"><div class=\"vw-main\"><div class=\"vw-ko\">노래하다</div><div class=\"vw-rom\">noraehada</div><div class=\"vw-en\">to sing</div></div><button class=\"vw-tts\" onclick=\"tts('노래해요')\" aria-label=\"듣기\">🔊</button></div><div class=\"vw-card\"><img class=\"vw-thumb\" src=\"assets/vocab/u5_dance.webp\" alt=\"춤\"><div class=\"vw-main\"><div class=\"vw-ko\">춤</div><div class=\"vw-rom\">chum</div><div class=\"vw-en\">dance</div></div><button class=\"vw-tts\" onclick=\"tts('춤')\" aria-label=\"듣기\">🔊</button></div><div class=\"vw-card\"><img class=\"vw-thumb\" src=\"assets/vocab/u5_noraebang.webp\" alt=\"노래방\"><div class=\"vw-main\"><div class=\"vw-ko\">노래방</div><div class=\"vw-rom\">noraebang</div><div class=\"vw-en\">karaoke room</div></div><button class=\"vw-tts\" onclick=\"tts('노래방')\" aria-label=\"듣기\">🔊</button></div></div><div class=\"vs-box\"><div class=\"vs-title\">💬 자주 쓰는 말</div><div class=\"vs-line\"><span class=\"vs-ko\">다희는 노래를 좋아해요.</span><button class=\"vu-btn\" onclick=\"tts('다희는 노래를 좋아해요.')\" aria-label=\"읽어 주기\">🔊</button></div><div class=\"vs-line\"><span class=\"vs-ko\">우리 오늘 노래방에 가요.</span><button class=\"vu-btn\" onclick=\"tts('우리 오늘 노래방에 가요.')\" aria-label=\"읽어 주기\">🔊</button></div><div class=\"vs-line\"><span class=\"vs-ko\">유나는 춤을 잘 춰요.</span><button class=\"vu-btn\" onclick=\"tts('유나는 춤을 잘 춰요.')\" aria-label=\"읽어 주기\">🔊</button></div></div><div class=\"vl-link\">🔗 <b>노래를 하고 춤을 추는</b> 곳이 바로 <b>노래방</b>! 아이돌 멤버들은 방송 전에 노래방에서 목을 풀기도 해요.</div>\n</div></div><div class=\"vl-cat\" data-tone=\"sky\"><button class=\"vl-cat-head\" onclick=\"glowVocab(this)\"><span class=\"vl-cat-ico\">🎮</span><div class=\"vl-cat-name\">취미와 활동<small>Hobbies &amp; everyday things</small></div><span class=\"vl-cat-count\">5</span><span class=\"vl-cat-arr\">▾</span></button><div class=\"vl-cat-body\"><div class=\"vw-grid\"><div class=\"vw-card\"><img class=\"vw-thumb\" src=\"assets/vocab/u5_game.webp\" alt=\"게임\"><div class=\"vw-main\"><div class=\"vw-ko\">게임</div><div class=\"vw-rom\">geim</div><div class=\"vw-en\">game</div></div><button class=\"vw-tts\" onclick=\"tts('게임')\" aria-label=\"듣기\">🔊</button></div><div class=\"vw-card\"><img class=\"vw-thumb\" src=\"assets/vocab/u5_study.webp\" alt=\"공부하다\"><div class=\"vw-main\"><div class=\"vw-ko\">공부하다</div><div class=\"vw-rom\">gongbuhada</div><div class=\"vw-en\">to study</div></div><button class=\"vw-tts\" onclick=\"tts('공부해요')\" aria-label=\"듣기\">🔊</button></div><div class=\"vw-card\"><img class=\"vw-thumb\" src=\"assets/vocab/u5_exercise.webp\" alt=\"운동\"><div class=\"vw-main\"><div class=\"vw-ko\">운동</div><div class=\"vw-rom\">undong</div><div class=\"vw-en\">exercise</div></div><button class=\"vw-tts\" onclick=\"tts('운동')\" aria-label=\"듣기\">🔊</button></div><div class=\"vw-card\"><img class=\"vw-thumb\" src=\"assets/vocab/u5_travel.webp\" alt=\"여행\"><div class=\"vw-main\"><div class=\"vw-ko\">여행</div><div class=\"vw-rom\">yeohaeng</div><div class=\"vw-en\">trip · travel</div></div><button class=\"vw-tts\" onclick=\"tts('여행')\" aria-label=\"듣기\">🔊</button></div><div class=\"vw-card\"><img class=\"vw-thumb\" src=\"assets/vocab/u5_sleep.webp\" alt=\"자다\"><div class=\"vw-main\"><div class=\"vw-ko\">자다</div><div class=\"vw-rom\">jada</div><div class=\"vw-en\">to sleep</div></div><button class=\"vw-tts\" onclick=\"tts('자요')\" aria-label=\"듣기\">🔊</button></div></div><div class=\"vs-box\"><div class=\"vs-title\">💬 자주 쓰는 말</div><div class=\"vs-line\"><span class=\"vs-ko\">로이는 매일 밤 게임을 해요.</span><button class=\"vu-btn\" onclick=\"tts('로이는 매일 밤 게임을 해요.')\" aria-label=\"읽어 주기\">🔊</button></div><div class=\"vs-line\"><span class=\"vs-ko\">아란은 아침마다 운동을 해요.</span><button class=\"vu-btn\" onclick=\"tts('아란은 아침마다 운동을 해요.')\" aria-label=\"읽어 주기\">🔊</button></div><div class=\"vs-line\"><span class=\"vs-ko\">저는 방학에 여행을 가고 싶어요.</span><button class=\"vu-btn\" onclick=\"tts('저는 방학에 여행을 가고 싶어요.')\" aria-label=\"읽어 주기\">🔊</button></div><div class=\"vs-line\"><span class=\"vs-ko\">피곤하면 일찍 자요.</span><button class=\"vu-btn\" onclick=\"tts('피곤하면 일찍 자요.')\" aria-label=\"읽어 주기\">🔊</button></div></div><div class=\"vl-link\">🔗 취미·활동은 다 <b>동사와 붙어요</b>: 게임을 <b>해요</b>, 운동을 <b>해요</b>, 여행을 <b>가요</b>. 받침이 있는 단어(게임·운동) 뒤엔 <b>을</b>, 공부(모음) 뒤엔 <b>를</b>이 와요!</div>\n</div></div><div class=\"vl-cat\" data-tone=\"lav\"><button class=\"vl-cat-head\" onclick=\"glowVocab(this)\"><span class=\"vl-cat-ico\">🍜</span><div class=\"vl-cat-name\">먹고 마시기<small>Eating &amp; drinking</small></div><span class=\"vl-cat-count\">4</span><span class=\"vl-cat-arr\">▾</span></button><div class=\"vl-cat-body\"><div class=\"vw-grid\"><div class=\"vw-card\"><img class=\"vw-thumb\" src=\"assets/vocab/u5_food.webp\" alt=\"음식\"><div class=\"vw-main\"><div class=\"vw-ko\">음식</div><div class=\"vw-rom\">eumsik</div><div class=\"vw-en\">food</div></div><button class=\"vw-tts\" onclick=\"tts('음식')\" aria-label=\"듣기\">🔊</button></div><div class=\"vw-card\"><img class=\"vw-thumb\" src=\"assets/vocab/u5_eat.webp\" alt=\"먹다\"><div class=\"vw-main\"><div class=\"vw-ko\">먹다</div><div class=\"vw-rom\">meokda</div><div class=\"vw-en\">to eat</div></div><button class=\"vw-tts\" onclick=\"tts('먹어요')\" aria-label=\"듣기\">🔊</button></div><div class=\"vw-card\"><img class=\"vw-thumb\" src=\"assets/vocab/u5_water.webp\" alt=\"물\"><div class=\"vw-main\"><div class=\"vw-ko\">물</div><div class=\"vw-rom\">mul</div><div class=\"vw-en\">water</div></div><button class=\"vw-tts\" onclick=\"tts('물')\" aria-label=\"듣기\">🔊</button></div><div class=\"vw-card\"><img class=\"vw-thumb\" src=\"assets/vocab/u5_coffee.webp\" alt=\"커피\"><div class=\"vw-main\"><div class=\"vw-ko\">커피</div><div class=\"vw-rom\">keopi</div><div class=\"vw-en\">coffee</div></div><button class=\"vw-tts\" onclick=\"tts('커피')\" aria-label=\"듣기\">🔊</button></div></div><div class=\"vs-box\"><div class=\"vs-title\">💬 자주 쓰는 말</div><div class=\"vs-line\"><span class=\"vs-ko\">저는 한국 음식을 좋아해요.</span><button class=\"vu-btn\" onclick=\"tts('저는 한국 음식을 좋아해요.')\" aria-label=\"읽어 주기\">🔊</button></div><div class=\"vs-line\"><span class=\"vs-ko\">매일 아침 물을 마셔요.</span><button class=\"vu-btn\" onclick=\"tts('매일 아침 물을 마셔요.')\" aria-label=\"읽어 주기\">🔊</button></div><div class=\"vs-line\"><span class=\"vs-ko\">채아는 커피를 마셔요.</span><button class=\"vu-btn\" onclick=\"tts('채아는 커피를 마셔요.')\" aria-label=\"읽어 주기\">🔊</button></div></div><div class=\"vl-link\">🔗 먹고 마시는 것들은 <b>목적어</b>라서 을/를을 붙여요: 음식(ㄱ) → <b>음식을</b>, 물(ㄹ) → <b>물을</b>, 커피(모음) → <b>커피를</b>.</div>\n</div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[5-1] Reading — Fill in the Blank — 을/를</span></div><div class=\"p-dir\">받침을 생각하며 맞는 조사를 고르세요.</div><div class=\"p-q\">저는 한국 음악(<span class=\"blank\">    </span>) 좋아해요.</div><div class=\"opts\" data-q=\"u5q1\"><button class=\"opt\" onclick=\"checkQ('u5q1',0,this)\"><span class=\"o-idx\">1</span>을<span class=\"o-gl\">✅✅ 음악은 받침 ㄱ으로 끝나요 → 을</span></button><button class=\"opt\" onclick=\"checkQ('u5q1',0,this)\"><span class=\"o-idx\">2</span>를<span class=\"o-gl\">❌ ❌ 를은 받침 없는 단어(노래·커피)에</span></button><button class=\"opt\" onclick=\"checkQ('u5q1',0,this)\"><span class=\"o-idx\">3</span>은<span class=\"o-gl\">❌ ❌ 은/는은 주제 조사예요</span></button><button class=\"opt\" onclick=\"checkQ('u5q1',0,this)\"><span class=\"o-idx\">4</span>는<span class=\"o-gl\">❌ ❌ 은/는은 주제 조사예요</span></button></div><div class=\"p-feedback\" id=\"fb-u5q1\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style='margin-bottom:5px;'>The last syllable of 음악 (音樂), '악', ends in the final consonant <b>ㄱ</b> &#8594; so the object particle is <b class=hl>을</b>. '<b class=hl>저는 음악을 좋아해요</b>' is correct.</div><div>Words with no final consonant (노래 · 커피) take <b class=hl>를</b>, while 은/는 marks the topic (subject) &#8212; not the object.</div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[5-2] Reading — Fill in the Blank — 을/를</span></div><div class=\"p-dir\">받침을 생각하며 맞는 조사를 고르세요.</div><div class=\"p-q\">다희는 노래(<span class=\"blank\">    </span>) 좋아해요.</div><div class=\"opts\" data-q=\"u5q2\"><button class=\"opt\" onclick=\"checkQ('u5q2',1,this)\"><span class=\"o-idx\">1</span>을<span class=\"o-gl\">❌ ❌ 노래는 받침이 없어요 → 를</span></button><button class=\"opt\" onclick=\"checkQ('u5q2',1,this)\"><span class=\"o-idx\">2</span>를<span class=\"o-gl\">✅✅ 노래는 모음 ㅐ로 끝나요 → 를</span></button><button class=\"opt\" onclick=\"checkQ('u5q2',1,this)\"><span class=\"o-idx\">3</span>이<span class=\"o-gl\">❌ ❌ 이/가는 주어를 표시해요</span></button><button class=\"opt\" onclick=\"checkQ('u5q2',1,this)\"><span class=\"o-idx\">4</span>가<span class=\"o-gl\">❌ ❌ 이/가는 주어를 표시해요</span></button></div><div class=\"p-feedback\" id=\"fb-u5q2\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style='margin-bottom:5px;'>The last syllable of 노래, '래', has no final consonant &#8212; it ends in the <b>vowel ㅐ</b> &#8594; so it&#8217;s <b class=hl>노래를</b>. '<b class=hl>다희는 노래를 좋아해요</b>' is correct.</div><div>이/가 attach to the doer of the sentence (subject), while 을/를 attach to the thing the action reaches (object).</div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[5-3] Reading — Choose the Correct Sentence</span></div><div class=\"p-dir\">케이팝을 좋아하는 문장을 고르세요. — “I like K-POP.”</div><div class=\"p-q\">저는 케이팝 ______.</div><div class=\"opts\" data-q=\"u5q3\"><button class=\"opt\" onclick=\"checkQ('u5q3',0,this)\"><span class=\"o-idx\">1</span>저는 케이팝을 좋아해요.<span class=\"o-gl\">✅✅ 케이팝 '팝'은 받침 ㅂ → 케이팝을</span></button><button class=\"opt\" onclick=\"checkQ('u5q3',0,this)\"><span class=\"o-idx\">2</span>저는 케이팝를 좋아해요.<span class=\"o-gl\">❌ ❌ 받침이 있으면 를을 못 써요</span></button><button class=\"opt\" onclick=\"checkQ('u5q3',0,this)\"><span class=\"o-idx\">3</span>저는 케이팝이 좋아해요.<span class=\"o-gl\">❌ ❌ 이는 주어 조사예요</span></button><button class=\"opt\" onclick=\"checkQ('u5q3',0,this)\"><span class=\"o-idx\">4</span>저는 케이팝은 좋아해요.<span class=\"o-gl\">❌ ❌ 은은 대조/주제를 나타내요</span></button></div><div class=\"p-feedback\" id=\"fb-u5q3\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style='margin-bottom:5px;'>Loanwords like K-POP work the same way &#8212; the last syllable '팝' ends in the consonant <b class=hl>ㅂ</b> &#8594; so '<b class=hl>케이팝을</b> 좋아해요' is correct.</div><div>Adding 를 to a word that has a final consonant (like 케이팝<b>를</b>) is the most common mistake &#8212; watch out!</div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[5-4] Reading — Fill in the Blank — 싫어해요</span></div><div class=\"p-dir\">받침을 생각하며 맞는 조사를 고르세요.</div><div class=\"p-q\">로이는 매운 음식(<span class=\"blank\">    </span>) 싫어해요.</div><div class=\"opts\" data-q=\"u5q4\"><button class=\"opt\" onclick=\"checkQ('u5q4',1,this)\"><span class=\"o-idx\">1</span>를<span class=\"o-gl\">❌ ❌ 음식의 끝 '식'은 받침 ㄱ → 을</span></button><button class=\"opt\" onclick=\"checkQ('u5q4',1,this)\"><span class=\"o-idx\">2</span>을<span class=\"o-gl\">✅✅ 매운 음식(받침 ㄱ) → 음식을</span></button><button class=\"opt\" onclick=\"checkQ('u5q4',1,this)\"><span class=\"o-idx\">3</span>에<span class=\"o-gl\">❌ ❌ 에는 장소/시간을 표시해요</span></button><button class=\"opt\" onclick=\"checkQ('u5q4',1,this)\"><span class=\"o-idx\">4</span>가<span class=\"o-gl\">❌ ❌ 가는 주어를 표시해요</span></button></div><div class=\"p-feedback\" id=\"fb-u5q4\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style='margin-bottom:5px;'>'음식' ends in '식', with the final consonant <b class=hl>ㄱ</b> &#8594; so it&#8217;s <b class=hl>음식을</b> 싫어해요.</div><div>싫어해요 takes an <b>object (을/를)</b> just like 좋아해요: '<b class=hl>로이는 매운 음식을 싫어해요</b>'.</div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[5-5] Reading — Fill in the Blank — -고 싶어요</span></div><div class=\"p-dir\">하고 싶은 일을 나타내는 말을 고르세요.</div><div class=\"p-q\">배가 고파요! 저는 한국 음식을 <span class=\"blank\">(    )</span>.</div><div class=\"opts\" data-q=\"u5q5\"><button class=\"opt\" onclick=\"checkQ('u5q5',0,this)\"><span class=\"o-idx\">1</span>먹고 싶어요<span class=\"o-gl\">✅✅ 먹다 → 먹<u>고 싶어요</u> (want to eat)</span></button><button class=\"opt\" onclick=\"checkQ('u5q5',0,this)\"><span class=\"o-idx\">2</span>먹어요 싶어요<span class=\"o-gl\">❌ ❌ -고 싶어요 순서를 바꾸면 안 돼요</span></button><button class=\"opt\" onclick=\"checkQ('u5q5',0,this)\"><span class=\"o-idx\">3</span>먹을까 싶어요<span class=\"o-gl\">❌ ❌ 먹을까 싶어요는 추측이에요</span></button><button class=\"opt\" onclick=\"checkQ('u5q5',0,this)\"><span class=\"o-idx\">4</span>먹다 싶어요<span class=\"o-gl\">❌ ❌ 어간 + 고 싶어요 형태예요</span></button></div><div class=\"p-feedback\" id=\"fb-u5q5\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style='margin-bottom:5px;'>For something you want to do, use the verb stem + <b class=hl>-고 싶어요</b>: 먹<b>다</b> &#8594; 먹<b class=hl>고 싶어요</b>.</div><div>The object 음식 (final consonant ㄱ) takes <b class=hl>을</b>, so '<b class=hl>한국 음식을 먹고 싶어요</b>' sounds natural.</div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[5-6] Reading — Choose by Situation</span></div><div class=\"p-dir\">상황에 맞는 문장을 고르세요.</div><div class=\"p-q\">지금 밤 12시예요. 너무 피곤해요. 저는 ______.</div><div class=\"opts\" data-q=\"u5q6\"><button class=\"opt\" onclick=\"checkQ('u5q6',0,this)\"><span class=\"o-idx\">1</span>자고 싶어요<span class=\"o-gl\">✅✅ 피곤하면 → 자고 싶어요 (want to sleep)</span></button><button class=\"opt\" onclick=\"checkQ('u5q6',0,this)\"><span class=\"o-idx\">2</span>먹고 싶어요<span class=\"o-gl\">❌ ❌ 배가 고픈 게 아니라 피곤해요</span></button><button class=\"opt\" onclick=\"checkQ('u5q6',0,this)\"><span class=\"o-idx\">3</span>여행하고 싶어요<span class=\"o-gl\">❌ ❌ 상황과 맞지 않아요</span></button><button class=\"opt\" onclick=\"checkQ('u5q6',0,this)\"><span class=\"o-idx\">4</span>공부하고 싶어요<span class=\"o-gl\">❌ ❌ 잠이 와서 공부는 힘들어요</span></button></div><div class=\"p-feedback\" id=\"fb-u5q6\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style='margin-bottom:5px;'>When you are tired, the thing you want to do is <b class=hl>자고 싶어요</b> (want to sleep). 자<b>다</b> &#8594; 자<b class=hl>고 싶어요</b> (-고 싶어요 = want to).</div><div>This sentence has no object. When there IS an object, it takes 을/를 before it: '잠을 자고 싶어요'.</div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[5-7] Listening — Listen &amp; Choose</span></div><div class=\"p-dir\">🔊 듣고 채아가 마시는 것을 고르세요.</div><button class=\"p-audio\" onclick=\"tts('채아는 커피를 마셔요.')\">🔊 Listen</button><div class=\"p-q\">채아는 무엇을 마셔요?</div><div class=\"opts\" data-q=\"u5q7\"><button class=\"opt\" onclick=\"checkQ('u5q7',1,this)\"><span class=\"o-idx\">1</span>물<span class=\"o-gl\">❌ ❌ 물은 마시지만 채아는 커피를 마셔요</span></button><button class=\"opt\" onclick=\"checkQ('u5q7',1,this)\"><span class=\"o-idx\">2</span>커피<span class=\"o-gl\">✅✅ “커피를 마셔요” — 목적어는 커피</span></button><button class=\"opt\" onclick=\"checkQ('u5q7',1,this)\"><span class=\"o-idx\">3</span>음식<span class=\"o-gl\">❌ ❌ 음식은 먹어요</span></button><button class=\"opt\" onclick=\"checkQ('u5q7',1,this)\"><span class=\"o-idx\">4</span>게임<span class=\"o-gl\">❌ ❌ 게임은 해요 (마셔요 아님)</span></button></div><div class=\"p-feedback\" id=\"fb-u5q7\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style='margin-bottom:5px;'>\"채아는 커피<b class=hl>를</b> 마셔요.\" &#8212; the thing being drunk (the object) is <b>커피</b>. 커피 ends in a vowel &#8594; <b class=hl>커피를</b>.</div><div>물 ends in the consonant ㄹ &#8594; <b class=hl>물을</b>. Listen carefully &#8212; whether a word takes 을 or 를 changes with its final consonant.</div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[5-8] Listening — Listen &amp; Choose</span></div><div class=\"p-dir\">🔊 듣고 로이가 좋아하는 것을 고르세요.</div><button class=\"p-audio\" onclick=\"tts('로이는 여행을 좋아해요. 그런데 게임은 싫어해요.')\">🔊 Listen</button><div class=\"p-q\">로이는 무엇을 좋아해요?</div><div class=\"opts\" data-q=\"u5q8\"><button class=\"opt\" onclick=\"checkQ('u5q8',1,this)\"><span class=\"o-idx\">1</span>게임<span class=\"o-gl\">❌ ❌ 게임은 싫어해요 (그런데)</span></button><button class=\"opt\" onclick=\"checkQ('u5q8',1,this)\"><span class=\"o-idx\">2</span>여행<span class=\"o-gl\">✅✅ “여행을 좋아해요” — 좋아하는 대상</span></button><button class=\"opt\" onclick=\"checkQ('u5q8',1,this)\"><span class=\"o-idx\">3</span>운동<span class=\"o-gl\">❌ ❌ 들리지 않아요</span></button><button class=\"opt\" onclick=\"checkQ('u5q8',1,this)\"><span class=\"o-idx\">4</span>노래<span class=\"o-gl\">❌ ❌ 들리지 않아요</span></button></div><div class=\"p-feedback\" id=\"fb-u5q8\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style='margin-bottom:5px;'>\"로이는 여행<b class=hl>을</b> 좋아해요. 그런데 게임<b class=hl>은</b> 싫어해요.\" &#8212; the thing she likes (the object) is <b class=hl>여행</b>.</div><div>여행 (final consonant ㅇ) &#8594; <b class=hl>을</b>. In '게임은', the 은 is a topic particle used for contrast &#8212; not an object marker.</div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[5-9] Listening — Listen &amp; Choose</span></div><div class=\"p-dir\">🔊 듣고 화자가 하고 싶은 일을 고르세요.</div><button class=\"p-audio\" onclick=\"tts('방학에 저는 한국에 가고 싶어요.')\">🔊 Listen</button><div class=\"p-q\">화자는 무엇을 하고 싶어요?</div><div class=\"opts\" data-q=\"u5q9\"><button class=\"opt\" onclick=\"checkQ('u5q9',0,this)\"><span class=\"o-idx\">1</span>한국에 가고 싶어요<span class=\"o-gl\">✅✅ “한국에 가고 싶어요” — 하고 싶은 일</span></button><button class=\"opt\" onclick=\"checkQ('u5q9',0,this)\"><span class=\"o-idx\">2</span>노래를 하고 싶어요<span class=\"o-gl\">❌ ❌ 노래 얘기는 없어요</span></button><button class=\"opt\" onclick=\"checkQ('u5q9',0,this)\"><span class=\"o-idx\">3</span>자고 싶어요<span class=\"o-gl\">❌ ❌ 자는 얘기는 없어요</span></button><button class=\"opt\" onclick=\"checkQ('u5q9',0,this)\"><span class=\"o-idx\">4</span>음식을 먹고 싶어요<span class=\"o-gl\">❌ ❌ 먹는 얘기는 없어요</span></button></div><div class=\"p-feedback\" id=\"fb-u5q9\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style='margin-bottom:5px;'>\"방학에 저는 한국에 <b class=hl>가고 싶어요</b>.\" &#8212; to say what you want to do, use <b class=hl>-고 싶어요</b>.</div><div>가<b>다</b> &#8594; 가<b class=hl>고 싶어요</b> = want to go. Just a verb + 고 싶어요 is enough &#8212; no object needed.</div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[5-10] Listening — Listen &amp; Choose</span></div><div class=\"p-dir\">🔊 듣고 아란이 하는 것을 고르세요.</div><button class=\"p-audio\" onclick=\"tts('아란은 매일 밤 게임을 해요.')\">🔊 Listen</button><div class=\"p-q\">아란은 무엇을 해요?</div><div class=\"opts\" data-q=\"u5q10\"><button class=\"opt\" onclick=\"checkQ('u5q10',2,this)\"><span class=\"o-idx\">1</span>춤<span class=\"o-gl\">❌ ❌ 춤을 추는 게 아니에요</span></button><button class=\"opt\" onclick=\"checkQ('u5q10',2,this)\"><span class=\"o-idx\">2</span>운동<span class=\"o-gl\">❌ ❌ 운동하는 게 아니에요</span></button><button class=\"opt\" onclick=\"checkQ('u5q10',2,this)\"><span class=\"o-idx\">3</span>게임<span class=\"o-gl\">✅✅ “게임을 해요” — 하는 대상(목적어)</span></button><button class=\"opt\" onclick=\"checkQ('u5q10',2,this)\"><span class=\"o-idx\">4</span>커피<span class=\"o-gl\">❌ ❌ 커피는 마시는 거예요</span></button></div><div class=\"p-feedback\" id=\"fb-u5q10\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style='margin-bottom:5px;'>\"아란은 매일 밤 게임<b class=hl>을</b> 해요.\" &#8212; the thing she does (the object) is <b class=hl>게임</b>. 게임 (final consonant ㅁ) &#8594; <b class=hl>을</b>.</div><div>The answer is <b>게임을 해요</b> &#8212; not dancing a dance (춤을 추다) or doing exercise (운동을 하다).</div></div></div></div>"}, {"cls": "culture", "html": "<div class=\"culture\">\n    <span class=\"c-label\">🎤 K-POP TIP</span>\n    <h3>Essential Idol Interview Question</h3>\n    <p>A question you hear often in interviews: <b>\"뭐를 좋아해요?\"</b> (What do you like?) — Introduce your 최애 (ultimate favorite) idol!</p>\n    <div class=\"c-tip\">💖 최애 = your absolute favorite thing/person. \"제 최애는 꿈아란에요!\" — fan language!</div>\n  </div>\n\n<!-- ============================================================\n     UNIT 6 — FOOD\n     ============================================================ -->"}]}, {"id": 6, "sections": [{"cls": "unit-flag", "html": "<div class=\"unit-flag\">UNIT 6 · FOOD</div>\n  "}, {"cls": "sec-title", "html": "<div class=\"sec-title\"><div class=\"no\">6</div><div><h2>Tteokbokki is Spicy</h2><div class=\"en\">떡볶이는 매워요 — Food · 안/못</div></div></div>\n  "}, {"cls": "story", "html": "<div class=\"story\">\n    <img class=\"story-art\" src=\"assets/glowsis/aran.png\" alt=\"아란\">\n    <div class=\"story-body\">\n      <span class=\"story-tag\">💿 GLOWSIS STORY · 6/8</span>\n      <h3>아란의 맛있는 휴게소 — \"떡볶이는 매워요!\"</h3>\n      <p><b>아란</b>은 한국 음식에 푹 빠졌어요 — 떡볶이, 김밥, 치킨! <b>맛을 말하는 법</b>을 알면 팬들에게 한국 음식을 소개할 수 있어요. \"맛있어요!\" 🍜</p>\n      <span class=\"story-piece\">🍜 GLOW POINT 6/8 획득 — Food & Taste!</span>\n    </div>\n  </div>\n"}, {"cls": "goals", "html": "<div class=\"goals\">\n    <div class=\"goal\"><span class=\"g-ico\">🍜</span> Food vocabulary</div>\n    <div class=\"goal\"><span class=\"g-ico\">😋</span> Taste adjectives</div>\n    <div class=\"goal\"><span class=\"g-ico\">🚫</span> 안 + verb (negation)</div>\n  </div>\n\n  "}, {"cls": "dialog", "html": "<div class=\"dialog\">\n    <div class=\"d-head\">\n      <span class=\"d-title\">💬 Dialogue 6 — Spicy Food</span>\n      <span class=\"d-scene\">🍽️ Eating at the rest stop</span>\n    </div>\n    <div class=\"d-line\"><img src=\"assets/glowsis/roy.png\" alt=\"로이\">\n      <div class=\"d-bubble\"><div class=\"who\">로이</div><div class=\"ko\">떡볶이 먹어요? 맛있어요!</div><div class=\"gl\">Want to eat tteokbokki? It's delicious!</div></div>\n    </div>\n    <div class=\"d-line me\"><img src=\"assets/glowsis/chaea.png\" alt=\"채아\">\n      <div class=\"d-bubble\"><div class=\"who\">채아</div><div class=\"ko\">떡볶이는 매워요. 저는 매운 음식을 안 먹어요.</div><div class=\"gl\">Tteokbokki is spicy. I don't eat spicy food.</div></div>\n    </div>\n    <div class=\"d-line\"><img src=\"assets/glowsis/aran.png\" alt=\"아란\">\n      <div class=\"d-bubble\"><div class=\"who\">아란</div><div class=\"ko\">김밥은 안 매워요. 김밥 먹어요!</div><div class=\"gl\">Gimbap isn't spicy. Let's eat gimbap!</div></div>\n    </div>\n    <div class=\"d-line me\"><img src=\"assets/glowsis/dahee.png\" alt=\"다희\">\n      <div class=\"d-bubble\"><div class=\"who\">다희</div><div class=\"ko\">좋아요! 저는 김밥을 좋아해요. 맛있어요!</div><div class=\"gl\">Great! I like gimbap. It's delicious!</div></div>\n    </div>\n  </div>\n\n  "}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">GRAMMAR 1</span>\n    <div class=\"g-point\">Taste Expressions — Adjectives</div>\n    <div class=\"g-rule\">A TOPIK I food-question favorite! Use adjectives to describe taste.</div>\n    <div class=\"g-ex\">\n      <div class=\"ex\"><span class=\"ko\">맛있어요 / 맛없어요</span><span class=\"gl\">delicious / not tasty</span></div>\n      <div class=\"ex\"><span class=\"ko\">매워요 / 안 매워요</span><span class=\"gl\">spicy / not spicy</span></div>\n      <div class=\"ex\"><span class=\"ko\">달아요 / 짜요 / 시어요</span><span class=\"gl\">sweet / salty / sour</span></div>\n      <div class=\"ex\"><span class=\"ko\">따뜻해요 / 차가워요</span><span class=\"gl\">warm / cold</span></div>\n    </div>\n  </div>\n\n  "}, {"cls": "teach", "html": "<div class=\"teach\">\n  <span class=\"t-label\">🧑🏫 Teacher's Deep-Dive · Taste adjective conjugation (맛 형용사)</span>\n  <div class=\"t-q\"><span class=\"t-ko\">맵다 → 매워요 · 달다 → 달아요 · 짜다 → 짜요</span> <span class=\"t-en\">= How taste adjectives conjugate</span></div>\n  <div class=\"t-row t-head\">\n    <div class=\"t-why\">Why do the shapes change? The dictionary form and the spoken form are different.</div>\n    <div class=\"t-deep\">\n      Every taste adjective in the dictionary ends in <b>다</b> — 맵다 · 달다 · 짜다 · 맛있다. To speak politely, we add <b>-아요 / -어요</b> to the stem to make the <b>해요체</b> (polite) form. But the <b>final-consonant rules (받침)</b> can change the sound, which is why 맵다 becomes 매워요.\n    </div>\n  </div>\n  <div class=\"t-grid\">\n    <div class=\"t-cell\">\n      <div class=\"t-word\">맵다 → 매워요</div>\n      <div class=\"t-role\">ㅂ irregular <span class=\"t-sub\">final ㅂ changes to 우</span></div>\n      <div class=\"t-note\">맵 + 어요 → the ㅂ turns into <b>우</b>, so we get <b>매워요</b>.<br>쉽다 → 쉬워요 follows the same rule</div>\n    </div>\n    <div class=\"t-op\">+</div>\n    <div class=\"t-cell\">\n      <div class=\"t-word\">달다 → 달아요</div>\n      <div class=\"t-role\">ㄹ irregular <span class=\"t-sub\">ㄹ stays before a vowel</span></div>\n      <div class=\"t-note\">달 + 아요 → <b>달아요</b>.<br>(before ㄴ it shortens to <b>단</b> → 단 음식 \"sweet food\")</div>\n    </div>\n    <div class=\"t-op\">+</div>\n    <div class=\"t-cell\">\n      <div class=\"t-word\">짜다 → 짜요</div>\n      <div class=\"t-role\">ㅏ contraction <span class=\"t-sub\">matching vowels squeeze together</span></div>\n      <div class=\"t-note\">짜 + 아요 → 짜아요 → <b>짜요</b>.<br>맛있다 → 맛있어요 (regular form)</div>\n    </div>\n  </div>\n  <div class=\"t-insight\">\n    <b class=\"t-i-ko\">Taste adjectives = 다 → 해요(요):</b> <b>매워요 · 달아요 · 짜요 · 맛있어요</b>.\n    That's why we don't say \"떡볶이는 맵다\" — we say <b>\"떡볶이는 매워요\"</b>. To make a negative, just put <b>안</b> in front of the adjective — 안 매워요.\n  </div>\n  <div class=\"t-compare\">\n    <div class=\"t-c-a\"><b>안 — \"안 해요\" = a choice</b><br><span class=\"t-ko\">매운 음식을 <b>안</b> 먹어요.</span><br><span class=\"t-en\">I don't eat it (I decided not to) · 김밥은 <b>안</b> 매워요 = not spicy</span></div>\n    <div class=\"t-c-b\"><b>못 — \"못 해요\" = ability</b><br><span class=\"t-ko\">매운 음식을 <b>못</b> 먹어요.</span><br><span class=\"t-en\">I can't eat it (I am unable to) · 노래를 <b>못</b> 해요 = can't sing</span></div>\n  </div>\n  <div class=\"t-tip\">\n    💡 <b>Memory tip:</b> <b>안</b> = \"I don't want to do it\" (don't · a choice), <b>못</b> = \"I can't, I'm not able to\" (can't · ability).\n    Conjugation rules: <b>ㅂ → 워요</b>, and if two <b>ㅏ</b> vowels meet, squeeze them into one. Just remember: the dictionary <b>다 → becomes 요 when you speak</b>!\n  </div>\n</div>"}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">GRAMMAR 2</span>\n    <div class=\"g-point\">안 + Verb — Negation</div>\n    <div class=\"g-rule\">Put <b>안</b> before a verb/adjective to say \"don't ~\". <b>못</b> means \"can't\" (lack of ability).</div>\n    <div class=\"g-ex\">\n      <div class=\"ex\"><span class=\"ko\">매운 음식을 <b>안</b> 먹어요.</span><span class=\"gl\">I don't eat spicy food.</span></div>\n      <div class=\"ex\"><span class=\"ko\">저는 노래를 <b>못</b> 해요.</span><span class=\"gl\">I can't sing.</span></div>\n      <div class=\"ex\"><span class=\"ko\">오늘은 <b>안</b> 추워요.</span><span class=\"gl\">It's not cold today.</span></div>\n    </div>\n  </div>\n\n    "}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">GRAMMAR 3</span>\n    <div class=\"g-point\">못 + verb — \"can't ~\"</div>\n    <div class=\"g-rule\"><b>안</b> = \"don't\" (choice), <b>못</b> = \"can't\" (no ability). Both go before the verb. Compare: 안 먹어요 vs 못 먹어요!</div>\n    <div class=\"g-ex\">\n      <div class=\"ex\"><span class=\"ko\">저는 매운 음식을 <b>못</b> 먹어요.</span><span class=\"gl\">I can't eat spicy food.</span></div>\n      <div class=\"ex\"><span class=\"ko\">오늘은 운동을 <b>못</b> 해요.</span><span class=\"gl\">I can't exercise today.</span></div>\n      <div class=\"ex\"><span class=\"ko\">노래를 <b>못</b> 해요.</span><span class=\"gl\">I can't sing.</span></div>\n    </div>\n  </div>\n\n"}, {"cls": "vocab-grid", "html": "<div class=\"vocab-lab\"><div class=\"vl-toolbar\"><span class=\"vl-hint\">카테고리를 눌러 그림과 함께 공부하세요</span><button class=\"vl-expand\" onclick=\"glowVocabAll()\">모두 펼치기</button></div><div class=\"vl-cat open\" data-tone=\"pink\"><button class=\"vl-cat-head\" onclick=\"glowVocab(this)\"><span class=\"vl-cat-ico\">🍲</span><span class=\"vl-cat-name\">매운 & 인기 한국 음식<small>Spicy Korean food · 길거리 음식</small></span><span class=\"vl-cat-count\">5</span><span class=\"vl-cat-arr\">▾</span></button><div class=\"vl-cat-body\"><div class=\"vw-grid\"><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u6_tteokbokki.webp\" alt=\"떡볶이\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('떡볶이')\">🔊</button><div class=\"vw-ko\">떡볶이</div><div class=\"vw-rom\">tteokbokki</div><div class=\"vw-en\">spicy rice cakes</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u6_gimbap.webp\" alt=\"김밥\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('김밥')\">🔊</button><div class=\"vw-ko\">김밥</div><div class=\"vw-rom\">gimbap</div><div class=\"vw-en\">seaweed rice roll</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u6_chicken.webp\" alt=\"치킨\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('치킨')\">🔊</button><div class=\"vw-ko\">치킨</div><div class=\"vw-rom\">chikin</div><div class=\"vw-en\">fried chicken</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u6_mandu.webp\" alt=\"만두\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('만두')\">🔊</button><div class=\"vw-ko\">만두</div><div class=\"vw-rom\">mandu</div><div class=\"vw-en\">dumplings</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u6_ramyeon.webp\" alt=\"라면\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('라면')\">🔊</button><div class=\"vw-ko\">라면</div><div class=\"vw-rom\">ramyeon</div><div class=\"vw-en\">instant noodles</div></div></div></div><div class=\"vs-box\"><div class=\"vs-head\">💬 이 단어로 자주 쓰는 말</div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('떡볶이는 매워요.')\">🔊</button><div><span class=\"vs-ko\">떡볶이는 매워요.</span> <span class=\"vs-en\">Tteokbokki is spicy.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('저는 김밥을 좋아해요.')\">🔊</button><div><span class=\"vs-ko\">저는 김밥을 좋아해요.</span> <span class=\"vs-en\">I like gimbap.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('치킨이 정말 맛있어요.')\">🔊</button><div><span class=\"vs-ko\">치킨이 정말 맛있어요.</span> <span class=\"vs-en\">The chicken is really delicious.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('만두를 먹어요.')\">🔊</button><div><span class=\"vs-ko\">만두를 먹어요.</span> <span class=\"vs-en\">I eat dumplings.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('라면이 뜨거워요. 조심하세요.')\">🔊</button><div><span class=\"vs-ko\">라면이 뜨거워요. 조심하세요.</span> <span class=\"vs-en\">The ramen is hot. Be careful.</span></div></div></div><div class=\"vl-link\">🌶️ <b>같이 쓰는 말:</b> <b>매운 음식</b> = 떡볶이·라면·치킨 → 모두 <b>매워요</b>. 김밥·만두는 <b>안 매워요</b>.</div></div></div><div class=\"vl-cat\" data-tone=\"mint\"><button class=\"vl-cat-head\" onclick=\"glowVocab(this)\"><span class=\"vl-cat-ico\">🥤</span><span class=\"vl-cat-name\">간식 & 음료<small>Snacks & drinks · 마시고 먹는 것</small></span><span class=\"vl-cat-count\">4</span><span class=\"vl-cat-arr\">▾</span></button><div class=\"vl-cat-body\"><div class=\"vw-grid\"><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u6_cola.webp\" alt=\"콜라\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('콜라')\">🔊</button><div class=\"vw-ko\">콜라</div><div class=\"vw-rom\">kolla</div><div class=\"vw-en\">cola</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u6_bread.webp\" alt=\"빵\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('빵')\">🔊</button><div class=\"vw-ko\">빵</div><div class=\"vw-rom\">ppang</div><div class=\"vw-en\">bread</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u6_fruit.webp\" alt=\"과일\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('과일')\">🔊</button><div class=\"vw-ko\">과일</div><div class=\"vw-rom\">gwail</div><div class=\"vw-en\">fruit</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u6_cake.webp\" alt=\"케이크\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('케이크')\">🔊</button><div class=\"vw-ko\">케이크</div><div class=\"vw-rom\">keikeu</div><div class=\"vw-en\">cake</div></div></div></div><div class=\"vs-box\"><div class=\"vs-head\">💬 이 단어로 자주 쓰는 말</div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('콜라를 마셔요.')\">🔊</button><div><span class=\"vs-ko\">콜라를 마셔요.</span> <span class=\"vs-en\">I drink cola.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('아침에 빵을 먹어요.')\">🔊</button><div><span class=\"vs-ko\">아침에 빵을 먹어요.</span> <span class=\"vs-en\">I eat bread in the morning.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('과일을 좋아해요.')\">🔊</button><div><span class=\"vs-ko\">과일을 좋아해요.</span> <span class=\"vs-en\">I like fruit.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('케이크는 달아요.')\">🔊</button><div><span class=\"vs-ko\">케이크는 달아요.</span> <span class=\"vs-en\">The cake is sweet.</span></div></div></div><div class=\"vl-link\">🥤 <b>관찰:</b> 콜라·케이크는 <b>달아요</b>(단 음식). 과일도 달지만 <b>건강</b>해요. 간식·음료의 맛은 <b>맛 형용사</b>로 말해요!</div></div></div><div class=\"vl-cat\" data-tone=\"sky\"><button class=\"vl-cat-head\" onclick=\"glowVocab(this)\"><span class=\"vl-cat-ico\">😋</span><span class=\"vl-cat-name\">맛 표현 형용사<small>Taste adjectives · 맛을 말해요</small></span><span class=\"vl-cat-count\">4</span><span class=\"vl-cat-arr\">▾</span></button><div class=\"vl-cat-body\"><div class=\"vw-grid\"><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u6_delicious.webp\" alt=\"맛있다\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('맛있어요')\">🔊</button><div class=\"vw-ko\">맛있다</div><div class=\"vw-rom\">masitda</div><div class=\"vw-en\">delicious</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u6_spicy.webp\" alt=\"맵다\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('매워요')\">🔊</button><div class=\"vw-ko\">맵다</div><div class=\"vw-rom\">maepta</div><div class=\"vw-en\">spicy</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u6_sweet.webp\" alt=\"달다\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('달아요')\">🔊</button><div class=\"vw-ko\">달다</div><div class=\"vw-rom\">dalda</div><div class=\"vw-en\">sweet</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u6_salty.webp\" alt=\"짜다\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('짜요')\">🔊</button><div class=\"vw-ko\">짜다</div><div class=\"vw-rom\">jjada</div><div class=\"vw-en\">salty</div></div></div></div><div class=\"vs-box\"><div class=\"vs-head\">💬 이 단어로 자주 쓰는 말</div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('음식이 정말 맛있어요.')\">🔊</button><div><span class=\"vs-ko\">음식이 정말 맛있어요.</span> <span class=\"vs-en\">The food is really delicious.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('이 음식은 안 매워요.')\">🔊</button><div><span class=\"vs-ko\">이 음식은 안 매워요.</span> <span class=\"vs-en\">This food is not spicy.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('케이크가 달아요.')\">🔊</button><div><span class=\"vs-ko\">케이크가 달아요.</span> <span class=\"vs-en\">The cake is sweet.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('감자칩은 짜요.')\">🔊</button><div><span class=\"vs-ko\">감자칩은 짜요.</span> <span class=\"vs-en\">Potato chips are salty.</span></div></div></div><div class=\"vl-link\">🔄 <b>반대 & 짝:</b> 맛있다 ↔ 맛없다 · (안) 맵다 · (안) 짜다. 활용: 맵다→<b>매워요</b>, 달다→<b>달아요</b>, 짜다→<b>짜요</b>, 맛있다→<b>맛있어요</b>.</div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[6-1] Reading — Which Food?</span></div><div class=\"p-dir\">Read the description and choose the food.</div><div class=\"p-passage\">🍽️ 이것은 길쭉한 흰 쌀밥을 김이로 말아서 만든 음식이에요. 안에 단무지와 당근, 계란이 있어요.</div><div class=\"p-q\">이 음식은 뭐예요?</div><div class=\"opts\" data-q=\"u6q1\"><button class=\"opt\" onclick=\"checkQ('u6q1',1,this)\"><span class=\"o-idx\">1</span>떡볶이<span class=\"o-gl\">❌ 매운 떡 요리</span></button><button class=\"opt\" onclick=\"checkQ('u6q1',1,this)\"><span class=\"o-idx\">2</span>김밥<span class=\"o-gl\">✅ 김으로 말아요 — 정답</span></button><button class=\"opt\" onclick=\"checkQ('u6q1',1,this)\"><span class=\"o-idx\">3</span>라면<span class=\"o-gl\">❌ 국수 요리</span></button><button class=\"opt\" onclick=\"checkQ('u6q1',1,this)\"><span class=\"o-idx\">4</span>케이크<span class=\"o-gl\">❌ 생일 때 먹는 빵</span></button></div><div class=\"p-feedback\" id=\"fb-u6q1\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">The passage describes food made by rolling white rice in <b class=\"hl\">김</b> (seaweed), so the answer is <b class=\"hl\">김밥</b>. The fillings — 단무지 (pickled radish), 당근 (carrot), and 계란 (egg) — are the clue.</div><div style=\"margin-bottom:5px;\">떡볶이 is a spicy stir-fried rice-cake dish, 라면 is noodles, and 케이크 is a sweet cake. None of these match \"rolled in seaweed,\" so they are wrong.</div></div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[6-2] Listening — What is it like?</span></div><div class=\"p-dir\">🔊 Listen and choose the correct answer.</div><button class=\"p-audio\" onclick=\"tts('이 케이크는 정말 달아요. 케이크를 좋아해요.')\">🔊 Listen</button><div class=\"p-q\">케이크는 어때요?</div><div class=\"opts\" data-q=\"u6q2\"><button class=\"opt\" onclick=\"checkQ('u6q2',0,this)\"><span class=\"o-idx\">1</span>달아요<span class=\"o-gl\">✅ 단맛 — 정답</span></button><button class=\"opt\" onclick=\"checkQ('u6q2',0,this)\"><span class=\"o-idx\">2</span>매워요<span class=\"o-gl\">❌ 매운맛은 아님</span></button><button class=\"opt\" onclick=\"checkQ('u6q2',0,this)\"><span class=\"o-idx\">3</span>짜요<span class=\"o-gl\">❌ 짠맛은 아님</span></button><button class=\"opt\" onclick=\"checkQ('u6q2',0,this)\"><span class=\"o-idx\">4</span>맛없어요<span class=\"o-gl\">❌ 맛이 없단 뜻 아님</span></button></div><div class=\"p-feedback\" id=\"fb-u6q2\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">The audio says \"케이크는 정말 <b class=\"hl\">달아요</b>\" — 달아요 is the conjugated form of 달다 (\"sweet\"), so the cake is <b class=\"hl\">달아요</b>. That is the answer.</div><div style=\"margin-bottom:5px;\">매워요 (from 맵다, spicy) and 짜요 (from 짜다, salty) describe different tastes, and 맛없어요 means \"tasteless\" — none matches the word the speaker used.</div></div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[6-3] Reading — How does it taste?</span></div><div class=\"p-dir\">Read and choose how the food tastes.</div><div class=\"p-passage\">🍜 이 음식은 빨개요. 먹으면 입이 매워서 물을 많이 마셔요.</div><div class=\"p-q\">이 음식은 어때요?</div><div class=\"opts\" data-q=\"u6q3\"><button class=\"opt\" onclick=\"checkQ('u6q3',2,this)\"><span class=\"o-idx\">1</span>짜요<span class=\"o-gl\">❌ 짠맛은 아님</span></button><button class=\"opt\" onclick=\"checkQ('u6q3',2,this)\"><span class=\"o-idx\">2</span>달아요<span class=\"o-gl\">❌ 단맛은 아님</span></button><button class=\"opt\" onclick=\"checkQ('u6q3',2,this)\"><span class=\"o-idx\">3</span>매워요<span class=\"o-gl\">✅ 빨갛고 매운맛 — 정답</span></button><button class=\"opt\" onclick=\"checkQ('u6q3',2,this)\"><span class=\"o-idx\">4</span>맛없어요<span class=\"o-gl\">❌ 맛있다는 말이 아님</span></button></div><div class=\"p-feedback\" id=\"fb-u6q3\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">The food is <b class=\"hl\">빨개요</b> (red), and eating it makes the mouth burn so the person drinks water — so it is <b class=\"hl\">매워요</b> (from 맵다, spicy).</div><div style=\"margin-bottom:5px;\">짜요 (salty) and 달아요 (sweet) are different tastes, and 맛없어요 means \"tasteless,\" which has nothing to do with being spicy.</div></div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[6-4] Listening — 못 먹어요</span></div><div class=\"p-dir\">🔊 Listen and choose the meaning.</div><button class=\"p-audio\" onclick=\"tts('저는 매운 음식을 못 먹어요.')\">🔊 Listen</button><div class=\"p-q\">“못 먹어요”의 뜻은 뭐예요?</div><div class=\"opts\" data-q=\"u6q4\"><button class=\"opt\" onclick=\"checkQ('u6q4',1,this)\"><span class=\"o-idx\">1</span>먹고 싶지 않아요<span class=\"o-gl\">❌ 그건 안 먹어요</span></button><button class=\"opt\" onclick=\"checkQ('u6q4',1,this)\"><span class=\"o-idx\">2</span>먹을 수 없어요<span class=\"o-gl\">✅ 능력·상황 — 정답</span></button><button class=\"opt\" onclick=\"checkQ('u6q4',1,this)\"><span class=\"o-idx\">3</span>매일 먹어요<span class=\"o-gl\">❌ 매일 먹는다는 뜻 아님</span></button><button class=\"opt\" onclick=\"checkQ('u6q4',1,this)\"><span class=\"o-idx\">4</span>조금만 먹어요<span class=\"o-gl\">❌ 양에 대한 말 아님</span></button></div><div class=\"p-feedback\" id=\"fb-u6q4\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\"><b class=\"hl\">못</b> + verb = \"<b class=\"hl\">can't do it</b>\" (no ability / the situation won't allow it). So 못 먹어요 = 먹을 수 없어요 = \"<b class=\"hl\">I can't eat it</b>.\" That is the answer.</div><div style=\"margin-bottom:5px;\">\"먹고 싶지 않아요\" (I don't want to eat) would be <b class=\"hl\">안 먹어요</b> — that's my own choice. Don't mix 안 (choice) with 못 (ability)!</div></div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[6-5] Reading — 안 매워요</span></div><div class=\"p-dir\">Read and choose what the gimbap is like.</div><div class=\"p-passage\">떡볶이는 매워요. 그런데 김밥은 안 매워요.</div><div class=\"p-q\">김밥은 어때요?</div><div class=\"opts\" data-q=\"u6q5\"><button class=\"opt\" onclick=\"checkQ('u6q5',3,this)\"><span class=\"o-idx\">1</span>매워요<span class=\"o-gl\">❌ 김밥은 맵지 않아요</span></button><button class=\"opt\" onclick=\"checkQ('u6q5',3,this)\"><span class=\"o-idx\">2</span>달아요<span class=\"o-gl\">❌ 단맛은 아님</span></button><button class=\"opt\" onclick=\"checkQ('u6q5',3,this)\"><span class=\"o-idx\">3</span>짜요<span class=\"o-gl\">❌ 짠맛은 아님</span></button><button class=\"opt\" onclick=\"checkQ('u6q5',3,this)\"><span class=\"o-idx\">4</span>안 매워요<span class=\"o-gl\">✅ 부정 — 정답</span></button></div><div class=\"p-feedback\" id=\"fb-u6q5\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\"><b class=\"hl\">안</b> + adjective = negation (\"not\"). \"김밥은 <b class=\"hl\">안 매워요</b>\" = the gimbap is <b class=\"hl\">not spicy</b>. That is the correct choice.</div><div style=\"margin-bottom:5px;\">\"그런데\" (but) shows contrast — 떡볶이 is spicy, but the gimbap is not. 달아요 (sweet) and 짜요 (salty) are not mentioned about the gimbap.</div></div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[6-6] Listening — What does she eat?</span></div><div class=\"p-dir\">🔊 Listen and choose what the person eats.</div><button class=\"p-audio\" onclick=\"tts('저는 매운 음식을 못 먹어요. 그래서 김밥이나 만두를 먹어요.')\">🔊 Listen</button><div class=\"p-q\">이 사람은 뭐를 먹어요?</div><div class=\"opts\" data-q=\"u6q6\"><button class=\"opt\" onclick=\"checkQ('u6q6',1,this)\"><span class=\"o-idx\">1</span>매운 음식<span class=\"o-gl\">❌ 못 먹는다고 했어요</span></button><button class=\"opt\" onclick=\"checkQ('u6q6',1,this)\"><span class=\"o-idx\">2</span>김밥이나 만두<span class=\"o-gl\">✅ 못 먹는 음식 제외 — 정답</span></button><button class=\"opt\" onclick=\"checkQ('u6q6',1,this)\"><span class=\"o-idx\">3</span>떡볶이<span class=\"o-gl\">❌ 매운 음식이라 못 먹어요</span></button><button class=\"opt\" onclick=\"checkQ('u6q6',1,this)\"><span class=\"o-idx\">4</span>케이크<span class=\"o-gl\">❌ 들리지 않았어요</span></button></div><div class=\"p-feedback\" id=\"fb-u6q6\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">The person <b class=\"hl\">못 먹어요</b> (can't eat) spicy food, and <b class=\"hl\">그래서</b> (so) eats <b class=\"hl\">김밥이나 만두</b> (gimbap or mandu) instead. That is the answer.</div><div style=\"margin-bottom:5px;\">떡볶이 is a spicy food, so this person can't eat it — that's exactly why they choose 김밥이나 만두, not the spicy food.</div></div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[6-7] Reading — 못 해요</span></div><div class=\"p-dir\">Read the short talk and choose the meaning.</div><div class=\"p-passage\">A: 노래를 잘해요?  B: 아니요, 노래를 못 해요.</div><div class=\"p-q\">여기서 “못 해요”의 뜻은 뭐예요?</div><div class=\"opts\" data-q=\"u6q7\"><button class=\"opt\" onclick=\"checkQ('u6q7',3,this)\"><span class=\"o-idx\">1</span>노래하고 싶지 않아요<span class=\"o-gl\">❌ 그건 안 해요</span></button><button class=\"opt\" onclick=\"checkQ('u6q7',3,this)\"><span class=\"o-idx\">2</span>매일 노래해요<span class=\"o-gl\">❌ 자주 한다는 뜻 아님</span></button><button class=\"opt\" onclick=\"checkQ('u6q7',3,this)\"><span class=\"o-idx\">3</span>노래를 잘해요<span class=\"o-gl\">❌ 부정인데 잘한다고?</span></button><button class=\"opt\" onclick=\"checkQ('u6q7',3,this)\"><span class=\"o-idx\">4</span>노래할 수 없어요<span class=\"o-gl\">✅ 능력 없음 — 정답</span></button></div><div class=\"p-feedback\" id=\"fb-u6q7\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\"><b class=\"hl\">못</b> + 해요 = \"<b class=\"hl\">can't do it</b>.\" Since the person answers \"아니요\" (no) to \"노래를 잘해요?\", 노래를 못 해요 means they <b class=\"hl\">노래할 수 없어요</b> (can't sing). That is the answer.</div><div style=\"margin-bottom:5px;\">\"하고 싶지 않아요\" (I don't want to) is <b class=\"hl\">안 해요</b> — that's about will. Remember 못 = inability. And \"노래를 잘해요\" (sing well) is a positive statement, so it can't be the meaning of the negative.</div></div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[6-8] Listening — Which sentence?</span></div><div class=\"p-dir\">🔊 Listen and choose the sentence you hear.</div><button class=\"p-audio\" onclick=\"tts('저는 매운 음식을 안 먹어요.')\">🔊 Listen</button><div class=\"p-q\">들은 문장을 고르세요.</div><div class=\"opts\" data-q=\"u6q8\"><button class=\"opt\" onclick=\"checkQ('u6q8',0,this)\"><span class=\"o-idx\">1</span>저는 매운 음식을 안 먹어요.<span class=\"o-gl\">✅ 안 + 동사 — 정답</span></button><button class=\"opt\" onclick=\"checkQ('u6q8',0,this)\"><span class=\"o-idx\">2</span>저는 매운 음식을 못 먹어요.<span class=\"o-gl\">❌ 못이 들려요?</span></button><button class=\"opt\" onclick=\"checkQ('u6q8',0,this)\"><span class=\"o-idx\">3</span>저는 매운 음식을 먹어요.<span class=\"o-gl\">❌ 부정이 없어요</span></button><button class=\"opt\" onclick=\"checkQ('u6q8',0,this)\"><span class=\"o-idx\">4</span>저는 단 음식을 안 먹어요.<span class=\"o-gl\">❌ 매운 vs 단 구별</span></button></div><div class=\"p-feedback\" id=\"fb-u6q8\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">The sentence you heard is \"매운 음식을 <b class=\"hl\">안</b> 먹어요\" (I don't eat spicy food). <b class=\"hl\">안</b> + verb expresses your own choice, so that is the answer.</div><div style=\"margin-bottom:5px;\">Don't confuse it with 못 (can't — ability). Also, option 4 says \"단 음식\" (sweet food) — learn to tell 매운 (spicy) apart from 단 (sweet), because that sentence was not what was said.</div></div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[6-9] Reading — Who likes gimbap?</span></div><div class=\"p-dir\">Read and choose who likes gimbap.</div><div class=\"p-passage\">🍱 로이는 떡볶이를 좋아해요. 떡볶이는 매워요. 채아는 김밥을 좋아해요. 김밥은 안 매워요.</div><div class=\"p-q\">안 매운 음식을 좋아하는 사람은 누구예요?</div><div class=\"opts\" data-q=\"u6q9\"><button class=\"opt\" onclick=\"checkQ('u6q9',3,this)\"><span class=\"o-idx\">1</span>로이<span class=\"o-gl\">❌ 떡볶이(매운 음식)를 좋아해요</span></button><button class=\"opt\" onclick=\"checkQ('u6q9',3,this)\"><span class=\"o-idx\">2</span>다희<span class=\"o-gl\">❌ 이 글에 없어요</span></button><button class=\"opt\" onclick=\"checkQ('u6q9',3,this)\"><span class=\"o-idx\">3</span>아란<span class=\"o-gl\">❌ 이 글에 없어요</span></button><button class=\"opt\" onclick=\"checkQ('u6q9',3,this)\"><span class=\"o-idx\">4</span>채아<span class=\"o-gl\">✅ 김밥을 좋아해요 — 정답</span></button></div><div class=\"p-feedback\" id=\"fb-u6q9\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">The gimbap is <b class=\"hl\">안 매워요</b> (not spicy), and the person who likes gimbap is <b class=\"hl\">채아</b>. So 채아 is the correct answer.</div><div style=\"margin-bottom:5px;\">로이 likes the spicy <b class=\"hl\">떡볶이</b>, so he is not the answer. 다희 and 아란 are not mentioned anywhere in the text.</div></div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\"><div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[6-10] Listening — Why water?</span></div><div class=\"p-dir\">🔊 Listen and choose the reason.</div><button class=\"p-audio\" onclick=\"tts('점심에 만두를 먹었어요. 그런데 만두가 짜요. 그래서 물을 많이 마셨어요.')\">🔊 Listen</button><div class=\"p-q\">왜 물을 많이 마셨어요?</div><div class=\"opts\" data-q=\"u6q10\"><button class=\"opt\" onclick=\"checkQ('u6q10',2,this)\"><span class=\"o-idx\">1</span>만두가 달아요<span class=\"o-gl\">❌ 단맛이 아니라 짠맛</span></button><button class=\"opt\" onclick=\"checkQ('u6q10',2,this)\"><span class=\"o-idx\">2</span>배가 고파요<span class=\"o-gl\">❌ 점심에 이미 먹었어요</span></button><button class=\"opt\" onclick=\"checkQ('u6q10',2,this)\"><span class=\"o-idx\">3</span>만두가 짜요<span class=\"o-gl\">✅ 짠맛 때문에 — 정답</span></button><button class=\"opt\" onclick=\"checkQ('u6q10',2,this)\"><span class=\"o-idx\">4</span>만두가 매워요<span class=\"o-gl\">❌ 매운맛은 아님</span></button></div><div class=\"p-feedback\" id=\"fb-u6q10\"></div><div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">The speaker says \"만두가 <b class=\"hl\">짜요</b>. <b class=\"hl\">그래서</b> 물을 많이 마셨어요\" — the mandu is salty, so they drank a lot of water. 짜요 = salty, so that is the answer.</div><div style=\"margin-bottom:5px;\">The mandu is salty, not sweet, so 달아요 (sweet) is wrong; 매워요 (spicy) is not what the mandu tastes like. These taste words are easy to mix up, so read carefully.</div></div></div></div></div>"}, {"cls": "culture", "html": "<div class=\"culture\">\n    <span class=\"c-label\">🎤 K-POP TIP</span>\n    <h3>Idol V-Live Mukbang</h3>\n    <p>Idols do <b>mukbang (eating shows)</b> on V LIVE! Fans comment \"맛있게 먹어요!\" (Enjoy your meal!).</p>\n    <div class=\"c-tip\">🍗 Chicken + cola = the chimaek culture! To say what you want: \"치킨 먹고 싶어요\" — you'll learn -고 싶어요 in 1B.</div>\n  </div>\n\n<!-- ============================================================\n     UNIT 7 — LOCATION\n     ============================================================ -->"}]}, {"id": 7, "sections": [{"cls": "unit-flag", "html": "<div class=\"unit-flag\">UNIT 7 · LOCATION</div>\n  "}, {"cls": "sec-title", "html": "<div class=\"sec-title\"><div class=\"no\">7</div><div><h2>I'm in the Practice Room</h2><div class=\"en\">연습실에 있어요 — Location · 에/에서</div></div></div>\n  "}, {"cls": "story", "html": "<div class=\"story\">\n    <img class=\"story-art\" src=\"assets/glowsis/chaea.png\" alt=\"채아\">\n    <div class=\"story-body\">\n      <span class=\"story-tag\">💿 GLOWSIS STORY · 7/8</span>\n      <h3>채아의 위치 알리기 — \"연습실에 있어요!\"</h3>\n      <p>글로시스 멤버들은 각자 다른 장소에 있어요! <b>채아</b>는 위치를 말하는 법을 배워요 — \"어디에 있어요?\" 장소를 말할수록 멤버들이 모여요. 📍</p>\n      <span class=\"story-piece\">📍 GLOW POINT 7/8 획득 — Locations!</span>\n    </div>\n  </div>\n"}, {"cls": "goals", "html": "<div class=\"goals\">\n    <div class=\"goal\"><span class=\"g-ico\">📍</span> Where are you?</div>\n    <div class=\"goal\"><span class=\"g-ico\">🔤</span> 에 / 에서 particles particles</div>\n    <div class=\"goal\"><span class=\"g-ico\">🏠</span> Place vocabulary</div>\n  </div>\n\n  "}, {"cls": "dialog", "html": "<div class=\"dialog\">\n    <div class=\"d-head\">\n      <span class=\"d-title\">💬 Dialogue 7 — Where Are the Members?</span>\n      <span class=\"d-scene\">📱 Group chat</span>\n    </div>\n    <div class=\"d-line\"><img src=\"assets/glowsis/aran.png\" alt=\"아란\">\n      <div class=\"d-bubble\"><div class=\"who\">아란</div><div class=\"ko\">지금 Where are you? 연습이에요!</div><div class=\"gl\">Where are you now? It's practice time!</div></div>\n    </div>\n    <div class=\"d-line me\"><img src=\"assets/glowsis/dahee.png\" alt=\"다희\">\n      <div class=\"d-bubble\"><div class=\"who\">다희</div><div class=\"ko\">저는 연습실에 있어요!</div><div class=\"gl\">I'm in the practice room!</div></div>\n    </div>\n    <div class=\"d-line\"><img src=\"assets/glowsis/roy.png\" alt=\"로이\">\n      <div class=\"d-bubble\"><div class=\"who\">로이</div><div class=\"ko\">저는 집에 있어요. 조금 있어요!</div><div class=\"gl\">I'm at home. Wait a bit!</div></div>\n    </div>\n    <div class=\"d-line me\"><img src=\"assets/glowsis/dahee.png\" alt=\"다희\">\n      <div class=\"d-bubble\"><div class=\"who\">다희</div><div class=\"ko\">저는 카페에서 커피를 마셔요. 곧 갈게요!</div><div class=\"gl\">I'm drinking coffee at the cafe. I'll come soon!</div></div>\n    </div>\n  </div>\n\n  "}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">GRAMMAR 1</span>\n    <div class=\"g-point\">에 — Location & Time</div>\n    <div class=\"g-rule\">N에 = \"at/in ~ (있다/없다)\" — the place where something exists, and also time.</div>\n    <div class=\"g-ex\">\n      <div class=\"ex\"><span class=\"ko\">연습실<b>에</b> 있어요.</span><span class=\"gl\">I'm in the practice room.</span></div>\n      <div class=\"ex\"><span class=\"ko\">집<b>에</b> 있어요.</span><span class=\"gl\">I'm at home.</span></div>\n      <div class=\"ex\"><span class=\"ko\">5월 20일<b>에</b> 데뷔해요.</span><span class=\"gl\">We debut on May 20th. (time)</span></div>\n    </div>\n  </div>\n\n  "}, {"cls": "teach", "html": "<div class=\"teach\">\n  <span class=\"t-label\">🧑🏫 Teacher's Deep-Dive · 에 vs 에서 — location &amp; action</span>\n  <div class=\"t-q\"><span class=\"t-ko\">연습실에 있어요</span> <span class=\"t-en\">vs <span class=\"t-ko\">연습실에서 춤춰요</span> — both are about the practice room, so what's different?</span></div>\n\n  <div class=\"t-row t-head\">\n    <div class=\"t-why\">Why do we pick different ones? The two particles do different jobs!</div>\n    <div class=\"t-deep\">\n      <b>에</b> marks <b>existence · location · time</b>, and <b>에서</b> marks <b>the place where an action happens</b>.<br>\n      After 있어요/없어요 (있다, to exist) use <b>에</b>; after action verbs (춤추다 · 마시다 · 공부하다) use <b>에서</b>.\n    </div>\n  </div>\n\n  <div class=\"t-grid\">\n    <div class=\"t-cell t-qcell\">\n      <div class=\"t-word\">에</div>\n      <div class=\"t-role\">at / in <span class=\"t-sub\">(location · existence · time)</span></div>\n      <div class=\"t-note\">연습실<b>에</b> 있어요<br>집<b>에</b> 있어요<br>5월 20일<b>에</b> 데뷔해요</div>\n    </div>\n    <div class=\"t-op\">vs</div>\n    <div class=\"t-cell t-eqcell\">\n      <div class=\"t-word\">에서</div>\n      <div class=\"t-role\">at / in <span class=\"t-sub\">(place of an action)</span></div>\n      <div class=\"t-note\">연습실<b>에서</b> 춤춰요<br>카페<b>에서</b> 커피를 마셔요<br>학교<b>에서</b> 공부해요</div>\n    </div>\n  </div>\n\n  <div class=\"t-insight\">\n    <b class=\"t-i-ko\">\"연습실에 있어요\"</b> = just the <b>state</b> of being there. &nbsp; <b class=\"t-i-ko\">\"연습실에서 춤춰요\"</b> = an <b>action</b> happening in that place follows.\n    If the verb is <b>있어요</b> → <b>에</b>; if it's an <b>action verb</b> → <b>에서</b>!\n  </div>\n\n  <div class=\"t-compare\">\n    <div class=\"t-c-a\"><b>Existence · 있어요</b><br><span class=\"t-ko\">연습실에 있어요.</span><br><span class=\"t-en\">있어요/없어요 → 에</span></div>\n    <div class=\"t-c-b\"><b>Action · action verb</b><br><span class=\"t-ko\">연습실에서 춤춰요.</span><br><span class=\"t-en\">춤추다/마시다/공부하다 → 에서</span></div>\n  </div>\n\n  <div class=\"t-tip\">\n    💡 <b>Memory tip:</b> <b>에</b> is a place where you \"있다\" (stay still); <b>에서</b> is a busy place where something is being done!\n    If a Glowsis member is <b>dancing</b> (춤춰요) in the practice room, use <b>에서</b>; if they're <b>resting</b> (있어요), use <b>에</b>.\n  </div>\n</div>"}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">GRAMMAR 2</span>\n    <div class=\"g-point\">에서 — Place of Action</div>\n    <div class=\"g-rule\">N에서 = \"at ~ (do an action)\" — the place where an action happens.</div>\n    <div class=\"g-ex\">\n      <div class=\"ex\"><span class=\"ko\">카페<b>에서</b> 커피를 마셔요.</span><span class=\"gl\">I drink coffee at the cafe.</span></div>\n      <div class=\"ex\"><span class=\"ko\">연습실에서 춤을 춰요.</span><span class=\"gl\">We dance in the practice room.</span></div>\n      <div class=\"ex\"><span class=\"ko\">학교에서 공부해요.</span><span class=\"gl\">I study at school.</span></div>\n    </div>\n  </div>\n\n    "}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">GRAMMAR 3</span>\n    <div class=\"g-point\">위 / 아래 / 옆 / 앞 / 뒤 — position words</div>\n    <div class=\"g-rule\">Say where things are: <b>N 위에</b> (above), <b>N 아래에</b> (below), <b>N 옆에</b> (next to), <b>N 앞에</b> (in front), <b>N 뒤에</b> (behind).</div>\n    <div class=\"g-ex\">\n      <div class=\"ex\"><span class=\"ko\">책상 <b>위에</b> 있어요.</span><span class=\"gl\">It's on top of the desk.</span></div>\n      <div class=\"ex\"><span class=\"ko\">연습실 <b>옆에</b> 카페가 있어요.</span><span class=\"gl\">There's a cafe next to the practice room.</span></div>\n      <div class=\"ex\"><span class=\"ko\">학교 <b>앞에</b> 가게가 있어요.</span><span class=\"gl\">There's a store in front of the school.</span></div>\n    </div>\n  </div>\n\n"}, {"cls": "vocab-grid", "html": "<div class=\"vocab-lab\"><div class=\"vl-toolbar\"><span class=\"vl-hint\">카테고리를 눌러 그림과 함께 공부하세요</span><button class=\"vl-expand\" onclick=\"glowVocabAll()\">모두 펼치기</button></div><div class=\"vl-cat open\" data-tone=\"pink\"><button class=\"vl-cat-head\" onclick=\"glowVocab(this)\"><span class=\"vl-cat-ico\">🩰</span><span class=\"vl-cat-name\">연습 & 공연<small>Practice & shows · 아이돌 일상</small></span><span class=\"vl-cat-count\">3</span><span class=\"vl-cat-arr\">▾</span></button><div class=\"vl-cat-body\"><div class=\"vw-grid\"><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u7_practiceroom.webp\" alt=\"연습실\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('연습실')\">🔊</button><div class=\"vw-ko\">연습실</div><div class=\"vw-rom\">yeonseupsil</div><div class=\"vw-en\">practice room</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u7_musicshow.webp\" alt=\"음악방송\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('음악방송')\">🔊</button><div class=\"vw-ko\">음악방송</div><div class=\"vw-rom\">eumakbangsong</div><div class=\"vw-en\">music show</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u7_concert.webp\" alt=\"콘서트장\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('콘서트장')\">🔊</button><div class=\"vw-ko\">콘서트장</div><div class=\"vw-rom\">konseoteujang</div><div class=\"vw-en\">concert hall</div></div></div></div><div class=\"vs-box\"><div class=\"vs-head\">💬 이 단어로 자주 쓰는 말</div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('연습실에서 춤을 춰요.')\">🔊</button><div><span class=\"vs-ko\">연습실에서 춤을 춰요.</span> <span class=\"vs-en\">We dance in the practice room.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('저는 연습실에 있어요.')\">🔊</button><div><span class=\"vs-ko\">저는 연습실에 있어요.</span> <span class=\"vs-en\">I am in the practice room.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('음악방송에서 노래를 해요.')\">🔊</button><div><span class=\"vs-ko\">음악방송에서 노래를 해요.</span> <span class=\"vs-en\">We sing on the music show.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('콘서트장에서 팬들을 만나요.')\">🔊</button><div><span class=\"vs-ko\">콘서트장에서 팬들을 만나요.</span> <span class=\"vs-en\">We meet fans at the concert hall.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('콘서트장에 있어요.')\">🔊</button><div><span class=\"vs-ko\">콘서트장에 있어요.</span> <span class=\"vs-en\">I am at the concert hall.</span></div></div></div><div class=\"vl-link\">🎤 <b>아이돌의 하루:</b> 연습실<u>에서</u> 연습하고, 음악방송<u>에서</u> 무대하고, 콘서트장<u>에서</u> 팬들을 만나요. <b>에</b>=있어요(존재), <b>에서</b>=행동!</div></div></div><div class=\"vl-cat\" data-tone=\"mint\"><button class=\"vl-cat-head\" onclick=\"glowVocab(this)\"><span class=\"vl-cat-ico\">🏠</span><span class=\"vl-cat-name\">일상 장소<small>Places · 매일 가는 곳</small></span><span class=\"vl-cat-count\">5</span><span class=\"vl-cat-arr\">▾</span></button><div class=\"vl-cat-body\"><div class=\"vw-grid\"><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u7_home.webp\" alt=\"집\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('집')\">🔊</button><div class=\"vw-ko\">집</div><div class=\"vw-rom\">jip</div><div class=\"vw-en\">home</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u7_cafe.webp\" alt=\"카페\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('카페')\">🔊</button><div class=\"vw-ko\">카페</div><div class=\"vw-rom\">kape</div><div class=\"vw-en\">cafe</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u7_school.webp\" alt=\"학교\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('학교')\">🔊</button><div class=\"vw-ko\">학교</div><div class=\"vw-rom\">hakgyo</div><div class=\"vw-en\">school</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u7_shop.webp\" alt=\"가게\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('가게')\">🔊</button><div class=\"vw-ko\">가게</div><div class=\"vw-rom\">gage</div><div class=\"vw-en\">store, shop</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u7_hospital.webp\" alt=\"병원\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('병원')\">🔊</button><div class=\"vw-ko\">병원</div><div class=\"vw-rom\">byeongwon</div><div class=\"vw-en\">hospital</div></div></div></div><div class=\"vs-box\"><div class=\"vs-head\">💬 이 단어로 자주 쓰는 말</div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('집에 있어요.')\">🔊</button><div><span class=\"vs-ko\">집에 있어요.</span> <span class=\"vs-en\">I am at home.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('카페에서 커피를 마셔요.')\">🔊</button><div><span class=\"vs-ko\">카페에서 커피를 마셔요.</span> <span class=\"vs-en\">I drink coffee at the cafe.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('학교에서 공부해요.')\">🔊</button><div><span class=\"vs-ko\">학교에서 공부해요.</span> <span class=\"vs-en\">I study at school.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('가게에서 빵을 사요.')\">🔊</button><div><span class=\"vs-ko\">가게에서 빵을 사요.</span> <span class=\"vs-en\">I buy bread at the store.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('병원에 있어요.')\">🔊</button><div><span class=\"vs-ko\">병원에 있어요.</span> <span class=\"vs-en\">I am at the hospital.</span></div></div></div><div class=\"vl-link\">🗺️ <b>장소마다 행동:</b> 카페<u>에서</u> 커피를 마셔요 · 학교<u>에서</u> 공부해요 · 가게<u>에서</u> 사요. “~에 있어요”=존재, “~에서 [동사]”=행동!</div></div></div><div class=\"vl-cat\" data-tone=\"sky\"><button class=\"vl-cat-head\" onclick=\"glowVocab(this)\"><span class=\"vl-cat-ico\">🚌</span><span class=\"vl-cat-name\">교통<small>Transport · 이동 수단</small></span><span class=\"vl-cat-count\">2</span><span class=\"vl-cat-arr\">▾</span></button><div class=\"vl-cat-body\"><div class=\"vw-grid\"><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u7_subway.webp\" alt=\"지하철\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('지하철')\">🔊</button><div class=\"vw-ko\">지하철</div><div class=\"vw-rom\">jihacheol</div><div class=\"vw-en\">subway</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u7_bus.webp\" alt=\"버스\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('버스')\">🔊</button><div class=\"vw-ko\">버스</div><div class=\"vw-rom\">beoseu</div><div class=\"vw-en\">bus</div></div></div></div><div class=\"vs-box\"><div class=\"vs-head\">💬 이 단어로 자주 쓰는 말</div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('지하철로 음악방송에 가요.')\">🔊</button><div><span class=\"vs-ko\">지하철로 음악방송에 가요.</span> <span class=\"vs-en\">We go to the music show by subway.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('버스로 학교에 가요.')\">🔊</button><div><span class=\"vs-ko\">버스로 학교에 가요.</span> <span class=\"vs-en\">I go to school by bus.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('지하철을 타요.')\">🔊</button><div><span class=\"vs-ko\">지하철을 타요.</span> <span class=\"vs-en\">I take the subway.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('버스를 타요.')\">🔊</button><div><span class=\"vs-ko\">버스를 타요.</span> <span class=\"vs-en\">I take the bus.</span></div></div></div><div class=\"vl-link\">🚇 <b>이동:</b> “(타고) 가다”에 <b>~로</b>(by). 지하철<u>로</u> 가요 · 버스<u>로</u> 가요. 장소가 아니고 <b>수단</b>이에요!</div></div></div><div class=\"vl-cat\" data-tone=\"lav\"><button class=\"vl-cat-head\" onclick=\"glowVocab(this)\"><span class=\"vl-cat-ico\">📍</span><span class=\"vl-cat-name\">위치<small>Position · 어디에 있어요?</small></span><span class=\"vl-cat-count\">4</span><span class=\"vl-cat-arr\">▾</span></button><div class=\"vl-cat-body\"><div class=\"vw-grid\"><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u7_where.webp\" alt=\"어디\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('어디')\">🔊</button><div class=\"vw-ko\">어디</div><div class=\"vw-rom\">eodi</div><div class=\"vw-en\">where</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u7_above.webp\" alt=\"위\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('위')\">🔊</button><div class=\"vw-ko\">위</div><div class=\"vw-rom\">wi</div><div class=\"vw-en\">above, top</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u7_below.webp\" alt=\"아래\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('아래')\">🔊</button><div class=\"vw-ko\">아래</div><div class=\"vw-rom\">arae</div><div class=\"vw-en\">below, bottom</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u7_side.webp\" alt=\"옆\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('옆')\">🔊</button><div class=\"vw-ko\">옆</div><div class=\"vw-rom\">yeop</div><div class=\"vw-en\">next to, side</div></div></div></div><div class=\"vs-box\"><div class=\"vs-head\">💬 이 단어로 자주 쓰는 말</div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('어디에 있어요?')\">🔊</button><div><span class=\"vs-ko\">어디에 있어요?</span> <span class=\"vs-en\">Where are you?</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('책상 위에 있어요.')\">🔊</button><div><span class=\"vs-ko\">책상 위에 있어요.</span> <span class=\"vs-en\">It is on top of the desk.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('책상 아래에 있어요.')\">🔊</button><div><span class=\"vs-ko\">책상 아래에 있어요.</span> <span class=\"vs-en\">It is under the desk.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('가게 옆에 카페가 있어요.')\">🔊</button><div><span class=\"vs-ko\">가게 옆에 카페가 있어요.</span> <span class=\"vs-en\">There is a cafe next to the store.</span></div></div></div><div class=\"vl-link\">📍 <b>반대 짝:</b> 위 ↔ 아래, 그리고 <b>옆</b>까지. 위치는 항상 <b>~에</b>와 함께: 책상 <b>위에</b> 있어요!</div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n<div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[7-1] Reading — 에 vs 에서 빈칸</span></div>\n<div class=\"p-dir\">Choose the correct particle.</div>\n<div class=\"p-q\">아란 씨는 연습실(    ) 있어요. <span class=\"gl\">Aran is in the practice room.</span></div>\n<div class=\"opts\" data-q=\"u7q1\">\n      <button class=\"opt\" onclick=\"checkQ('u7q1',1,this)\"><span class=\"o-idx\">1</span> 에서<span class=\"o-gl\">❌ ❌ 에서 = action place</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q1',1,this)\"><span class=\"o-idx\">2</span> 에<span class=\"o-gl\">✅ ✅ 에 = existence (있어요)</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q1',1,this)\"><span class=\"o-idx\">3</span> 을<span class=\"o-gl\">❌ ❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q1',1,this)\"><span class=\"o-idx\">4</span> 가<span class=\"o-gl\">❌ ❌</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u7q1\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">있어요 (있다) is a state of existence, so the place takes <span class=\"pt-ko\">에</span> — 연습실<b class=\"hl\">에</b> 있어요. That is the answer.</div><div style=\"margin-bottom:5px;\"><b class=\"hl\">에서</b> = the place where an action happens; 을 and 가 are object and subject markers, not location. Rule: with 있어요/없어요 → <b class=\"hl\">에</b>!</div></div></div></div>\n</div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n<div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[7-2] Listening — 행동 장소</span></div>\n<div class=\"p-dir\">🔊 Listen and choose what you hear.</div>\n<button class=\"p-audio\" onclick=\"tts('저는 카페에서 커피를 마셔요.')\">🔊 Listen</button>\n<div class=\"opts\" data-q=\"u7q2\">\n      <button class=\"opt\" onclick=\"checkQ('u7q2',1,this)\"><span class=\"o-idx\">1</span>집에서 커피를 마셔요.<span class=\"o-gl\">❌ ❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q2',1,this)\"><span class=\"o-idx\">2</span>카페에서 커피를 마셔요.<span class=\"o-gl\">✅ ✅ 카페 = cafe</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q2',1,this)\"><span class=\"o-idx\">3</span>학교에서 커피를 마셔요.<span class=\"o-gl\">❌ ❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q2',1,this)\"><span class=\"o-idx\">4</span>병원에서 커피를 마셔요.<span class=\"o-gl\">❌ ❌</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u7q2\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">The audio says <span class=\"pt-ko\">카페에서 커피를 마셔요</span> — 마시다 (to drink) is an action, so the place takes <b class=\"hl\">에서</b>. The person is in a <b class=\"hl\">cafe</b> (카페).</div><div style=\"margin-bottom:5px;\">집 (home), 학교 (school), and 병원 (hospital) have a different place word, which changes the whole meaning. In listening, grab the <b class=\"hl\">place word</b> (카페 · 집 · 학교) first!</div></div></div></div>\n</div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n<div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[7-3] Reading — 위 (on top)</span></div>\n<div class=\"p-dir\">Look at the picture and choose the correct sentence.</div>\n<div class=\"p-passage\">[그림: 책상 위에 책]<br><span class=\"gl\">[Picture: a book on top of the desk]</span></div>\n<div class=\"opts\" data-q=\"u7q3\">\n      <button class=\"opt\" onclick=\"checkQ('u7q3',0,this)\"><span class=\"o-idx\">1</span>책이 책상 위에 있어요.<span class=\"o-gl\">✅ ✅ The book is ON the desk.</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q3',0,this)\"><span class=\"o-idx\">2</span>책이 책상 아래에 있어요.<span class=\"o-gl\">❌ ❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q3',0,this)\"><span class=\"o-idx\">3</span>책이 책상 옆에 있어요.<span class=\"o-gl\">❌ ❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q3',0,this)\"><span class=\"o-idx\">4</span>책이 책상 뒤에 있어요.<span class=\"o-gl\">❌ ❌</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u7q3\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">In the picture the book is on <b class=\"hl\">위</b> of the desk, so the right sentence is \"책이 책상 <b class=\"hl\">위에</b> 있어요\" = The book is ON the desk.</div><div style=\"margin-bottom:5px;\"><b class=\"hl\">아래</b> = below, <b class=\"hl\">옆</b> = next to, and <b class=\"hl\">뒤</b> = behind — none matches \"on top.\" The picture tells you the position!</div></div></div></div>\n</div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n<div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[7-4] Listening — 위치 (아래)</span></div>\n<div class=\"p-dir\">🔊 Listen and choose where the book is.</div>\n<button class=\"p-audio\" onclick=\"tts('책이 책상 아래에 있어요.')\">🔊 Listen (책이 책상 아래에 있어요)</button>\n<div class=\"opts\" data-q=\"u7q4\">\n      <button class=\"opt\" onclick=\"checkQ('u7q4',1,this)\"><span class=\"o-idx\">1</span>It is on top of the desk.<span class=\"o-gl\">❌ ❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q4',1,this)\"><span class=\"o-idx\">2</span>It is under the desk.<span class=\"o-gl\">✅ ✅ 아래 = under</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q4',1,this)\"><span class=\"o-idx\">3</span>It is next to the desk.<span class=\"o-gl\">❌ ❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q4',1,this)\"><span class=\"o-idx\">4</span>It is in front of the desk.<span class=\"o-gl\">❌ ❌</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u7q4\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">The audio says 책이 책상 <span class=\"pt-ko\">아래에</span> 있어요, and 아래 = bottom / under. So it is <b class=\"hl\">under the desk</b> — that is the answer.</div><div style=\"margin-bottom:5px;\"><b class=\"hl\">위</b> = on top (the opposite of 아래), <b class=\"hl\">옆</b> = next to, <b class=\"hl\">앞</b> = in front. Learn 위 ↔ 아래 as an <b class=\"hl\">opposite pair</b>!</div></div></div></div>\n</div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n<div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[7-5] Reading — 에서 (place of action)</span></div>\n<div class=\"p-dir\">Choose the correct particle.</div>\n<div class=\"p-q\">연습실(    ) 춤을 춰요. <span class=\"gl\">We dance in the practice room.</span></div>\n<div class=\"opts\" data-q=\"u7q5\">\n      <button class=\"opt\" onclick=\"checkQ('u7q5',1,this)\"><span class=\"o-idx\">1</span> 에<span class=\"o-gl\">❌ ❌ 에 = existence/time</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q5',1,this)\"><span class=\"o-idx\">2</span> 에서<span class=\"o-gl\">✅ ✅ 에서 = place of action</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q5',1,this)\"><span class=\"o-idx\">3</span> 이<span class=\"o-gl\">❌ ❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q5',1,this)\"><span class=\"o-idx\">4</span> 로<span class=\"o-gl\">❌ ❌</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u7q5\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">춤추다 is an action verb, so the place where you dance takes <span class=\"pt-ko\">에서</span> — 연습실<b class=\"hl\">에서</b> 춤을 춰요. That is the answer.</div><div style=\"margin-bottom:5px;\"><b class=\"hl\">에</b> follows 있어요 (existence); <b class=\"hl\">로</b> means \"by (means of)\" or a direction. Rule: after action verbs (춤추다 · 마시다 · 공부하다) use <b class=\"hl\">에서</b>!</div></div></div></div>\n</div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n<div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[7-6] Listening — 교통 & 장소</span></div>\n<div class=\"p-dir\">🔊 Listen and choose the correct sentence.</div>\n<button class=\"p-audio\" onclick=\"tts('지하철로 음악방송에 가요.')\">🔊 Listen (지하철로 음악방송에 가요)</button>\n<div class=\"opts\" data-q=\"u7q6\">\n      <button class=\"opt\" onclick=\"checkQ('u7q6',1,this)\"><span class=\"o-idx\">1</span>We go to the music show by bus.<span class=\"o-gl\">❌ ❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q6',1,this)\"><span class=\"o-idx\">2</span>We go to the music show by subway.<span class=\"o-gl\">✅ ✅ 지하철 = subway</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q6',1,this)\"><span class=\"o-idx\">3</span>We go to the concert hall by subway.<span class=\"o-gl\">❌ ❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q6',1,this)\"><span class=\"o-idx\">4</span>We stay at the music show.<span class=\"o-gl\">❌ ❌</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u7q6\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">지하철<b class=\"hl\">로</b> = by subway (means of transport), 음악방송<b class=\"hl\">에</b> = to the music show. So the meaning is \"We go to the music show by subway.\"</div><div style=\"margin-bottom:5px;\">버스 = bus (not heard), 콘서트장 = concert hall (not a music show), and \"stay\" is wrong because 가요 means \"go.\" For travel: <b class=\"hl\">~로</b> (by) + <b class=\"hl\">~에 가요</b> (go to)!</div></div></div></div>\n</div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n<div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[7-7] Reading — 장소 어휘 (병원)</span></div>\n<div class=\"p-dir\">Read the sentence and choose the meaning.</div>\n<div class=\"p-q\"><span class=\"pt-ko\">아파서 병원에 있어요.</span></div>\n<div class=\"opts\" data-q=\"u7q7\">\n      <button class=\"opt\" onclick=\"checkQ('u7q7',0,this)\"><span class=\"o-idx\">1</span>I am at the hospital because I am sick.<span class=\"o-gl\">✅ ✅ 병원 = hospital</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q7',0,this)\"><span class=\"o-idx\">2</span>I am at the shop because I am sick.<span class=\"o-gl\">❌ ❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q7',0,this)\"><span class=\"o-idx\">3</span>I am at home because I am sick.<span class=\"o-gl\">❌ ❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q7',0,this)\"><span class=\"o-idx\">4</span>I am at the cafe because I am sick.<span class=\"o-gl\">❌ ❌</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u7q7\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">아파서 병원<b class=\"hl\">에</b> 있어요 = \"I'm at the hospital because I'm sick.\" 병원 = <b class=\"hl\">hospital</b>, and being there is a state, so we use 에.</div><div style=\"margin-bottom:5px;\">가게 = shop, 집 = home, 카페 = cafe — but the place you go when you're sick (아파서) is the <b class=\"hl\">병원</b>. State (있어요) → 에.</div></div></div></div>\n</div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n<div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[7-8] Reading — 옆 (next to)</span></div>\n<div class=\"p-dir\">Read and choose the correct meaning.</div>\n<div class=\"p-q\"><span class=\"pt-ko\">학교 옆에 가게가 있어요.</span></div>\n<div class=\"opts\" data-q=\"u7q8\">\n      <button class=\"opt\" onclick=\"checkQ('u7q8',0,this)\"><span class=\"o-idx\">1</span>There is a store next to the school.<span class=\"o-gl\">✅ ✅ 옆 = next to</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q8',0,this)\"><span class=\"o-idx\">2</span>There is a store in front of the school.<span class=\"o-gl\">❌ ❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q8',0,this)\"><span class=\"o-idx\">3</span>There is a store behind the school.<span class=\"o-gl\">❌ ❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q8',0,this)\"><span class=\"o-idx\">4</span>There is a store under the school.<span class=\"o-gl\">❌ ❌</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u7q8\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">학교 <span class=\"pt-ko\">옆에</span> 가게가 있어요 = \"There's a store <b class=\"hl\">next to</b> the school.\" 옆 = next to, so that is the answer.</div><div style=\"margin-bottom:5px;\"><b class=\"hl\">앞</b> = in front, <b class=\"hl\">뒤</b> = behind, <b class=\"hl\">아래</b> = below. Pattern: \"~옆에 ~가 있어요\" = there is ~ next to ~. Position + 있어요 → <b class=\"hl\">에</b>!</div></div></div></div>\n</div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n<div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[7-9] Reading — 에 (time)</span></div>\n<div class=\"p-dir\">Choose the correct particle.</div>\n<div class=\"p-q\">글로시스는 5월 20일(    ) 데뷔해요. <span class=\"gl\">Glowsis debuts on May 20th.</span></div>\n<div class=\"opts\" data-q=\"u7q9\">\n      <button class=\"opt\" onclick=\"checkQ('u7q9',0,this)\"><span class=\"o-idx\">1</span> 에<span class=\"o-gl\">✅ ✅ 에 = time (on a date)</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q9',0,this)\"><span class=\"o-idx\">2</span> 에서<span class=\"o-gl\">❌ ❌ 에서 = action place</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q9',0,this)\"><span class=\"o-idx\">3</span> 을<span class=\"o-gl\">❌ ❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q9',0,this)\"><span class=\"o-idx\">4</span> 이<span class=\"o-gl\">❌ ❌</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u7q9\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">Dates and times also take <span class=\"pt-ko\">에</span> — 5월 20일<b class=\"hl\">에</b> (on May 20th). So 에 is the answer for the time blank.</div><div style=\"margin-bottom:5px;\"><b class=\"hl\">에서</b> is used only for the place of an action, and 을 marks the object. So <b class=\"hl\">에</b> covers both a place (with 있어요) and <b class=\"hl\">time</b> (when)!</div></div></div></div>\n</div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n<div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[7-10] Listening — 에 vs 에서 구별</span></div>\n<div class=\"p-dir\">🔊 Listen and choose the correct meaning.</div>\n<button class=\"p-audio\" onclick=\"tts('저는 집에서 밥을 먹어요.')\">🔊 Listen (저는 집에서 밥을 먹어요)</button>\n<div class=\"opts\" data-q=\"u7q10\">\n      <button class=\"opt\" onclick=\"checkQ('u7q10',1,this)\"><span class=\"o-idx\">1</span>I am at home.<span class=\"o-gl\">❌ ❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q10',1,this)\"><span class=\"o-idx\">2</span>I eat rice at home.<span class=\"o-gl\">✅ ✅ 밥을 먹다 = action → 에서</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q10',1,this)\"><span class=\"o-idx\">3</span>I am going home.<span class=\"o-gl\">❌ ❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u7q10',1,this)\"><span class=\"o-idx\">4</span>I rest at home.<span class=\"o-gl\">❌ ❌</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u7q10\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">집<b class=\"hl\">에서</b> 밥을 먹어요 — 먹다 (to eat) is an action, so the place takes <b class=\"hl\">에서</b>. The meaning is \"I <b class=\"hl\">eat rice</b> at home.\"</div><div style=\"margin-bottom:5px;\">This is different from \"집에 있어요\" (the state of being at home). If there's an action verb use <b class=\"hl\">에서</b>; if the verb is 있어요 use <b class=\"hl\">에</b>!</div></div></div></div>\n</div>"}, {"cls": "culture", "html": "<div class=\"culture\">\n    <span class=\"c-label\">🎤 K-POP TIP</span>\n    <h3>Places Idols Go</h3>\n    <p><b>Music shows</b> (Music Bank, Inkigayo, M Countdown!), <b>concert halls</b>, <b>fan sign events</b> — an idol's day is all about moving between places!</p>\n    <div class=\"c-tip\">🚇 \"음악방송에 어떻게 가요?\" (How do you get to the music show?) — By subway! Transportation comes in 1B!</div>\n  </div>\n\n<!-- ============================================================\n     UNIT 8 — PAST TENSE\n     ============================================================ -->"}]}, {"id": 8, "sections": [{"cls": "unit-flag", "html": "<div class=\"unit-flag\">UNIT 8 · PAST TENSE</div>\n  "}, {"cls": "sec-title", "html": "<div class=\"sec-title\"><div class=\"no\">8</div><div><h2>What Did You Do Yesterday?</h2><div class=\"en\">어제 뭐 했어요? — Past tense · -았/었어요</div></div></div>\n  "}, {"cls": "story", "html": "<div class=\"story\">\n    <img class=\"story-art\" src=\"assets/glowsis/roy.png\" alt=\"로이\">\n    <div class=\"story-body\">\n      <span class=\"story-tag\">💿 GLOWSIS STORY · 8/8</span>\n      <h3>마지막 GLOW POINT — \"어제 뭐 했어요?\"</h3>\n      <p>드디어 마지막 포인트! 네 명은 <b>과거 시제</b>로 데뷔 무대의 추억을 이야기해요. \"어제 노래를 불렀어요!\" — 여덟 번째 포인트가 모이면... 데뷔 완성! ✨</p>\n      <span class=\"story-piece\">✨ GLOW POINT 8/8 — DEBUT COMPLETE! → 1B로 계속!</span>\n    </div>\n  </div>\n"}, {"cls": "goals", "html": "<div class=\"goals\">\n    <div class=\"goal\"><span class=\"g-ico\">⏪</span> -았/었어요 past tense</div>\n    <div class=\"goal\"><span class=\"g-ico\">📝</span> Writing a diary</div>\n    <div class=\"goal\"><span class=\"g-ico\">🎤</span> Life after debut</div>\n  </div>\n\n  "}, {"cls": "dialog", "html": "<div class=\"dialog\">\n    <div class=\"d-head\">\n      <span class=\"d-title\">💬 Dialogue 8 — The Day After Debut</span>\n      <span class=\"d-scene\">🌅 Morning at the dorm</span>\n    </div>\n    <div class=\"d-line\"><img src=\"assets/glowsis/dahee.png\" alt=\"다희\">\n      <div class=\"d-bubble\"><div class=\"who\">다희</div><div class=\"ko\">어제 정말 재미있었어요! 데뷔 무대, 최고였어요!</div><div class=\"gl\">Yesterday was really fun! The debut stage was the best!</div></div>\n    </div>\n    <div class=\"d-line\"><img src=\"assets/glowsis/chaea.png\" alt=\"채아\">\n      <div class=\"d-bubble\"><div class=\"who\">채아</div><div class=\"ko\">팬들이 많았어요. 저는 정말 감동했어요.</div><div class=\"gl\">There were so many fans. I was really touched.</div></div>\n    </div>\n    <div class=\"d-line me\"><img src=\"assets/glowsis/aran.png\" alt=\"아란\">\n      <div class=\"d-bubble\"><div class=\"who\">아란</div><div class=\"ko\">우리 노래를 다 같이 불렀어요! 오늘도 힘내요!</div><div class=\"gl\">We all sang our song together! Let's do our best today too!</div></div>\n    </div>\n    <div class=\"d-line\"><img src=\"assets/glowsis/roy.png\" alt=\"로이\">\n      <div class=\"d-bubble\"><div class=\"who\">로이</div><div class=\"ko\">저는 어제 치킨을 먹었어요. 맛있었어요!</div><div class=\"gl\">I ate fried chicken yesterday. It was delicious!</div></div>\n    </div>\n  </div>\n\n  "}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">GRAMMAR 1</span>\n    <div class=\"g-point\">-았/었어요 — Past Tense</div>\n    <div class=\"g-rule\">Change present <b>-아요/어요</b> to <b>-았어요/었어요</b>! After ㅏ/ㅗ → 았어요, otherwise → 었어요, 하다 → 했어요.</div>\n    <div class=\"g-ex\">\n      <div class=\"ex\"><span class=\"ko\">먹<b>다</b> → 먹<b>었어요</b></span><span class=\"gl\">ate</span></div>\n      <div class=\"ex\"><span class=\"ko\">하<b>다</b> → <b>했어요</b></span><span class=\"gl\">did</span></div>\n      <div class=\"ex\"><span class=\"ko\">재미있<b>다</b> → 재미있<b>었어요</b></span><span class=\"gl\">was fun</span></div>\n      <div class=\"ex\"><span class=\"ko\">가<b>다</b> → 갔어요</span><span class=\"gl\">went</span></div>\n    </div>\n  </div>\n\n  "}, {"cls": "teach", "html": "<div class=\"teach\">\n  <span class=\"t-label\">🧑‍🏫 Teacher's Deep-Dive · The Past Tense -았/었어요 — Why “어제 노래를 불렀어요”?</span>\n  <div class=\"t-q\"><span class=\"t-ko\">어제 뭐 했어요?</span> <span class=\"t-en\">= “What did you do yesterday?”</span></div>\n\n  <div class=\"t-row t-head\">\n    <div class=\"t-why\">How do I turn the present tense into the past? — Just look at the last vowel!</div>\n    <div class=\"t-deep\">\n      The “-아요/어요” you learned means <b>now</b>. Things you did yesterday are <b>finished</b>, so you add <b>ㅆ</b> (double siot) and switch to “-았/었어요”.<br>\n      There are only two rules: a stem ending in <b>ㅏ/ㅗ</b> takes <b>았</b>, and any other vowel takes <b>었</b>. And 하다 is always <b>했</b>!\n    </div>\n  </div>\n\n  <div class=\"t-grid\">\n    <div class=\"t-cell t-qcell\">\n      <div class=\"t-word\">먹다</div>\n      <div class=\"t-role\">eat <span class=\"t-sub\">(vowel ㅓ — not ㅏ/ㅗ)</span></div>\n      <div class=\"t-note\">not ㅏ/ㅗ → <b class=\"hl\">었</b><br>먹 + 었 → <b>먹었어요</b></div>\n    </div>\n    <div class=\"t-op\">+</div>\n    <div class=\"t-cell\">\n      <div class=\"t-word\">가다</div>\n      <div class=\"t-role\">go <span class=\"t-sub\">(vowel ㅏ)</span></div>\n      <div class=\"t-note\">ㅏ/ㅗ → <b class=\"hl\">았</b><br>가 + 았 → <b>갔어요</b></div>\n    </div>\n    <div class=\"t-op\">+</div>\n    <div class=\"t-cell\">\n      <div class=\"t-word\">보다</div>\n      <div class=\"t-role\">watch <span class=\"t-sub\">(vowel ㅗ)</span></div>\n      <div class=\"t-note\">ㅗ → <b class=\"hl\">았</b><br>보 + 았 → <b>봤어요</b></div>\n    </div>\n    <div class=\"t-op\">+</div>\n    <div class=\"t-cell t-eqcell\">\n      <div class=\"t-word\">하다</div>\n      <div class=\"t-role\">do <span class=\"t-sub\">(always the exception!)</span></div>\n      <div class=\"t-note\">하다 is always <b class=\"hl\">했</b><br>쇼핑하다 → <b>쇼핑했어요</b></div>\n    </div>\n  </div>\n\n  <div class=\"t-insight\">\n    <b class=\"t-i-ko\">That's why we say “어제 노래를 불렀어요”!</b> The stem of 부르다 is ‘부르’, and ㅜ is not ㅏ/ㅗ → <b>불렀어요</b>. Today (present) you'd say “노래를 불러요”, but yesterday (past) it's “노래를 불렀어요”.\n    All 하다 verbs (쇼핑하다 · 감동하다 · 힘내다) squeeze into one ‘했/냈’ too: <b>쇼핑했어요 · 감동했어요 · 힘냈어요</b>.\n  </div>\n\n  <div class=\"t-compare\">\n    <div class=\"t-c-a\"><b>오늘 (now · present)</b><br><span class=\"t-ko\">노래를 불러요 · 영화를 봐요 · 공원에 가요</span><br><span class=\"t-en\">“-아요/어요” — what I'm doing now</span></div>\n    <div class=\"t-c-b\"><b>어제 (past · finished)</b><br><span class=\"t-ko\">노래를 불렀어요 · 영화를 봤어요 · 공원에 갔어요</span><br><span class=\"t-en\">“-았/었어요” — already done ✨</span></div>\n  </div>\n\n  <div class=\"t-tip\">\n    💡 <b>Memory tip:</b> when you hear “어제 뭐 했어요?”, always answer with <b>-았/었어요</b>! Look at the vowel: 가다 · 오다 · 사다 (ㅏ) and 보다 · 놀다 (ㅗ) take 앗, everything else (ㅓ/ㅣ/ㅜ/ㅡ) takes 었. And memorize 하다: <b>했다!</b>\n  </div>\n</div>"}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">GRAMMAR 2</span>\n    <div class=\"g-point\">Time Expressions — 어제/오늘/내일</div>\n    <div class=\"g-rule\">TOPIK I listening always asks \"when?\" Combine time expressions with the past tense!</div>\n    <div class=\"g-ex\">\n      <div class=\"ex\"><span class=\"ko\">어제 뭐 했어요?</span><span class=\"gl\">What did you do yesterday?</span></div>\n      <div class=\"ex\"><span class=\"ko\">어제 쇼핑했어요.</span><span class=\"gl\">I went shopping yesterday.</span></div>\n      <div class=\"ex\"><span class=\"ko\">내일 뭐 해요?</span><span class=\"gl\">What are you doing tomorrow?</span></div>\n    </div>\n  </div>\n\n    "}, {"cls": "grammar", "html": "<div class=\"grammar\">\n    <span class=\"g-label\">GRAMMAR 3</span>\n    <div class=\"g-point\">안 + past — \"didn't ~\"</div>\n    <div class=\"g-rule\">Negate the past tense: <b>안</b> + verb (past form). Compare: 했어요 (did) vs 안 했어요 (didn't do).</div>\n    <div class=\"g-ex\">\n      <div class=\"ex\"><span class=\"ko\">어제 공부를 <b>안 했어요</b>.</span><span class=\"gl\">I didn't study yesterday.</span></div>\n      <div class=\"ex\"><span class=\"ko\">아침을 <b>안 먹었어요</b>.</span><span class=\"gl\">I didn't eat breakfast.</span></div>\n      <div class=\"ex\"><span class=\"ko\">음악방송에 <b>안 갔어요</b>.</span><span class=\"gl\">I didn't go to the music show.</span></div>\n    </div>\n  </div>\n\n"}, {"cls": "vocab-grid", "html": "<div class=\"vocab-lab\"><div class=\"vl-toolbar\"><span class=\"vl-hint\">카테고리를 눌러 그림과 함께 공부하세요 — 과거 시제로 말해 봐요!</span><button class=\"vl-expand\" onclick=\"glowVocabAll()\">모두 펼치기</button></div><div class=\"vl-cat open\" data-tone=\"pink\"><button class=\"vl-cat-head\" onclick=\"glowVocab(this)\"><span class=\"vl-cat-ico\">⏰</span><span class=\"vl-cat-name\">시간 말하기<small>Time words · 어제/오늘/내일</small></span><span class=\"vl-cat-count\">3</span><span class=\"vl-cat-arr\">▾</span></button><div class=\"vl-cat-body\"><div class=\"vw-grid\"><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u8_yesterday.webp\" alt=\"어제\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('어제')\">🔊</button><div class=\"vw-ko\">어제</div><div class=\"vw-rom\">eoje</div><div class=\"vw-en\">yesterday</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u8_today.webp\" alt=\"오늘\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('오늘')\">🔊</button><div class=\"vw-ko\">오늘</div><div class=\"vw-rom\">oneul</div><div class=\"vw-en\">today</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u8_tomorrow.webp\" alt=\"내일\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('내일')\">🔊</button><div class=\"vw-ko\">내일</div><div class=\"vw-rom\">naeil</div><div class=\"vw-en\">tomorrow</div></div></div></div><div class=\"vs-box\"><div class=\"vs-head\">💬 이 단어로 자주 쓰는 말</div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('어제 뭐 했어요?')\">🔊</button><div><span class=\"vs-ko\">어제 뭐 했어요?</span> <span class=\"vs-en\">What did you do yesterday?</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('오늘은 아주 바빠요.')\">🔊</button><div><span class=\"vs-ko\">오늘은 아주 바빠요.</span> <span class=\"vs-en\">I'm very busy today.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('내일 또 만나요!')\">🔊</button><div><span class=\"vs-ko\">내일 또 만나요!</span> <span class=\"vs-en\">See you again tomorrow!</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('어제 공원에 갔어요.')\">🔊</button><div><span class=\"vs-ko\">어제 공원에 갔어요.</span> <span class=\"vs-en\">I went to the park yesterday.</span></div></div></div><div class=\"vl-link\">⏰ <b>시제의 기준점:</b> <b>어제</b>(과거, 지나감) ↔ <b>오늘</b>(지금) ↔ <b>내일</b>(미래, 아직 안 옴). “어제 뭐 했어요?” 물으면 과거형 -았/었어요로 답해요!</div></div></div><div class=\"vl-cat\" data-tone=\"mint\"><button class=\"vl-cat-head\" onclick=\"glowVocab(this)\"><span class=\"vl-cat-ico\">🎬</span><span class=\"vl-cat-name\">주말 활동<small>Weekend fun · 영화/쇼핑/드라마/파티</small></span><span class=\"vl-cat-count\">4</span><span class=\"vl-cat-arr\">▾</span></button><div class=\"vl-cat-body\"><div class=\"vw-grid\"><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u8_movie.webp\" alt=\"영화\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('영화')\">🔊</button><div class=\"vw-ko\">영화</div><div class=\"vw-rom\">yeonghwa</div><div class=\"vw-en\">movie</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u8_shopping.webp\" alt=\"쇼핑\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('쇼핑')\">🔊</button><div class=\"vw-ko\">쇼핑</div><div class=\"vw-rom\">syoping</div><div class=\"vw-en\">shopping</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u8_drama.webp\" alt=\"드라마\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('드라마')\">🔊</button><div class=\"vw-ko\">드라마</div><div class=\"vw-rom\">deurama</div><div class=\"vw-en\">drama</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u8_party.webp\" alt=\"파티\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('파티')\">🔊</button><div class=\"vw-ko\">파티</div><div class=\"vw-rom\">pati</div><div class=\"vw-en\">party</div></div></div></div><div class=\"vs-box\"><div class=\"vs-head\">💬 이 단어로 자주 쓰는 말</div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('어제 영화를 봤어요.')\">🔊</button><div><span class=\"vs-ko\">어제 영화를 봤어요.</span> <span class=\"vs-en\">I watched a movie yesterday.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('주말에 쇼핑했어요.')\">🔊</button><div><span class=\"vs-ko\">주말에 쇼핑했어요.</span> <span class=\"vs-en\">I went shopping on the weekend.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('어젯밤에 드라마를 봤어요.')\">🔊</button><div><span class=\"vs-ko\">어젯밤에 드라마를 봤어요.</span> <span class=\"vs-en\">I watched a drama last night.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('어제 파티에 갔어요.')\">🔊</button><div><span class=\"vs-ko\">어제 파티에 갔어요.</span> <span class=\"vs-en\">I went to a party yesterday.</span></div></div></div><div class=\"vl-link\">🎬 <b>같이 쓰는 말:</b> 영화·드라마는 <b>보다</b>(→봤어요), 쇼핑은 <b>하다</b>(→했어요), 파티는 <b>가다</b>(→갔어요). 전부 과거에 하면 -았/었어요!</div></div></div><div class=\"vl-cat\" data-tone=\"sky\"><button class=\"vl-cat-head\" onclick=\"glowVocab(this)\"><span class=\"vl-cat-ico\">❤️</span><span class=\"vl-cat-name\">느낌 & 응원<small>Feelings · 재미있다/감동하다/힘내다</small></span><span class=\"vl-cat-count\">3</span><span class=\"vl-cat-arr\">▾</span></button><div class=\"vl-cat-body\"><div class=\"vw-grid\"><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u8_fun.webp\" alt=\"재미있다\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('재미있어요')\">🔊</button><div class=\"vw-ko\">재미있다</div><div class=\"vw-rom\">jaemiitda</div><div class=\"vw-en\">fun, interesting</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u8_moved.webp\" alt=\"감동하다\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('감동했어요')\">🔊</button><div class=\"vw-ko\">감동하다</div><div class=\"vw-rom\">gamdonghada</div><div class=\"vw-en\">to be moved</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u8_cheer.webp\" alt=\"힘내다\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('힘내요')\">🔊</button><div class=\"vw-ko\">힘내다</div><div class=\"vw-rom\">himnaeda</div><div class=\"vw-en\">cheer up</div></div></div></div><div class=\"vs-box\"><div class=\"vs-head\">💬 이 단어로 자주 쓰는 말</div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('어제 정말 재미있었어요!')\">🔊</button><div><span class=\"vs-ko\">어제 정말 재미있었어요!</span> <span class=\"vs-en\">Yesterday was really fun!</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('팬들이 정말 감동했어요.')\">🔊</button><div><span class=\"vs-ko\">팬들이 정말 감동했어요.</span> <span class=\"vs-en\">The fans were really moved.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('오늘도 힘내요!')\">🔊</button><div><span class=\"vs-ko\">오늘도 힘내요!</span> <span class=\"vs-en\">Let's cheer up today too!</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('데뷔 무대, 최고였어요!')\">🔊</button><div><span class=\"vs-ko\">데뷔 무대, 최고였어요!</span> <span class=\"vs-en\">The debut stage was the best!</span></div></div></div><div class=\"vl-link\">❤️ <b>마음 표현:</b> 재미있<b>다</b>는 형용사 → <b>재미있었어요</b>(fun→was fun). 감동하다·힘내다 같은 ‘하다 동사’는 → <b>감동했어요·힘냈어요</b>!</div></div></div><div class=\"vl-cat\" data-tone=\"lav\"><button class=\"vl-cat-head\" onclick=\"glowVocab(this)\"><span class=\"vl-cat-ico\">📍</span><span class=\"vl-cat-name\">갈 수 있는 곳<small>Places · 공원/시장/은행</small></span><span class=\"vl-cat-count\">3</span><span class=\"vl-cat-arr\">▾</span></button><div class=\"vl-cat-body\"><div class=\"vw-grid\"><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u8_park.webp\" alt=\"공원\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('공원')\">🔊</button><div class=\"vw-ko\">공원</div><div class=\"vw-rom\">gongwon</div><div class=\"vw-en\">park</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u8_market.webp\" alt=\"시장\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('시장')\">🔊</button><div class=\"vw-ko\">시장</div><div class=\"vw-rom\">sijang</div><div class=\"vw-en\">market</div></div></div><div class=\"vw-card\"><div class=\"vw-pic\"><img src=\"assets/vocab/u8_bank.webp\" alt=\"은행\"></div><div class=\"vw-info\"><button class=\"vw-tts\" onclick=\"tts('은행')\">🔊</button><div class=\"vw-ko\">은행</div><div class=\"vw-rom\">eunhaeng</div><div class=\"vw-en\">bank</div></div></div></div><div class=\"vs-box\"><div class=\"vs-head\">💬 이 단어로 자주 쓰는 말</div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('공원에서 산책했어요.')\">🔊</button><div><span class=\"vs-ko\">공원에서 산책했어요.</span> <span class=\"vs-en\">I took a walk in the park.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('어제 시장에 갔어요.')\">🔊</button><div><span class=\"vs-ko\">어제 시장에 갔어요.</span> <span class=\"vs-en\">I went to the market yesterday.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('은행에서 돈을 찾았어요.')\">🔊</button><div><span class=\"vs-ko\">은행에서 돈을 찾았어요.</span> <span class=\"vs-en\">I withdrew money at the bank.</span></div></div><div class=\"vs-line\"><button class=\"vs-tts\" onclick=\"tts('시장에서 야채를 샀어요.')\">🔊</button><div><span class=\"vs-ko\">시장에서 야채를 샀어요.</span> <span class=\"vs-en\">I bought vegetables at the market.</span></div></div></div><div class=\"vl-link\">📍 <b>장소 + 에 가요:</b> 공원<b>에</b> 가요 · 시장<b>에</b> 가요 · 은행<b>에</b> 가요. 과거엔 전부 <b>갔어요</b>로 통일!</div></div></div></div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n  <div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[8-1] Reading — “가다”를 과거로</span></div>\n  <div class=\"p-dir\">Choose the correct past tense.</div>\n  <div class=\"p-q\">None</div>\n  <div class=\"opts\" data-q=\"u8q1\">\n      <button class=\"opt\" onclick=\"checkQ('u8q1',1,this)\"><span class=\"o-idx\">1</span>공원에 (     ).<span class=\"o-gl\">❌ present</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q1',1,this)\"><span class=\"o-idx\">2</span>공원에 갔어요.<span class=\"o-gl\">✅ ㅏ→갔어요 (went)</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q1',1,this)\"><span class=\"o-idx\">3</span>공원에 가요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q1',1,this)\"><span class=\"o-idx\">4</span>공원에 갈 거예요.<span class=\"o-gl\">❌ future</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u8q1\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\"><b class=\"hl\">가다</b> has the vowel <b class=\"hl\">ㅏ</b>, so we add 았: <span class=\"pt-ko\">가 + 았 → 갔어요</span>.</div><div style=\"margin-bottom:5px;\">⓪ Present <b class=\"hl\">가요</b> (going now) ↔ past <b class=\"hl\">갔어요</b> (already went). “갈 거예요” is future, so it doesn't fit a sentence about yesterday.</div><div style=\"margin-bottom:5px;\">💡 Verbs that end in <b class=\"hl\">ㅏ/ㅗ</b>, like 가다 · 오다 · 사다, take 았!</div></div></div></div>\n</div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n  <div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[8-2] Reading — “쇼핑하다” 과거</span></div>\n  <div class=\"p-dir\">Choose the correct past tense.</div>\n  <div class=\"p-q\">None</div>\n  <div class=\"opts\" data-q=\"u8q2\">\n      <button class=\"opt\" onclick=\"checkQ('u8q2',1,this)\"><span class=\"o-idx\">1</span>어제 쇼핑해요.<span class=\"o-gl\">❌ present</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q2',1,this)\"><span class=\"o-idx\">2</span>어제 쇼핑했어요.<span class=\"o-gl\">✅ 하다→했어요 (shopped)</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q2',1,this)\"><span class=\"o-idx\">3</span>어제 쇼핑할 거예요.<span class=\"o-gl\">❌ future</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q2',1,this)\"><span class=\"o-idx\">4</span>어제 쇼핑 안 해요.<span class=\"o-gl\">❌ present negative</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u8q2\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">쇼핑하다 is a <b class=\"hl\">하다 verb</b> → the past ALWAYS adds <b class=\"hl\">했</b>: <span class=\"pt-ko\">쇼핑했어요</span>.</div><div style=\"margin-bottom:5px;\">⓪ “해요” = now, “할 거예요” = future, “안 해요” = not now — for yesterday (past) it's <b class=\"hl\">했어요</b>!</div><div style=\"margin-bottom:5px;\">💡 <b class=\"hl\">~하다 → ~했어요</b>: 공부하다 · 운동하다 · 쇼핑하다 all follow the same rule.</div></div></div></div>\n</div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n  <div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[8-3] Reading — “안 했어요” (부정 과거)</span></div>\n  <div class=\"p-dir\">Choose the correct negative past tense.</div>\n  <div class=\"p-q\">None</div>\n  <div class=\"opts\" data-q=\"u8q3\">\n      <button class=\"opt\" onclick=\"checkQ('u8q3',1,this)\"><span class=\"o-idx\">1</span>어제 영화를 안 봐요.<span class=\"o-gl\">❌ present negative</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q3',1,this)\"><span class=\"o-idx\">2</span>어제 영화를 안 봤어요.<span class=\"o-gl\">✅ didn’t watch</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q3',1,this)\"><span class=\"o-idx\">3</span>어제 영화를 봤어요.<span class=\"o-gl\">❌ positive</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q3',1,this)\"><span class=\"o-idx\">4</span>어제 영화를 볼 거예요.<span class=\"o-gl\">❌ future</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u8q3\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">Negative past tense = <span class=\"pt-ko\">안 + (past form)</span>: put 안 before the past of 보다, <b class=\"hl\">봤어요</b> → <b class=\"hl\">안 봤어요</b>.</div><div style=\"margin-bottom:5px;\">⓪ “안 봐요” means I'm not watching now, so it doesn't fit yesterday. If you did watch → 봤어요, if not → 안 봤어요!</div><div style=\"margin-bottom:5px;\">💡 To make a negative, use <b class=\"hl\">안 + verb</b>. If it's past, the verb is past too: <b class=\"hl\">안 먹었어요 · 안 갔어요</b>.</div></div></div></div>\n</div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n  <div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[8-4] Listening — 어제 뭐 했어요?</span></div>\n  <div class=\"p-dir\">🔊 Listen and choose what you hear.</div>\n  <button class=\"p-audio\" onclick=\"tts('어제 영화를 봤어요. 그리고 공원에 갔어요.')\">🔊 Listen</button>\n  <div class=\"opts\" data-q=\"u8q4\">\n      <button class=\"opt\" onclick=\"checkQ('u8q4',0,this)\"><span class=\"o-idx\">1</span>영화를 봤어요.<span class=\"o-gl\">✅ watched a movie</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q4',0,this)\"><span class=\"o-idx\">2</span>영화를 만들었어요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q4',0,this)\"><span class=\"o-idx\">3</span>영화를 안 봤어요.<span class=\"o-gl\">❌ negative</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q4',0,this)\"><span class=\"o-idx\">4</span>영화를 볼 거예요.<span class=\"o-gl\">❌ future</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u8q4\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">Audio: <span class=\"pt-ko\">어제 영화를 봤어요</span> + <span class=\"pt-ko\">공원에 갔어요</span>. The key part is “영화를 <b class=\"hl\">봤어요</b>”.</div><div style=\"margin-bottom:5px;\">⓪ “만들었어요” (만들다), “안 봤어요” (negative), “볼 거예요” (future) — none match what you heard.</div><div style=\"margin-bottom:5px;\">💡 In listening, first catch the <b class=\"hl\">ㅆ</b> sound at the end of the verb — 봤어요 / 갔어요!</div></div></div></div>\n</div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n  <div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[8-5] Listening — 주말에 뭐 했어요?</span></div>\n  <div class=\"p-dir\">🔊 Listen and choose what you hear.</div>\n  <button class=\"p-audio\" onclick=\"tts('주말에 드라마를 봤어요. 정말 재미있었어요.')\">🔊 Listen</button>\n  <div class=\"opts\" data-q=\"u8q5\">\n      <button class=\"opt\" onclick=\"checkQ('u8q5',0,this)\"><span class=\"o-idx\">1</span>주말에 드라마를 봤어요.<span class=\"o-gl\">✅ watched a drama</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q5',0,this)\"><span class=\"o-idx\">2</span>주말에 시장에 갔어요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q5',0,this)\"><span class=\"o-idx\">3</span>주말에 드라마를 안 봤어요.<span class=\"o-gl\">❌ negative</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q5',0,this)\"><span class=\"o-idx\">4</span>주말에 파티를 했어요.<span class=\"o-gl\">❌</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u8q5\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">Audio: <span class=\"pt-ko\">드라마를 봤어요. 정말 재미있었어요.</span> → Roy watched a drama.</div><div style=\"margin-bottom:5px;\">⓪ 시장, 파티, and the negative were never said. 재미있<b>었</b>어요 is the past of 재미있다!</div><div style=\"margin-bottom:5px;\">💡 <b class=\"hl\">재미있다 → 재미있었어요</b> (was fun). Adjectives use the past tense too.</div></div></div></div>\n</div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n  <div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[8-6] Reading — “내일” 문장 찾기</span></div>\n  <div class=\"p-dir\">시간을 나타내는 말 ‘내일’이 들어간 문장을 고르세요.</div>\n  <div class=\"p-q\">None</div>\n  <div class=\"opts\" data-q=\"u8q6\">\n      <button class=\"opt\" onclick=\"checkQ('u8q6',0,this)\"><span class=\"o-idx\">1</span>내일 영화를 볼 거예요.<span class=\"o-gl\">✅ ‘내일’ = tomorrow</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q6',0,this)\"><span class=\"o-idx\">2</span>어제 영화를 봤어요.<span class=\"o-gl\">❌ ‘어제’ = yesterday</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q6',0,this)\"><span class=\"o-idx\">3</span>오늘 영화를 봐요.<span class=\"o-gl\">❌ ‘오늘’ = today</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q6',0,this)\"><span class=\"o-idx\">4</span>지금 영화를 봐요.<span class=\"o-gl\">❌ ‘지금’ = now</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u8q6\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">내일 means <b class=\"hl\">tomorrow</b> (future). It hasn't come yet, so it's a perfect match with <span class=\"pt-ko\">~ㄹ 거예요</span> (future).</div><div style=\"margin-bottom:5px;\">⓪ “어제” = past (봤어요), “오늘 · 지금” = present (봐요). The verb tense changes with the time word.</div><div style=\"margin-bottom:5px;\">💡 <b class=\"hl\">어제 → past · 오늘 → present · 내일 → future</b> — a must-know set for TOPIK!</div></div></div></div>\n</div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n  <div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[8-7] Listening — 팬들의 마음</span></div>\n  <div class=\"p-dir\">🔊 Listen and choose what you hear.</div>\n  <button class=\"p-audio\" onclick=\"tts('팬들이 정말 감동했어요. 노래가 최고였어요.')\">🔊 Listen</button>\n  <div class=\"opts\" data-q=\"u8q7\">\n      <button class=\"opt\" onclick=\"checkQ('u8q7',0,this)\"><span class=\"o-idx\">1</span>팬들이 정말 감동했어요.<span class=\"o-gl\">✅ fans were moved</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q7',0,this)\"><span class=\"o-idx\">2</span>팬들이 정말 재미있었어요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q7',0,this)\"><span class=\"o-idx\">3</span>팬들이 정말 힘내요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q7',0,this)\"><span class=\"o-idx\">4</span>팬들이 정말 싫어했어요.<span class=\"o-gl\">❌</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u8q7\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">Audio: <span class=\"pt-ko\">팬들이 정말 감동했어요</span>. The past of 감동하다 is <b class=\"hl\">감동했어요</b>.</div><div style=\"margin-bottom:5px;\">⓪ “재미있었어요” fits an activity or movie; “감동했어요” fits when your heart is moved. Don't mix them up!</div><div style=\"margin-bottom:5px;\">💡 Past of a 하다 verb: <b class=\"hl\">감동하다 → 감동했어요</b>. Like 쇼핑하다, they all take 했!</div></div></div></div>\n</div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n  <div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[8-8] Reading — 어디에 갔어요?</span></div>\n  <div class=\"p-dir\">은행에서 돈을 찾았어요. 로이는 어제 어디에 갔을까요?</div>\n  <div class=\"p-q\">None</div>\n  <div class=\"opts\" data-q=\"u8q8\">\n      <button class=\"opt\" onclick=\"checkQ('u8q8',0,this)\"><span class=\"o-idx\">1</span>은행에 갔어요.<span class=\"o-gl\">✅ went to the bank</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q8',0,this)\"><span class=\"o-idx\">2</span>공원에 갔어요.<span class=\"o-gl\">❌ park</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q8',0,this)\"><span class=\"o-idx\">3</span>시장에 갔어요.<span class=\"o-gl\">❌ market</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q8',0,this)\"><span class=\"o-idx\">4</span>영화관에 갔어요.<span class=\"o-gl\">❌ cinema</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u8q8\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">The place where you <b class=\"hl\">withdraw money</b> is <span class=\"pt-ko\">은행</span>! → “은행에 <b class=\"hl\">갔어요</b>”.</div><div style=\"margin-bottom:5px;\">⓪ The park (walking), the market (shopping), and the cinema (movies) don't fit “withdrawing money”.</div><div style=\"margin-bottom:5px;\">💡 Learn place words together with <b class=\"hl\">~에 가다</b>: 은행에 가요 · 시장에 가요.</div></div></div></div>\n</div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n  <div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[8-9] Reading — “재미있다” 과거</span></div>\n  <div class=\"p-dir\">Choose the correct past form of the adjective.</div>\n  <div class=\"p-q\">None</div>\n  <div class=\"opts\" data-q=\"u8q9\">\n      <button class=\"opt\" onclick=\"checkQ('u8q9',1,this)\"><span class=\"o-idx\">1</span>어제 파티가 재미있어요.<span class=\"o-gl\">❌ present</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q9',1,this)\"><span class=\"o-idx\">2</span>어제 파티가 재미있었어요.<span class=\"o-gl\">✅ was fun</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q9',1,this)\"><span class=\"o-idx\">3</span>어제 파티가 재미있을 거예요.<span class=\"o-gl\">❌ future</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q9',1,this)\"><span class=\"o-idx\">4</span>어제 파티가 재미없어요.<span class=\"o-gl\">❌ ‘없다’</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u8q9\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\"><b class=\"hl\">재미있다 → 재미있었어요</b> (was fun). Yesterday's party is already over, so we use the past tense!</div><div style=\"margin-bottom:5px;\">⓪ “재미있어요” = now, “재미있을 거예요” = future, “재미없어요” = 재미없다 (the opposite word).</div><div style=\"margin-bottom:5px;\">💡 The past of “있다” is “<b class=\"hl\">있었어요</b>”: 재미있다 → 재미있<b>었</b>어요.</div></div></div></div>\n</div>"}, {"cls": "practice", "html": "<div class=\"practice\">\n  <div class=\"p-head\"><span class=\"p-badge\">TOPIK TYPE</span><span class=\"p-title\">[8-10] Listening — 데뷔 다음 날</span></div>\n  <div class=\"p-dir\">🔊 Listen and choose what you hear.</div>\n  <button class=\"p-audio\" onclick=\"tts('다희: 어제 정말 재미있었어요! 로이: 저는 어제 치킨을 먹었어요. 맛있었어요!')\">🔊 Listen</button>\n  <div class=\"opts\" data-q=\"u8q10\">\n      <button class=\"opt\" onclick=\"checkQ('u8q10',0,this)\"><span class=\"o-idx\">1</span>로이는 어제 치킨을 먹었어요.<span class=\"o-gl\">✅ Roy ate chicken</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q10',0,this)\"><span class=\"o-idx\">2</span>로이는 어제 파티를 했어요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q10',0,this)\"><span class=\"o-idx\">3</span>로이는 어제 노래를 불렀어요.<span class=\"o-gl\">❌</span></button>\n      <button class=\"opt\" onclick=\"checkQ('u8q10',0,this)\"><span class=\"o-idx\">4</span>로이는 어제 감동했어요.<span class=\"o-gl\">❌</span></button>\n  </div>\n  <div class=\"p-feedback\" id=\"fb-u8q10\"></div>\n  <div class=\"pt-note\"><div class=\"pt-note-head\">🧑‍🏫 선생님 노트 · 문제 해설</div><div class=\"pt-note-body\"><div style=\"margin-bottom:5px;\">Roy's words: <span class=\"pt-ko\">어제 치킨을 먹었어요. 맛있었어요</span>. → Roy <b class=\"hl\">먹었어요</b> (ate) chicken.</div><div style=\"margin-bottom:5px;\">⓪ Dahi said “재미있었어요”, but the question asks about <b class=\"hl\">Roy</b>. Read who is being asked!</div><div style=\"margin-bottom:5px;\">💡 In listening questions, first check WHO is talking — that way you won't fall for the trap (Dahi)!</div></div></div></div>\n</div>"}, {"cls": "culture", "html": "<div class=\"culture\">\n    <span class=\"c-label\">🎤 K-POP TIP</span>\n    <h3>Diary Writing Challenge</h3>\n    <p>Idols write diaries too! Write about your day using the <b>past tense</b>.</p>\n    <div class=\"c-tip\">✍️ \"오늘 한국어를 공부했어요. 노래를 들었어요. 정말 재미있었어요!\" — Complete a 3-sentence diary!</div>\n  </div>\n\n</div>"}]}];